(window.TRENER_PACKS=window.TRENER_PACKS||{})["neorganika-reakcii-6-9-31"]={"id": "neorganika-reakcii-6-9-31", "subject": "Химия", "title": "Неорганика металлов и неметаллов: задания № 6–9 и № 31 ЕГЭ", "version": "26.11.2026", "konspekt": "neorganika-reakcii-6-9-31", "codes": ["2.2", "2.3", "2.4"], "kod": {"p": [{"id": "p1", "t": "Четыре движущие силы и металлургия по ряду напряжений", "x": "Неорганические реакции в ЕГЭ сводятся к четырём типам: кислотно-основные, ОВР, реакции ионного обмена (осадок/газ/слабый электролит) и комплексообразование. Металлы до Al получают только электролизом расплавов, средние (Zn–Pb) — восстановлением C/CO/H2/Al или электролизом, малоактивные (Cu–Au) — пиро- и гидрометаллургией.", "ref": "01.1"}, {"id": "p2", "t": "Активные металлы (Na, K, Ca, Mg), пероксиды и кислые соли", "x": "Щелочные и щёлочноземельные металлы — сильнейшие восстановители: с водой реагируют при н.у. (Mg — только с горячей водой или паром), а из водных растворов солей другие металлы не вытесняют. В O2 литий даёт Li2O, натрий — Na2O2, калий — KO2. Кислые соли слабых кислот (NaHCO3) амфотерны, а NaHSO4 ведёт себя как кислота.", "ref": "02.1"}, {"id": "p3", "t": "Амфотерность Al и Zn: раствор vs сплавление", "x": "Al, Zn и их оксиды/гидроксиды реагируют и с кислотами, и со щелочами: в водном растворе образуются гидроксокомплексы Na[Al(OH)4] и Na2[Zn(OH)4], при сплавлении — средние соли NaAlO2 и Na2ZnO2. Слабые кислоты и кислые газы (CO2, SO2, H2S) разрушают комплексы строго до осадка гидроксида и кислой соли.", "ref": "03.1"}, {"id": "p4", "t": "Переходные металлы (Fe, Cr, Mn, Cu): смена СО и пассивация", "x": "С ростом степени окисления характер соединений меняется от основного к амфотерному и кислотному (CrO → Cr2O3 → CrO3). Сильные окислители (Cl2, Br2, HNO3, горячая конц. H2SO4) переводят Fe в +3, а HCl, H2SO4(разб.), S и I2 — в +2. Fe, Al и Cr пассивируются холодными концентрированными HNO3 и H2SO4.", "ref": "04.1"}, {"id": "p5", "t": "Галогены: ряд окислителей, щёлочи и конц. H2SO4", "x": "В ряду F2 → Cl2 → Br2 → I2 окислительная активность падает, а восстановительная способность галогенидов (F⁻ → I⁻) растёт. Cl2 и Br2 диспропорционируют в холодной щёлочи до гипогалогенитов (NaClO), в горячей — до галогенатов (NaClO3). Конц. H2SO4 с NaCl даёт обмен (HCl↑), с KBr — Br2 + SO2↑, с KI — I2 + H2S↑.", "ref": "05.1"}, {"id": "p6", "t": "Шкала степеней окисления серы и две серные кислоты", "x": "S^{−2} (H2S, сульфиды) — только восстановитель, S^{0} и S^{+4} (SO2, сульфиты) — двойственны, S^{+6} (H2SO4 конц.) — только окислитель. Разбавленная H2SO4 окисляет за счёт H^{+} (выделяет H2↑ с металлами до H), а концентрированная — за счёт S^{+6} (реагирует с Cu, Ag, C, S, P без выделения H2↑).", "ref": "06.1"}, {"id": "p7", "t": "Азот, NO2, азотная кислота и разложение нитратов", "x": "HNO3 любой концентрации не выделяет H2↑ с металлами (окисляет N^{+5}). Оксиды N2O и NO несолеобразующие, а NO2 — кислотный оксид (диспропорционирует в воде и щёлочи, с O2 даёт только HNO3/нитрат). Разложение нитратов идёт по ряду напряжений: до Mg → нитрит + O2; Mg–Cu (и Li!) → оксид + NO2 + O2; после Cu → металл + NO2 + O2.", "ref": "07.1"}, {"id": "p8", "t": "Фосфор, углерод и кремний: особые реакции неметаллов", "x": "Фосфор и кремний напрямую с H2 не реагируют; белый P и Si растворяются в водных щелочах (P → PH3 + NaH2PO2; Si → Na2SiO3 + H2↑). SiO2 имеет атомную решётку: не реагирует с водой и обычными кислотами, но растворяется в HF и сплавляется со щелочами и карбонатами. CO — несолеобразующий оксид.", "ref": "08.1"}, {"id": "p9", "t": "Алгоритм быстрого отсева для № 6–9 КИМ", "x": "В № 7 строку из трёх реагентов отбрасывают по первому же несовместимому веществу (несолеобразующий оксид, нерастворимая соль/основание, пассивация, SiO2 + H2O). В № 9 нерастворимые гидроксиды (Cu(OH)2, Al(OH)3, Fe(OH)3) и H2SiO3 получают обходным путём через растворимую соль.", "ref": "09.1"}, {"id": "p10", "t": "Расшифровка эксперимента и критерии 4/4 балла в № 31", "x": "В № 31 каждое из 4 сбалансированных уравнений даёт 1 независимый балл. Ключ к расшифровке — цветовые и газовые маркеры (бурый газ NO2, жёлто-зелёный Cl2, жёлтый осадок S, белый студенистый Al(OH)3, бурый Fe(OH)3) и строгий учёт слов «избыток», «недостаток», «нагревание», «сплавление».", "ref": "10.1"}], "z": [{"id": "z1", "x": "Al2O3 нельзя восстановить водородом H2 или угарным газом CO — алюминий получают только электролизом раствора Al2O3 в расплаве криолита Na3AlF6.", "sk": "metallurgy_logic", "ref": "01.17"}, {"id": "z2", "x": "Щелочные и щёлочноземельные металлы (Na, K, Ca) не вытесняют другие металлы из водных растворов солей: сначала идёт реакция с водой до щёлочи и H2↑, затем щёлочь осаждает гидроксид.", "sk": "active_metals", "ref": "02.15"}, {"id": "z3", "x": "При горении в O2 литий даёт оксид Li2O, натрий — пероксид Na2O2, калий — надпероксид KO2; чистые Na2O и K2O получают довосстановлением пероксида избытком металла.", "sk": "active_metals", "ref": "02.4"}, {"id": "z4", "x": "Al(OH)3 НЕ растворяется в водном аммиаке NH3·H2O, а Zn(OH)2 и Cu(OH)2 растворяются с образованием аммиачных комплексов [Zn(NH3)4](OH)2 и [Cu(NH3)4](OH)2.", "sk": "amphoteric_al_zn", "ref": "03.21"}, {"id": "z5", "x": "Пропускание избытка CO2, SO2 или H2S через Na[Al(OH)4] даёт осадок Al(OH)3↓ и кислую соль (NaHCO3, NaHSO3, NaHS); осадок в слабых кислотах не растворяется.", "sk": "amphoteric_al_zn", "ref": "03.19"}, {"id": "z6", "x": "Пары Fe^{3+} + I⁻ / S^{2−} / H2S / SO3^{2−} и Cu^{2+} + I⁻ вступают в ОВР (с восстановлением до Fe^{2+} и CuI↓), а не в совместный гидролиз! С CO3^{2−} соли Fe(III) дают совместный гидролиз.", "sk": "transition_fe_cr_cu", "ref": "04.14"}, {"id": "z7", "x": "Fe(OH)3 в рамках ЕГЭ не растворяется в водных растворах щелочей — ферриты (NaFeO2) образуются только при сплавлении с твёрдой щёлочью или Na2CO3.", "sk": "transition_fe_cr_cu", "ref": "04.12"}, {"id": "z8", "x": "Фтор F2 не вытесняет хлор из водного раствора NaCl: фтор немедленно окисляет воду (2F2 + 2H2O → 4HF + O2↑). Плавиковая кислота HF — слабая, но растворяет SiO2.", "sk": "halogens", "ref": "05.5"}, {"id": "z9", "x": "При сжигании серы в кислороде образуется ТОЛЬКО SO2 (получить SO3 напрямую без катализатора V2O5 нельзя). Сульфиды CuS, Ag2S, HgS, PbS не растворяются в HCl и H2SO4(разб.).", "sk": "sulfur_compounds", "ref": "06.8"}, {"id": "z10", "x": "Исключения разложения нитратов: LiNO3 разлагается до Li2O + NO2 + O2 (как средняя группа!), а Fe(NO3)2 — до Fe2O3 + NO2 + O2 (Fe^{+2} окисляется выделяющимся кислородом до +3).", "sk": "nitrogen_nitrates", "ref": "07.17"}, {"id": "z11", "x": "Соль NaH2PO2 (гипофосфит натрия) — СРЕДНЯЯ соль одноосновной кислоты H3PO2 (два атома H связаны напрямую с P), а не кислая соль.", "sk": "p_c_si_compounds", "ref": "08.7"}, {"id": "z12", "x": "Оксид кремния(IV) SiO2 не реагирует с водой, HCl, H2SO4 и HNO3; кислота H2SiO3 — единственная нерастворимая кислота в таблице растворимости ФИПИ.", "sk": "p_c_si_compounds", "ref": "08.23"}]}, "skills": [{"id": "metallurgy_logic", "name": "Логика реакций и способы получения металлов", "ref": "01", "idea": "Выбирать промышленный метод получения любого металла по электрохимическому ряду напряжений и отсекать невозможные реакции восстановления.", "pre": {"type": "one", "q": "Какой металл в промышленности получают ТОЛЬКО электролизом расплава его соединения (нельзя восстановить CO, H2 или из водного раствора)?", "o": ["Алюминий (Al)", "Железо (Fe)", "Медь (Cu)", "Серебро (Ag)"], "a": 0, "ex": "Алюминий стоит в активной зоне ряда напряжений (Li–Al): его оксид Al2O3 слишком прочен для H2/CO, а в водном растворе на катоде вместо Al выделяется H2↑. Al получают электролизом Al2O3 в расплаве криолита.", "d": {"1": "Железо выплавляют пирометаллургией (восстановлением Fe2O3 угарным газом CO в домне).", "2": "Медь легко получают пирометаллургией (H2, CO) и гидрометаллургией (вытеснением железом из CuSO4).", "3": "Серебро — малоактивный металл, его получают гидрометаллургией или термическим разложением соединений."}}, "pair": {"type": "one", "cases": [["Получение железа Fe из Fe2O3", "Металл средней активности (правее Al в ряду напряжений)"], ["Получение натрия Na из NaCl", "Активный металл (левее Al в ряду напряжений)"]], "q": "Какие промышленные способы соответствуют получению железа из Fe2O3 и натрия из NaCl?", "o": ["Fe — восстановление CO/C (пирометаллургия); Na — электролиз расплава NaCl", "Оба металла получают электролизом водных растворов их хлоридов", "Fe — только электролиз расплава Fe2O3; Na — восстановление водородом H2", "Оба металла получают восстановлением угарным газом CO"], "a": 0, "ex": "Железо восстанавливается из оксида угарным газом CO в доменной печи, а натрий можно получить только электролизом расплава NaCl (или NaOH)."}, "fade": {"q": "Определи способ получения металла по его положению в ряду напряжений:", "steps": ["Металлы от Li до Al (Na, K, Ca, Mg, Al) получают исключительно {электролизом расплавов|восстановлением водородом|электролизом водных растворов}.", "Хром Cr из Cr2O3 часто получают алюмотермией: Cr2O3 + 2Al —t°→ 2Cr + {Al2O3|Al(OH)3|AlCl3}.", "Медь из водного раствора CuSO4 можно вытеснить железом (гидрометаллургия), так как Fe стоит {левее Cu и не реагирует бурно с водой|правее Cu|левее Na}."]}, "bug": {"q": "Найди ошибочный шаг в анализе способов получения металлов для заданий № 7 и № 9:", "steps": ["Медь Cu можно получить восстановлением CuO водородом H2 при нагревании.", "Хром Cr можно получить восстановлением Cr2O3 алюминием (алюмотермия).", "Алюминий Al можно получить в промышленности восстановлением Al2O3 угарным газом CO при нагревании.", "Ртуть Hg можно получить термическим разложением HgO при нагревании."], "bad": 2, "fix": "Al2O3 не восстанавливается ни водородом H2, ни угарным газом CO: алюминий получают электролизом раствора Al2O3 в расплаве криолита Na3AlF6.", "why": "Оксиды активных металлов (Li–Al) имеют слишком прочную связь металл–кислород для восстановления CO или H2."}, "recall": {"q": "Назови по памяти три главных метода металлургии и границу в ряду напряжений для каждого.", "points": ["Электрометаллургия (электролиз расплавов): активные металлы Li–Al (Al — из Al2O3 в расплаве криолита).", "Пирометаллургия (восстановление C, CO, H2, Al, Mg при нагревании): металлы средней и малой активности (правее Al).", "Гидрометаллургия (перевод руды в раствор соли и вытеснение более активным металлом правее Mg, например Fe + CuSO4 → FeSO4 + Cu)."]}}, {"id": "active_metals", "name": "Активные металлы (Na, K, Ca, Mg), пероксиды и кислые соли", "ref": "02", "idea": "Предсказывать продукты горения Na/K/Li в O2, реакции с водой и растворами солей, свойства пероксидов, гидридов, нитридов и различие NaHCO3 vs NaHSO4.", "pre": {"type": "one", "q": "Что произойдёт при внесении кусочка металлического натрия Na в водный раствор сульфата меди(II) CuSO4?", "o": ["Выделится газ H2↑ и выпадет голубой осадок Cu(OH)2↓", "Выпадет красная металлическая медь Cu и образуется Na2SO4", "Реакция не пойдёт из-за пассивации натрия", "Выделится бурый газ и выпадет чёрный осадок CuO"], "a": 0, "ex": "Натрий мгновенно реагирует с водой (2Na + 2H2O → 2NaOH + H2↑), а образовавшаяся щёлочь осаждает голубой гидроксид меди(II): 2NaOH + CuSO4 → Cu(OH)2↓ + Na2SO4.", "d": {"1": "Антипаттерн № 1: щелочные металлы не вытесняют другие металлы из водных растворов солей.", "2": "Натрий не пассивируется в воде — он реагирует с ней бурно.", "3": "Бурый газ (NO2) здесь образоваться не из чего, а в растворе при н.у. выпадает Cu(OH)2, не CuO."}}, "pair": {"type": "one", "cases": [["Гидрокарбонат натрия NaHCO3", "Кислая соль слабой угольной кислоты H2CO3"], ["Гидросульфат натрия NaHSO4", "Кислая соль сильной серной кислоты H2SO4"]], "q": "Чем принципиально отличаются химические свойства NaHCO3 и NaHSO4 в заданиях № 7 и № 8?", "o": ["NaHCO3 реагирует и с кислотами (CO2↑), и со щелочами; NaHSO4 не реагирует с сильными кислотами, но ведёт себя как кислота (реагирует с Mg, Na2CO3, щелочами)", "Обе соли реагируют с соляной кислотой HCl с выделением газа", "Обе соли не реагируют со щелочами", "NaHSO4 разлагается при слабом нагревании на Na2SO4, SO2 и H2O, а NaHCO3 термически устойчив"], "a": 0, "ex": "NaHCO3 проявляет кислотно-основную двойственность (с HCl → CO2↑, с NaOH → Na2CO3). NaHSO4 диссоциирует на Na^{+}, H^{+} и SO4^{2−}, поэтому ведёт себя как сильная кислота (растворяет Mg и карбонаты), но с HCl не реагирует."}, "fade": {"q": "Сравни продукты горения щелочных металлов в кислороде и гидролиза бинарных соединений:", "steps": ["При сгорании на воздухе литий даёт {Li2O|Li2O2|LiO2}, натрий — {Na2O2|Na2O|NaO2}, а калий — {KO2|K2O|K2O2}.", "Чтобы получить чистый Na2O из пероксида, его сплавляют с {избытком Na|избытком O2|водой}.", "При гидролизе нитрида магния Mg3N2 водой выделяется газ {NH3↑|N2↑|H2↑}, а при гидролизе CaC2 — газ {C2H2↑|CH4↑|CO2↑}."]}, "bug": {"q": "Найди ошибочный шаг в разборе свойств соединений кальция и магния:", "steps": ["Магний Mg практически не реагирует с холодной водой, но реагирует с кипящей водой (Mg(OH)2↓ + H2↑) и водяным паром (MgO + H2↑).", "При пропускании избытка CO2 через известковую воду Ca(OH)2 сначала выпадает осадок CaCO3↓, который затем растворяется с образованием Ca(HCO3)2.", "Карбонат натрия Na2CO3 при прокаливании легко разлагается на Na2O и CO2↑, как и CaCO3.", "При действии избытка Ba(OH)2 на KHCO3 образуются осадок BaCO3↓, щёлочь KOH и вода."], "bad": 2, "fix": "Карбонаты щелочных металлов (Na2CO3, K2CO3, кроме Li2CO3) термически устойчивы и при прокаливании плавятся без разложения.", "why": "Разлагаются при прокаливании карбонаты щелочноземельных металлов (CaCO3, MgCO3), Li2CO3 и тяжёлых металлов, но не Na2CO3 и K2CO3."}, "recall": {"q": "Перечисли по памяти продукты реакций Na2O2 с CO2, горячей H2O, холодной H2O и SO2.", "points": ["2Na2O2 + 2CO2 → 2Na2CO3 + O2↑ (регенерация кислорода).", "2Na2O2 + 2H2O(гор.) → 4NaOH + O2↑.", "Na2O2 + 2H2O(хол.) → 2NaOH + H2O2.", "Na2O2 + SO2 → Na2SO4 (окисление S^{+4} до S^{+6} без выделения O2)."]}}, {"id": "amphoteric_al_zn", "name": "Амфотерные металлы (Al, Zn), комплексы и совместный гидролиз", "ref": "03", "idea": "Различать реакции Al/Zn в растворе щёлочи и при сплавлении, предсказывать разрушение гидроксокомплексов, отличать Al(OH)3 от Zn(OH)2 в NH3·H2O и писать совместный гидролиз.", "pre": {"type": "one", "q": "Какой продукт образуется при пропускании избытка углекислого газа CO2 через раствор тетрагидроксоалюмината натрия Na[Al(OH)4]?", "o": ["Al(OH)3↓ и NaHCO3", "Al2(CO3)3↓ и NaOH", "Al(OH)3↓ и Na2CO3", "Реакция не идёт, так как CO2 — слабый кислотный оксид"], "a": 0, "ex": "Избыток CO2 разрушает комплекс с выпадением белого студенистого осадка Al(OH)3↓ и образованием кислой соли NaHCO3: Na[Al(OH)4] + CO2(изб.) → Al(OH)3↓ + NaHCO3.", "d": {"1": "Карбонат алюминия Al2(CO3)3 в воде не существует (прочерк в таблице растворимости).", "2": "При избытке CO2 всегда образуется кислая соль NaHCO3, а не средняя Na2CO3.", "3": "Угольная кислота достаточно сильна, чтобы разрушить гидроксокомплекс [Al(OH)4]⁻."}}, "pair": {"type": "one", "cases": [["Al(OH)3 + избыток водного аммиака NH3·H2O", "Алюминий не образует устойчивых аммиачных комплексов в воде"], ["Zn(OH)2 + избыток водного аммиака NH3·H2O", "Цинк (как и медь Cu) образует растворимый аммиакат"]], "q": "Что наблюдается в двух пробирках с осадками Al(OH)3 и Zn(OH)2 при добавлении избытка водного аммиака?", "o": ["Осадок Al(OH)3 не растворяется, а осадок Zn(OH)2 растворяется до [Zn(NH3)4](OH)2", "Оба осадка полностью растворяются с образованием комплексов", "Оба осадка не растворяются, так как NH3·H2O — слабое основание", "Al(OH)3 растворяется до NH4[Al(OH)4], а Zn(OH)2 остаётся в осадке"], "a": 0, "ex": "Водный аммиак осаждает Al(OH)3 из солей, но не растворяет его в избытке. Zn(OH)2 и Cu(OH)2 растворяются в избытке NH3·H2O за счёт образования аммиачных комплексов."}, "fade": {"q": "Выбери продукты для реакций амфотерного оксида/гидроксида алюминия в разных условиях:", "steps": ["Al2O3 + 2NaOH(тв.) —сплавление→ {2NaAlO2 + H2O|2Na[Al(OH)4]|Na3AlO3 + H2O}.", "Na[Al(OH)4] + HCl(нед.) → {Al(OH)3↓ + NaCl + H2O|AlCl3 + NaCl + 4H2O|NaAlO2 + HCl}.", "При сливании растворов AlCl3 и Na2CO3 идёт совместный гидролиз: выпадает {Al(OH)3↓|Al2(CO3)3↓|NaCl↓} и выделяется газ {CO2↑|H2↑|O2↑}."]}, "bug": {"q": "Найди ошибку в цепочке превращений соединений алюминия:", "steps": ["2Al + 2NaOH(водн.) + 6H2O → 2Na[Al(OH)4] + 3H2↑.", "Na[Al(OH)4] + NH4Cl → Al(OH)3↓ + NH3↑ + NaCl + H2O.", "Al2S3 + 6H2O → 2Al(OH)3↓ + 3H2S↑.", "2AlCl3 + 3Na2CO3 → Al2(CO3)3↓ + 6NaCl."], "bad": 3, "fix": "2AlCl3 + 3Na2CO3 + 3H2O → 2Al(OH)3↓ + 3CO2↑ + 6NaCl (необратимый совместный гидролиз).", "why": "Карбонат алюминия Al2(CO3)3 не существует в водном растворе (в таблице растворимости ФИПИ стоит прочерк)."}, "recall": {"q": "Назови по памяти 4 реагента, которые разрушают Na[Al(OH)4] строго до осадка Al(OH)3↓ (без растворения осадка в избытке).", "points": ["Углекислый газ CO2 (изб.) → Al(OH)3↓ + NaHCO3.", "Сернистый газ SO2 (изб.) → Al(OH)3↓ + NaHSO3.", "Сероводород H2S (изб.) → Al(OH)3↓ + NaHS + H2O.", "Соль аммония NH4Cl (или слабая кислота / недостаток HCl) → Al(OH)3↓ + NH3↑ + NaCl + H2O."]}}, {"id": "transition_fe_cr_cu", "name": "Переходные металлы: Fe, Cr, Mn, Cu, Ag и их соединения", "ref": "04", "idea": "Управлять степенями окисления Fe(+2/+3), Cr(+3/+6), Cu(+1/+2), видеть пассивацию и отличать ОВР с Fe^{3+}/Cu^{2+} от совместного гидролиза.", "pre": {"type": "one", "q": "Какие продукты образуются при сливании водных растворов хлорида железа(III) FeCl3 и иодида калия KI?", "o": ["FeCl2, I2 и KCl (ОВР)", "FeI3↓ и KCl (реакция обмена)", "Fe(OH)3↓, HI и KCl (совместный гидролиз)", "Реакция не идёт, так как все соли растворимы"], "a": 0, "ex": "Ион Fe^{3+} — сильный окислитель, а I⁻ — сильный восстановитель: 2FeCl3 + 2KI → 2FeCl2 + I2↓ + 2KCl. Соль FeI3 не существует.", "d": {"1": "Иодид железа(III) FeI3 не существует — I⁻ сразу восстанавливает Fe^{+3} до Fe^{+2}.", "2": "С I⁻ (как и с S^{2−}, SO3^{2−}) соли Fe(III) вступают в ОВР, а не в совместный гидролиз.", "3": "Отсутствие осадка обмена не мешает окислительно-восстановительной реакции."}}, "pair": {"type": "one", "cases": [["Fe3O4 + избыток HCl", "Неокисляющая кислота: степени окисления железа сохраняются"], ["Fe3O4 + избыток HNO3(конц.) при нагревании", "Кислота-окислитель: Fe^{+2} окисляется до Fe^{+3}"]], "q": "Какие соли железа образуются при растворении железной окалины Fe3O4 в HCl и в горячей HNO3(конц.) соответственно?", "o": ["В HCl — смесь FeCl2 и FeCl3; в HNO3(конц.) — только Fe(NO3)3 (+ NO2↑ + H2O)", "В обоих случаях образуется смесь солей железа(II) и железа(III)", "В HCl — только FeCl2; в HNO3(конц.) — только Fe(NO3)3", "В обоих случаях образуется только соль железа(III)"], "a": 0, "ex": "Fe3O4 = FeO·Fe2O3. С неокисляющей HCl получаются обе соли (FeCl2 + 2FeCl3 + 4H2O), с окислителем HNO3(конц.) всё железо переходит в Fe(NO3)3, а с восстановителем HI — всё железо переходит в FeI2 (+ I2)."}, "fade": {"q": "Проследи переходы переходных металлов в заданиях № 8 и № 31:", "steps": ["С хлором железо даёт {FeCl3|FeCl2|Fe3Cl4}, а с серой или HCl — {FeS / FeCl2|Fe2S3 / FeCl3|реакция не идёт}.", "При добавлении щёлочи KOH к оранжевому раствору K2Cr2O7 цвет становится {жёлтым (K2CrO4)|зелёным (Cr(OH)3)|фиолетовым}, и это {не ОВР|ОВР восстановления|ОВР окисления}.", "При смешивании CuSO4 и KI выпадает белый осадок {CuI↓|CuI2↓|Cu(OH)2↓} и выделяется {I2↓|O2↑|SO2↑}."]}, "bug": {"q": "Найди ошибочное уравнение в реакциях железа, хрома и серебра:", "steps": ["Cu + 2FeCl3 → CuCl2 + 2FeCl2.", "2AgNO3 + 2NaOH → Ag2O↓ + 2NaNO3 + H2O.", "Fe(OH)3 + NaOH(водн. р-р) → Na[Fe(OH)4].", "2Na[Cr(OH)4] + 3H2O2 + 2NaOH → 2Na2CrO4 + 8H2O."], "bad": 2, "fix": "В рамках ЕГЭ Fe(OH)3 не растворяется в водных растворах щелочей; феррит NaFeO2 получают только сплавлением с твёрдой щёлочью или Na2CO3.", "why": "Амфотерность Fe(OH)3 выражена крайне слабо: в № 6, 7, 8 его считают нерастворимым в водном NaOH."}, "recall": {"q": "Назови по памяти продукты реакций: 1) Fe3O4 + HI; 2) 2FeCl3 + 3Na2S(изб.); 3) Cu + 2FeCl3; 4) (NH4)2Cr2O7 при нагревании.", "points": ["Fe3O4 + 8HI → 3FeI2 + I2 + 4H2O (восстановление всего железа до +2).", "2FeCl3 + 3Na2S(изб.) → 2FeS↓ + S↓ + 6NaCl (при недостатке Na2S получается FeCl2 + S↓).", "Cu + 2FeCl3 → CuCl2 + 2FeCl2 (травление медных плат, ОВР).", "(NH4)2Cr2O7 —t°→ N2↑ + Cr2O3 + 4H2O («вулканчик»)."]}}, {"id": "halogens", "name": "Галогены (F2, Cl2, Br2, I2), щёлочи и галогениды с H2SO4(конц.)", "ref": "05", "idea": "Применять ряд окислительной активности галогенов, различать холодную и горячую щёлочь, предсказывать реакции NaCl/KBr/KI с конц. H2SO4 и разложение KClO3.", "pre": {"type": "one", "q": "Какие продукты образуются при пропускании хлора Cl2 в ГОРЯЧИЙ раствор гидроксида калия KOH?", "o": ["KCl, KClO3 и H2O", "KCl, KClO и H2O", "KCl, KClO4 и H2O", "Только KCl и O2↑"], "a": 0, "ex": "При нагревании хлор диспропорционирует до хлорида (−1) и хлората (+5): 3Cl2 + 6KOH(гор.) —t°→ 5KCl + KClO3 + 3H2O.", "d": {"1": "Гипохлорит KClO образуется в ХОЛОДНОМ растворе щёлочи.", "2": "Перхлорат KClO4 получается при термическом разложении KClO3 без катализатора.", "3": "Кислород выделяется при реакции с водой у фтора F2, а не у хлора со щёлочью."}}, "pair": {"type": "one", "cases": [["NaCl(тв.) + H2SO4(конц., t°)", "Cl⁻ — слабый восстановитель, серная кислота его не окисляет"], ["KI(тв.) + H2SO4(конц.)", "I⁻ — сильный восстановитель, восстанавливает S^{+6} максимально глубоко"]], "q": "Какие продукты выделяются в первой и второй реакциях соответственно?", "o": ["В первой — HCl↑ (обмен); во второй — I2↓ и H2S↑ (ОВР)", "В первой — Cl2↑ и SO2↑; во второй — I2↓ и SO2↑", "В обеих реакциях идёт обмен с выделением HCl↑ и HI↑", "В первой — HCl↑; во второй — I2↓ и SO2↑"], "a": 0, "ex": "NaCl(тв.) + H2SO4(конц.) → NaHSO4 + HCl↑ (обмен). С бромидом KBr конц. H2SO4 даёт Br2 + SO2↑, а с самым сильным восстановителем KI — I2↓ + H2S↑ (запах тухлых яиц)."}, "fade": {"q": "Предскажи продукты ключевых реакций галогенов и хлората калия:", "steps": ["При пропускании фтора F2 в водный раствор NaCl фтор реагирует с водой: 2F2 + 2H2O → 4HF + {O2↑|Cl2↑|H2↑}.", "Разложение KClO3 при нагревании С катализатором MnO2 даёт {KCl + O2↑|KClO4 + KCl|K2O + Cl2↑}, а БЕЗ катализатора — {KClO4 + KCl|KCl + O2↑|KClO + O2↑}.", "В ряду HF — HCl — HBr — HI сила кислоты {растёт|падает|не меняется}, и единственная кислота, растворяющая SiO2 — это {HF|HI|HCl}."]}, "bug": {"q": "Найди ошибочное утверждение о свойствах галогенов и их соединений:", "steps": ["Хлор вытесняет бром из водного раствора NaBr и иод из водного раствора KI.", "При действии избытка аммиака на хлор выделяется азот: 3Cl2 + 8NH3 → N2↑ + 6NH4Cl.", "Чистый газообразный иодоводород HI удобно получать в лаборатории действием концентрированной H2SO4 на твёрдый KI.", "С избытком хлора фосфор образует PCl5, а с недостатком — PCl3."], "bad": 2, "fix": "Концентрированная H2SO4 окисляет I⁻ до свободного иода I2 (с выделением H2S↑), поэтому HI (и HBr) нельзя получать через H2SO4(конц.) — используют гидролиз PI3/PBr3 или H3PO4.", "why": "Восстановительная сила HI слишком велика для контакта с окислителем H2SO4(конц.)."}, "recall": {"q": "Сравни по памяти три реакции твёрдых галогенидов (NaCl, KBr, KI) с H2SO4(конц.) и оба варианта разложения KClO3.", "points": ["NaCl(тв.) + H2SO4(конц.) —t°→ NaHSO4 + HCl↑ (обмен, без ОВР).", "2KBr(тв.) + 2H2SO4(конц.) → Br2 + SO2↑ + K2SO4 + 2H2O (ОВР до SO2).", "8KI(тв.) + 5H2SO4(конц.) → 4I2 + H2S↑ + 4K2SO4 + 4H2O (ОВР до H2S).", "KClO3 с MnO2 → KCl + O2↑; без катализатора → 3KClO4 + KCl."]}}, {"id": "sulfur_compounds", "name": "Сера, H2S, сульфиды, SO2 и серная кислота (разб. vs конц.)", "ref": "06", "idea": "Пользоваться шкалой степеней окисления серы, делить сульфиды по растворимости в кислотах, писать обжиг пирита и отличать H2SO4(разб.) от H2SO4(конц.).", "pre": {"type": "one", "q": "Какой сульфид НЕ растворяется в разбавленной соляной кислоте HCl, но растворяется в концентрированной азотной кислоте HNO3?", "o": ["CuS", "FeS", "ZnS", "Na2S"], "a": 0, "ex": "Четвёрка «сверхнерастворимых» сульфидов (CuS, Ag2S, HgS, PbS) не растворяется в неокисляющих кислотах (HCl, H2SO4 разб.), но окисляется азотной кислотой HNO3.", "d": {"1": "FeS легко растворяется в HCl с выделением H2S↑.", "2": "ZnS растворяется в HCl с выделением H2S↑.", "3": "Na2S растворим в воде и бурно реагирует с HCl."}}, "pair": {"type": "one", "cases": [["Cu + H2SO4(разб.)", "Медь стоит правее водорода, H^{+} её не окисляет"], ["Cu + H2SO4(конц., t°)", "Окислитель — S^{+6} концентрированной серной кислоты"]], "q": "Что происходит с медью в разбавленной и горячей концентрированной серной кислоте соответственно?", "o": ["В разбавленной реакция не идёт; в концентрированной образуются CuSO4, SO2↑ и H2O", "В разбавленной выделяется H2↑; в концентрированной — SO2↑", "В обоих случаях образуются CuSO4 и SO2↑", "Медь пассивируется в концентрированной H2SO4 при нагревании"], "a": 0, "ex": "H2SO4(разб.) с медью не реагирует. Горячая H2SO4(конц.) окисляет медь: Cu + 2H2SO4(конц.) —t°→ CuSO4 + SO2↑ + 2H2O."}, "fade": {"q": "Заполни ключевые реакции серы, сероводорода и пирита:", "steps": ["При сжигании серы даже в избытке кислорода образуется только {SO2|SO3|H2SO4}.", "При горении H2S в НЕДОСТАТКЕ O2 образуются {S↓ + H2O|SO2 + H2O|SO3 + H2O}, а в ИЗБЫТКЕ O2 — {SO2↑ + H2O|S↓ + H2O|H2SO4}.", "Обжиг пирита FeS2 на воздухе даёт бурый твёрдый оксид {Fe2O3|FeO|Fe3O4} и газ {SO2↑|SO3↑|H2S↑}."]}, "bug": {"q": "Найди ошибочный шаг в разборе реакций соединений серы:", "steps": ["2H2S + SO2 → 3S↓ + 2H2O (выпадение жёлтого осадка серы).", "3S + 6KOH(гор., конц.) —t°→ 2K2S + K2SO3 + 3H2O (диспропорционирование).", "2S + 3O2(изб.) —t°→ 2SO3 (прямое окисление серы в избытке кислорода).", "SO2 + Br2 + 2H2O → H2SO4 + 2HBr (обесцвечивание бромной воды)."], "bad": 2, "fix": "S + O2 —t°→ SO2. Оксид серы(VI) SO3 получают только каталитическим окислением SO2 (2SO2 + O2 ⇄ 2SO3, кат. V2O5, 450 °C).", "why": "Антипаттерн № 4: прямое сжигание серы в кислороде никогда не даёт SO3."}, "recall": {"q": "Назови по памяти 4 сульфида, нерастворимых в HCl, и продукты реакций S с горячей KOH, конц. HNO3 и конц. H2SO4.", "points": ["Не растворяются в HCl/H2SO4(разб.): CuS, Ag2S, HgS, PbS.", "3S + 6KOH(гор., конц.) → 2K2S + K2SO3 + 3H2O.", "S + 6HNO3(конц.) → H2SO4 + 6NO2↑ + 2H2O.", "S + 2H2SO4(конц.) → 3SO2↑ + 2H2O."]}}, {"id": "nitrogen_nitrates", "name": "Азот, аммиак, NO2, HNO3 и разложение нитратов", "ref": "07", "idea": "Безошибочно раскладывать любой нитрат и соль аммония при нагревании, различать NO/N2O vs NO2 и писать реакции HNO3 без выделения H2.", "pre": {"type": "one", "q": "Какие продукты образуются при термическом разложении нитрата лития LiNO3 и нитрата железа(II) Fe(NO3)2 соответственно?", "o": ["Li2O + NO2↑ + O2↑ и Fe2O3 + NO2↑ + O2↑", "LiNO2 + O2↑ и FeO + NO2↑ + O2↑", "LiNO2 + O2↑ и Fe2O3 + NO2↑ + O2↑", "Li2O + NO2↑ + O2↑ и FeO + NO2↑ + O2↑"], "a": 0, "ex": "Два главных исключения разложения нитратов: LiNO3 разлагается по типу средней группы до оксида Li2O, а в Fe(NO3)2 железо(+2) окисляется кислородом до Fe2O3(+3)!", "d": {"1": "Обе формулы неверны: LiNO3 не даёт нитрит, а Fe(NO3)2 не даёт FeO.", "2": "LiNO3 — исключение среди щелочных металлов, даёт Li2O + NO2 + O2.", "3": "FeO при прокаливании в потоке O2 и NO2 окисляется до Fe2O3."}}, "pair": {"type": "one", "cases": [["2NO2 + 2KOH (без кислорода)", "Диспропорционирование N^{+4} в N^{+3} и N^{+5}"], ["4NO2 + O2 + 4KOH (в присутствии O2)", "Кислород доокисляет весь азот до N^{+5}"]], "q": "Какие соли калия образуются при поглощении NO2 раствором KOH без кислорода и в присутствии кислорода O2?", "o": ["Без O2 — смесь KNO2 и KNO3; с O2 — только KNO3", "В обоих случаях образуется только нитрат калия KNO3", "Без O2 — только KNO2; с O2 — смесь KNO2 и KNO3", "NO2 — несолеобразующий оксид, с KOH не реагирует"], "a": 0, "ex": "NO2 — кислотный оксид (смешанный ангидрид): без O2 даёт нитрит + нитрат (KNO2 + KNO3), а с O2 — только нитрат KNO3."}, "fade": {"q": "Сравни разложение солей аммония и реакции с азотной кислотой:", "steps": ["При нагревании NH4NO2 образуется газ {N2↑|N2O↑|NH3↑}, а при нагревании NH4NO3 — газ {N2O↑|N2↑|NO2↑}.", "При действии концентрированной HNO3 на медь Cu выделяется {NO2↑ (бурый газ)|H2↑|NO↑ (бесцветный газ)}.", "При прокаливании AgNO3 образуются {Ag + NO2↑ + O2↑|Ag2O + NO2↑ + O2↑|AgNO2 + O2↑}."]}, "bug": {"q": "Найди ошибочный шаг в разборе свойств азота и его соединений:", "steps": ["Оксиды N2O и NO — несолеобразующие: они не реагируют с водой, кислотами и водными растворами щелочей.", "При горении аммиака без катализатора образуются N2 и H2O, а на платиновом катализаторе — NO и H2O.", "При реакции магния с очень разбавленной HNO3 выделяется водород H2↑ и образуется Mg(NO3)2.", "При нагревании NH4HCO3 образуются NH3↑, CO2↑ и H2O."], "bad": 2, "fix": "Антипаттерн № 5: азотная кислота ЛЮБОЙ концентрации не выделяет H2↑ с металлами; активный металл Mg с очень разбавленной HNO3 восстанавливает азот до NH4NO3 (или N2O/N2).", "why": "В HNO3 главным окислителем всегда выступает N^{+5}, а не H^{+}."}, "recall": {"q": "Назови по памяти 3 зоны термического разложения нитратов металлов и 2 главных исключения.", "points": ["Левее Mg (K, Na, Ca, Ba, кроме Li!): нитрит + O2↑ (2KNO3 → 2KNO2 + O2↑).", "От Mg до Cu включительно (+ Li!): оксид металла + NO2↑ + O2↑.", "Правее Cu (Ag, Hg): свободный металл + NO2↑ + O2↑.", "Исключения: LiNO3 → Li2O + NO2 + O2; Fe(NO3)2 → Fe2O3 + NO2 + O2 (повышение СО до +3)."]}}, {"id": "p_c_si_compounds", "name": "Фосфор, углерод, кремний и их соединения", "ref": "08", "idea": "Предсказывать реакции фосфора со щёлочью, взаимопереходы 3 рядов фосфатов, гидролиз карбидов, реакции CO/CO2 и особые свойства Si и SiO2.", "pre": {"type": "one", "q": "С какой из перечисленных кислот реагирует оксид кремния(IV) SiO2?", "o": ["HF (плавиковая)", "HCl (соляная)", "H2SO4 (конц.)", "HNO3 (конц.)"], "a": 0, "ex": "SiO2 — единственный кислотный оксид с атомной решёткой, который растворяется в плавиковой кислоте HF: SiO2 + 4HF → SiF4↑ + 2H2O (травление стекла).", "d": {"1": "Соляная кислота с SiO2 не реагирует.", "2": "Серная кислота (даже концентрированная) с SiO2 не реагирует.", "3": "Азотная кислота с SiO2 не реагирует."}}, "pair": {"type": "one", "cases": [["Карбид кальция CaC2 + H2O", "Ацетиленид кальция"], ["Карбид алюминия Al4C3 + H2O", "Метанид алюминия"]], "q": "Какие газы выделяются при гидролизе CaC2 и Al4C3 водой соответственно?", "o": ["Из CaC2 — ацетилен C2H2↑; из Al4C3 — метан CH4↑", "Из CaC2 — метан CH4↑; из Al4C3 — ацетилен C2H2↑", "В обоих случаях выделяется углекислый газ CO2↑", "В обоих случаях выделяется водород H2↑"], "a": 0, "ex": "CaC2 + 2H2O → Ca(OH)2 + C2H2↑ (ацетилен); Al4C3 + 12H2O → 4Al(OH)3↓ + 3CH4↑ (метан)."}, "fade": {"q": "Закрепи нестандартные реакции фосфора, углерода и кремния для № 7 и № 8:", "steps": ["При нагревании белого фосфора с концентрированным NaOH образуются газ {PH3↑|H2↑|P2O5} и средняя соль {NaH2PO2|Na3PO4|Na2HPO4}.", "Кремний растворяется в горячем водном растворе NaOH с образованием Na2SiO3 и газа {H2↑|SiH4↑|O2↑}.", "При сплавлении песка SiO2 с Na2CO3 образуются Na2SiO3 и {CO2↑|CO↑|C}; при этом SiO2 с водой {не реагирует|даёт H2SiO3|даёт SiH4}."]}, "bug": {"q": "Найди ошибочный шаг в разборе свойств фосфора, углерода и кремния:", "steps": ["Фосфор и кремний напрямую с водородом H2 не реагируют.", "При растворении P2O5 в холодной воде образуется HPO3, а в горячей — H3PO4.", "Оксид кремния(IV) SiO2 — кислотный оксид, поэтому при нагревании с водой он даёт кремниевую кислоту H2SiO3.", "При избытке Ca(OH)2 дигидрофосфат кальция Ca(H2PO4)2 переходит в средний фосфат Ca3(PO4)2↓."], "bad": 2, "fix": "Антипаттерн № 6: SiO2 с водой НЕ реагирует (из-за прочной атомной решётки). Кислоту H2SiO3↓ получают действием кислот на растворимый силикат Na2SiO3.", "why": "SiO2 — единственное школьное исключение среди кислотных оксидов, которое не реагирует с водой."}, "recall": {"q": "Назови по памяти 3 реакции получения или превращения кремния и 2 главные реакции карботермии с углеродом.", "points": ["SiO2 + 2C —t°→ Si + 2CO↑ (или SiO2 + 2Mg → Si + 2MgO).", "Si + 2NaOH + H2O —t°→ Na2SiO3 + 2H2↑ (растворение кремния в щёлочи).", "Mg2Si + 4HCl → 2MgCl2 + SiH4↑ (получение силана).", "CaO + 3C —t°→ CaC2 + CO↑ и Ca3(PO4)2 + 3SiO2 + 5C —t°→ 3CaSiO3 + 2P + 5CO↑."]}}, {"id": "kim6_9_algorithms", "name": "Алгоритмы отсева № 6–8 и генетические цепочки № 9", "ref": "09", "idea": "Мгновенно отбрасывать неверные тройки реагентов в № 7, различать осадки в № 6 и строить обходные пути через соль в цепочках № 9.", "pre": {"type": "one", "q": "В задании № 9 нужно осуществить цепочку превращений: CuO → X → Cu(OH)2. Какое вещество X необходимо взять на промежуточном шаге?", "o": ["CuCl2 (или CuSO4 / Cu(NO3)2)", "Cu", "Cu2O", "CuS"], "a": 0, "ex": "CuO с водой не реагирует, поэтому нерастворимый Cu(OH)2 получают обходным путём через растворимую соль: CuO + 2HCl → CuCl2 + H2O, затем CuCl2 + 2NaOH → Cu(OH)2↓ + 2NaCl.", "d": {"1": "Медь Cu не реагирует с водой и щелочами — из неё напрямую Cu(OH)2 не получить.", "2": "Cu2O также нерастворим и не реагирует с водой.", "3": "CuS нерастворим ни в воде, ни в щелочах, ни в HCl."}}, "pair": {"type": "one", "cases": [["В пробирке № 1 с осадком X при добавлении HCl осадок растворяется БЕЗ газа", "Основной/амфотерный гидроксид или оксид (например, Mg(OH)2, Al(OH)3, CuO)"], ["В пробирке № 2 с осадком Y при добавлении HCl осадок растворяется с выделением газа", "Карбонат (CO2↑), сульфит (SO2↑) или растворимый в кислоте сульфид (H2S↑)"]], "q": "Какая пара осадков X и Y подходит под эти наблюдения задания № 6?", "o": ["X = Al(OH)3, Y = CaCO3", "X = BaSO4, Y = CuS", "X = CaCO3, Y = Al(OH)3", "X = AgCl, Y = FeS"], "a": 0, "ex": "Al(OH)3 растворяется в HCl без выделения газа (AlCl3 + H2O), а CaCO3 растворяется в HCl с бурным выделением CO2↑. BaSO4, AgCl и CuS в HCl вообще не растворяются."}, "fade": {"q": "Примени алгоритм быстрого отсева в задании № 7 для оксида кремния(IV) SiO2:", "steps": ["Строку {H2O, HCl, NaOH} сразу отбрасываем, потому что SiO2 не реагирует с {водой и HCl|NaOH|ни одним из них}.", "Строку {HF, NaOH, CaCO3} проверяем по очереди: с HF → {SiF4↑ + H2O|реакции нет|H2SiO3}, с NaOH → Na2SiO3 + H2O, с CaCO3 при сплавлении → {CaSiO3 + CO2↑|CaSiO3 + CO↑|реакции нет}.", "Значит, для SiO2 подходит тройка {HF, NaOH, CaCO3|H2O, HCl, NaOH|HNO3, O2, NaCl}."]}, "bug": {"q": "Найди ошибку в рассуждении ученика при решении задания № 7 для меди Cu:", "steps": ["Медь стоит после водорода, поэтому строки с HCl и H2SO4(разб.) сразу вычёркиваем.", "Медь реагирует с концентрированной HNO3 (выделяется бурый газ NO2↑).", "Медь реагирует с раствором FeCl3 (образуются CuCl2 и FeCl2).", "Медь реагирует с водным раствором ZnSO4, вытесняя цинк."], "bad": 3, "fix": "Медь стоит ПРАВЕЕ цинка в ряду напряжений, поэтому она не вытесняет Zn из ZnSO4 (вытесняет только металлы правее себя, например Ag из AgNO3).", "why": "Металл вытесняет из раствора соли только менее активный металл (стоящий правее в ряду напряжений)."}, "recall": {"q": "Назови по памяти 4 главных «мгновенных отсекателя» в задании № 7.", "points": ["Несолеобразующие оксиды (CO, NO, N2O, SiO) не реагируют с H2O, кислотами и водными щелочами.", "SiO2 не реагирует с H2O, HCl, H2SO4, HNO3 (из кислот — только HF).", "Нерастворимые соли (BaSO4, AgCl, CuS) не вступают в РИО в воде и не растворяются в HCl.", "Металлы после H (Cu, Ag) не реагируют с H2O, HCl, H2SO4(разб.) и щелочами; Fe, Al, Cr пассивируются холодными конц. HNO3/H2SO4."]}}, {"id": "kim31_experiment", "name": "Мысленный эксперимент № 31: маркеры и 4 уравнения на 4/4", "ref": "10", "idea": "Расшифровывать текстовое описание четырёх превращений по цвету осадков и запаху газов, учитывать избыток/недостаток и писать 4 сбалансированных уравнения без потери баллов.", "pre": {"type": "one", "q": "В тексте задания № 31 написано: «Через раствор тетрагидроксоалюмината натрия пропустили избыток сернистого газа, выпавший осадок отделили и прокалили». Какие два уравнения соответствуют этим шагам?", "o": ["Na[Al(OH)4] + SO2 → Al(OH)3↓ + NaHSO3 и 2Al(OH)3 —t°→ Al2O3 + 3H2O", "2Na[Al(OH)4] + SO2 → 2Al(OH)3↓ + Na2SO3 + H2O и 2Al(OH)3 —t°→ Al2O3 + 3H2O", "2Na[Al(OH)4] + 3SO2 → Al2(SO3)3↓ + 2NaOH + 3H2O и Al2(SO3)3 → Al2O3 + 3SO2", "Na[Al(OH)4] + SO2 → NaAlO2 + H2SO3 + H2O и NaAlO2 → Al2O3"], "a": 0, "ex": "Ключевое слово «избыток SO2» требует записи КИСЛОЙ соли NaHSO3! Если написать среднюю Na2SO3, эксперт ФИПИ поставит 0 баллов за это уравнение.", "d": {"1": "При избытке кислого газа SO2 средняя соль Na2SO3 переходит в кислую NaHSO3 — за среднюю соль снимут балл.", "2": "Сульфит алюминия Al2(SO3)3 в воде не существует.", "3": "В водном растворе образуется осадок Al(OH)3, а не NaAlO2."}}, "pair": {"type": "one", "cases": [["В пробирке выпал жёлтый осадок и раствор обесцветился/позеленел", "Характерно для окисления H2S / S^{2−} до серы S↓ (например, с FeCl3 или SO2)"], ["В пробирке выпал бурый осадок без выделения газа", "Характерно для Fe(OH)3↓ (обмен с щёлочью) или MnO2↓ (KMnO4 в воде)"]], "q": "Какие вещества зашифрованы под «жёлтым осадком простого вещества» и «бурым осадком, не растворяющимся в избытке водного NaOH»?", "o": ["Сера S↓ и гидроксид железа(III) Fe(OH)3↓", "Иодид серебра AgI↓ и оксид меди(II) CuO↓", "Хромат бария BaCrO4↓ и гидроксид алюминия Al(OH)3↓", "Сера S↓ и гидроксид меди(II) Cu(OH)2↓"], "a": 0, "ex": "Жёлтый осадок простого вещества — сера S↓; бурый осадок, не растворяющийся в водном NaOH — Fe(OH)3↓ (а Cu(OH)2 — голубой, Al(OH)3 — белый)."}, "fade": {"q": "Расшифруй классическую цепочку маркеров задания № 31:", "steps": ["«Бурый газ с резким запахом» при растворении меди в кислоте — это {NO2↑|Cl2↑|SO2↑}, значит кислота — {HNO3(конц.)|HNO3(разб.)|H2SO4(конц.)}.", "«Бесцветный газ с запахом тухлых яиц» при действии HCl на сульфид железа(II) — это {H2S↑|SO2↑|NH3↑}.", "«Осадок растворился в избытке щёлочи с образованием бесцветного раствора» — это амфотерный гидроксид {Al(OH)3 или Zn(OH)2|Fe(OH)3|Mg(OH)2}."]}, "bug": {"q": "Найди ошибку, за которую эксперт ФИПИ снимет балл в задании № 31:", "steps": ["В задании № 31 не требуется указывать стрелки ↑/↓ и условия над стрелкой (t°, кат.) — достаточно верных формул и целых коэффициентов.", "Каждое из четырёх уравнений оценивается независимо в 1 балл (итого максимум 4 балла).", "Если в условии написано «пропустили избыток CO2 через раствор Na2SiO3», можно записать Na2SiO3 + CO2 + H2O → H2SiO3↓ + Na2CO3 — эксперт засчитает оба варианта.", "Уравнения в № 31 нужно обязательно проверять на баланс всех атомов (особенно кислорода)."], "bad": 2, "fix": "При прямом указании «избыток CO2» необходимо писать кислую соль: Na2SiO3 + 2CO2 + 2H2O → H2SiO3↓ + 2NaHCO3. Запись Na2CO3 при избытке CO2 оценивается в 0 баллов.", "why": "Игнорирование указаний «избыток» / «недостаток» в условии № 31 — самая частая причина потери 1 балла у сильных выпускников."}, "recall": {"q": "Назови по памяти 5 главных цветовых/газовых маркеров задания № 31 и 3 критерия, обнуляющих уравнение.", "points": ["Маркеры: NO2 (бурый газ), Cl2 (жёлто-зелёный газ), H2S (тухлые яйца), NH3/SO2 (резкий запах), Fe(OH)3 (бурый), Cu(OH)2 (голубой), Cr(OH)3 (серо-зелёный), S (жёлтый).", "Обнуляют балл: неверный или пропущенный коэффициент (в т.ч. дробный); игнорирование слова «избыток»/«недостаток»; неверная формула комплекса/соли."]}}], "figs": {}, "tab": [{"id": "tab_metallurgy", "ref": "01.15", "k": "Металл", "km": "металлом", "lv3": ["Al", "Cr", "Na", "Hg"], "cols": [{"t": "Основной промышленный способ получения", "sk": "metallurgy_logic", "n": 7, "q": "Каким промышленным способом получают металл {x}?", "m": "способом получения", "mq": "Выберите {k} металлы, получаемые способом: {v}."}], "rows": [["Na", "Электролиз расплава соли (хлорида)"], ["K", "Электролиз расплава соли (хлорида)"], ["Ca", "Электролиз расплава соли (хлорида)"], ["Mg", "Электролиз расплава соли (хлорида)"], ["Al", "Электролиз раствора Al2O3 в расплаве криолита"], ["Fe", "Восстановление оксида угарным газом CO / углеродом (пирометаллургия)"], ["Zn", "Восстановление оксида угарным газом CO / углеродом (пирометаллургия)"], ["Cr", "Алюмотермия (восстановление оксида алюминием)"], ["Mn", "Алюмотермия (восстановление оксида алюминием)"], ["Cu", "Пирометаллургия (H2/CO) или гидрометаллургия (вытеснение Fe)"], ["Hg", "Термическое разложение оксида / обжиг сульфида"]], "rw": {"Al": "Al2O3 не восстанавливается CO и H2; расплав AlCl3 не проводит ток → только Al2O3 в криолите.", "Cr": "Тугоплавкий хром получают алюмотермией: Cr2O3 + 2Al —t°→ 2Cr + Al2O3.", "Na": "Активные металлы (Li–Al) не выделяются из водных растворов → только электролиз расплава."}}, {"id": "tab_active_o2_bin", "ref": "02.4", "k": "Реакция активного металла / бинарного соединения", "km": "реакцией", "lv3": ["Na + O2", "K + O2", "Mg3N2 + H2O", "CaC2 + H2O", "Al4C3 + H2O"], "cols": [{"t": "Главный продукт реакции", "sk": "active_metals", "n": 8, "q": "Какой главный продукт образуется в реакции {x}?", "m": "главным продуктом", "mq": "Выберите {k} реакции, дающие продукт: {v}."}], "rows": [["Li + O2", "Оксид Li2O"], ["Na + O2", "Пероксид Na2O2"], ["K + O2", "Надпероксид KO2"], ["Ca + O2", "Оксид CaO"], ["NaH + H2O", "Щёлочь и водород H2↑"], ["CaH2 + H2O", "Щёлочь и водород H2↑"], ["Mg3N2 + H2O", "Mg(OH)2↓ и аммиак NH3↑"], ["CaC2 + H2O", "Ca(OH)2 и ацетилен C2H2↑"], ["Al4C3 + H2O", "Al(OH)3↓ и метан CH4↑"], ["Ca3P2 + H2O", "Ca(OH)2 и фосфин PH3↑"]], "rw": {"Na + O2": "Натрий при горении на воздухе образует жёлтоватый пероксид Na2O2, а не Na2O.", "K + O2": "Калий при горении образует надпероксид KO2 (СО кислорода −1/2).", "Mg3N2 + H2O": "Необратимый гидролиз нитрида даёт гидроксид металла и аммиак NH3↑."}}, {"id": "tab_amphoteric_cond", "ref": "03.13", "k": "Реакция амфотерного соединения", "km": "реакцией", "lv3": ["Al(OH)3 + NH3·H2O(изб.)", "Zn(OH)2 + NH3·H2O(изб.)", "Na[Al(OH)4] + CO2(изб.)", "Fe(OH)3 + NaOH(водн.)"], "cols": [{"t": "Результат / главный продукт", "sk": "amphoteric_al_zn", "n": 8, "q": "Какой результат характерен для взаимодействия {x}?", "m": "результатом", "mq": "Выберите {k} пары с результатом: {v}."}], "rows": [["Al(OH)3 + NaOH(водн.)", "Гидроксокомплекс Na[Al(OH)4]"], ["Al2O3 + NaOH(тв., сплавление)", "Средняя соль NaAlO2 + H2O"], ["Zn(OH)2 + NaOH(водн.)", "Гидроксокомплекс Na2[Zn(OH)4]"], ["ZnO + NaOH(тв., сплавление)", "Средняя соль Na2ZnO2 + H2O"], ["Al(OH)3 + NH3·H2O(изб.)", "Реакция не идёт (осадок не растворяется)"], ["Fe(OH)3 + NaOH(водн.)", "Реакция не идёт (осадок не растворяется)"], ["Zn(OH)2 + NH3·H2O(изб.)", "Аммиачный комплекс [Zn(NH3)4](OH)2"], ["Na[Al(OH)4] + CO2(изб.)", "Al(OH)3↓ + NaHCO3"], ["Na[Al(OH)4] + HCl(изб.)", "AlCl3 + NaCl + H2O"], ["AlCl3 + Na2CO3 + H2O", "Al(OH)3↓ + CO2↑ + NaCl (совместный гидролиз)"]], "rw": {"Al(OH)3 + NH3·H2O(изб.)": "Алюминий не образует устойчивого аммиачного комплекса.", "Fe(OH)3 + NaOH(водн.)": "В школьной модели ЕГЭ Fe(OH)3 реагирует со щёлочью только при сплавлении.", "Na[Al(OH)4] + CO2(изб.)": "Слабая угольная кислота не растворяет осадок Al(OH)3↓, а избыток CO2 даёт кислую соль NaHCO3."}}, {"id": "tab_fe_ox_products", "ref": "04.4", "k": "Реакция железа / соединений Fe", "km": "реакцией", "lv3": ["Fe + I2", "Fe + HNO3(конц., хол.)", "Fe3O4 + HCl", "FeCl3 + KI", "FeCl3 + Na2S(изб.)"], "cols": [{"t": "Степень окисления Fe в продуктах", "sk": "transition_fe_cr_cu", "n": 8, "q": "В какой степени окисления находится железо в продуктах реакции {x}?", "m": "степенью окисления железа", "mq": "Выберите {k} реакции, где железо в продуктах имеет состояние: {v}."}], "rows": [["Fe + HCl", "Только Fe(+2)"], ["Fe + H2SO4(разб.)", "Только Fe(+2)"], ["Fe + S (t°)", "Только Fe(+2)"], ["Fe + I2 (t°)", "Только Fe(+2)"], ["FeCl3 + KI", "Только Fe(+2)"], ["FeCl3 + Na2S(изб.)", "Только Fe(+2)"], ["Fe + Cl2 (t°)", "Только Fe(+3)"], ["Fe + Br2 (t°)", "Только Fe(+3)"], ["Fe + HNO3(конц., t°)", "Только Fe(+3)"], ["Fe + H2SO4(конц., t°)", "Только Fe(+3)"], ["Fe3O4 + HCl", "Смесь Fe(+2) и Fe(+3)"], ["Fe + O2 (t°)", "Смесь Fe(+2) и Fe(+3)"], ["Fe + HNO3(конц., хол.)", "Пассивация (реакция не идёт)"]], "rw": {"Fe + I2": "Иод — слабый окислитель, окисляет железо только до FeI2 (+2); FeI3 не существует.", "Fe3O4 + HCl": "Смешанный оксид FeO·Fe2O3 с неокисляющей HCl даёт смесь FeCl2 и FeCl3.", "Fe + HNO3(конц., хол.)": "На холоде Fe, Al и Cr пассивируются концентрированными HNO3 и H2SO4."}}, {"id": "tab_halogens_h2so4", "ref": "05.18", "k": "Взаимодействие с галогеном / галогенидом", "km": "реакцией", "lv3": ["F2 + H2O", "Cl2 + KOH(гор.)", "KBr(тв.) + H2SO4(конц., t°)", "KI(тв.) + H2SO4(конц.)", "KClO3 (t°, без кат.)"], "cols": [{"t": "Тип продуктов реакции", "sk": "halogens", "n": 8, "q": "Какие продукты образуются в реакции {x}?", "m": "продуктами реакции", "mq": "Выберите {k} реакции, дающие результат: {v}."}], "rows": [["F2 + H2O", "HF + O2↑ (окисление воды)"], ["Cl2 + H2O", "HCl + HClO (обратимо)"], ["Cl2 + KOH(хол.)", "Галогенид + гипогалогенит + H2O"], ["Cl2 + NaOH(хол.)", "Галогенид + гипогалогенит + H2O"], ["Cl2 + KOH(гор.)", "Галогенид + галогенат + H2O"], ["Cl2 + NaOH(гор.)", "Галогенид + галогенат + H2O"], ["NaCl(тв.) + H2SO4(конц., t°)", "Гидросульфат + HCl↑ (обмен, без ОВР)"], ["KCl(тв.) + H2SO4(конц., t°)", "Гидросульфат + HCl↑ (обмен, без ОВР)"], ["KBr(тв.) + H2SO4(конц., t°)", "Br2 + SO2↑ + сульфат + H2O"], ["NaBr(тв.) + H2SO4(конц., t°)", "Br2 + SO2↑ + сульфат + H2O"], ["KI(тв.) + H2SO4(конц.)", "I2 + H2S↑ + сульфат + H2O"], ["NaI(тв.) + H2SO4(конц.)", "I2 + H2S↑ + сульфат + H2O"], ["KClO3 (t°, кат. MnO2)", "KCl + O2↑"], ["KClO3 (t°, без кат.)", "KClO4 + KCl (диспропорционирование)"]], "rw": {"F2 + H2O": "Фтор окисляет воду с выделением кислорода O2↑.", "KI(тв.) + H2SO4(конц.)": "Сильный восстановитель I⁻ восстанавливает S^{+6} максимально глубоко — до H2S↑.", "KClO3 (t°, без кат.)": "Без катализатора идёт диспропорционирование: 4KClO3 → 3KClO4 + KCl."}}, {"id": "tab_nitrates_decomp", "ref": "07.18", "k": "Нитрат / соль аммония (нагревание)", "km": "солью", "lv3": ["LiNO3", "Fe(NO3)2", "AgNO3", "NH4NO2", "NH4NO3"], "cols": [{"t": "Продукты термического разложения", "sk": "nitrogen_nitrates", "n": 8, "q": "Какие продукты образуются при прокаливании {x}?", "m": "продуктами разложения", "mq": "Выберите {k} соли, которые при нагревании дают: {v}."}], "rows": [["KNO3", "Нитрит + O2↑"], ["NaNO3", "Нитрит + O2↑"], ["Ba(NO3)2", "Нитрит + O2↑"], ["LiNO3", "Оксид металла + NO2↑ + O2↑"], ["Mg(NO3)2", "Оксид металла + NO2↑ + O2↑"], ["Cu(NO3)2", "Оксид металла + NO2↑ + O2↑"], ["Fe(NO3)2", "Оксид металла(+3) Fe2O3 + NO2↑ + O2↑"], ["AgNO3", "Свободный металл + NO2↑ + O2↑"], ["Hg(NO3)2", "Свободный металл + NO2↑ + O2↑"], ["NH4NO2", "N2↑ + H2O"], ["NH4NO3", "N2O↑ + H2O"], ["(NH4)2Cr2O7", "N2↑ + Cr2O3 + H2O"]], "rw": {"LiNO3": "Исключение: нитрат лития разлагается до Li2O + NO2 + O2, а не до нитрита.", "Fe(NO3)2": "Железо(+2) окисляется кислородом до Fe2O3(+3): 4Fe(NO3)2 → 2Fe2O3 + 8NO2 + O2.", "NH4NO3": "Нитрат аммония даёт веселящий газ N2O↑ + 2H2O (в отличие от NH4NO2 → N2↑ + 2H2O)."}}, {"id": "tab_markers31", "ref": "10.5", "k": "Реакция в задании № 31 / № 6", "km": "реакцией", "lv3": ["Na[Al(OH)4] + CO2(изб.)", "FeCl3 + H2S", "Na + CuSO4(водн.)", "Fe(OH)2 + O2 + H2O"], "cols": [{"t": "Главный наблюдаемый маркер в пробирке", "sk": "kim31_experiment", "n": 31, "q": "Какой главный визуальный или газовый маркер наблюдается в реакции: {x}?", "m": "визуальным маркером", "mq": "Выберите {k} реакции, в которых наблюдается маркер: {v}."}], "rows": [["Cu + HNO3(конц.)", "Бурый газ NO2↑"], ["S + HNO3(конц., t°)", "Бурый газ NO2↑"], ["KMnO4 + HCl(конц.)", "Жёлто-зелёный газ Cl2↑"], ["MnO2 + HCl(конц., t°)", "Жёлто-зелёный газ Cl2↑"], ["FeCl3 + NaOH", "Бурый осадок Fe(OH)3↓"], ["Fe(OH)2 + O2 + H2O", "Бурый осадок Fe(OH)3↓"], ["CuSO4 + NaOH", "Голубой осадок Cu(OH)2↓"], ["Na + CuSO4(водн.)", "Голубой осадок Cu(OH)2↓"], ["AlCl3 + NH3·H2O(изб.)", "Белый студенистый осадок Al(OH)3↓"], ["Na[Al(OH)4] + CO2(изб.)", "Белый студенистый осадок Al(OH)3↓"], ["FeCl3 + H2S", "Жёлтый осадок серы S↓"], ["H2S + SO2", "Жёлтый осадок серы S↓"]], "rw": {"Na[Al(OH)4] + CO2(изб.)": "Избыток CO2 разрушает комплекс до Al(OH)3↓ + NaHCO3.", "FeCl3 + H2S": "ОВР: 2FeCl3 + H2S → 2FeCl2 + S↓ + 2HCl.", "Na + CuSO4(водн.)": "Сначала 2Na + 2H2O → 2NaOH + H2↑, затем 2NaOH + CuSO4 → Cu(OH)2↓ + Na2SO4."}}], "rx": [{"id": "rx001_fe2o3_co", "sk": "metallurgy_logic", "ref": "01.15", "n": 8, "lvl": 1, "l": ["Fe2O3", "CO"], "r": ["Fe", "CO2"], "c": [1, 3, 2, 3], "if": "t° (доменная пирометаллургия)", "bad": [["FeO", "В избытке CO при высокой температуре железо восстанавливается до металла Fe."], ["C", "Угарный газ CO окисляется до CO2, а не восстанавливается до углерода."]], "why": "Пирометаллургия: CO восстанавливает оксиды металлов средней активности до свободного металла."}, {"id": "rx002_cr2o3_al", "sk": "metallurgy_logic", "ref": "01.15", "n": 8, "lvl": 2, "l": ["Cr2O3", "Al"], "r": ["Cr", "Al2O3"], "c": [1, 2, 2, 1], "if": "t° (алюмотермия)", "bad": [["CrO", "Алюминий восстанавливает оксид хрома(III) полностью до металлического хрома."], ["AlCrO3", "При алюмотермии образуется свободный хром и оксид алюминия Al2O3."]], "why": "Алюмотермия — промышленный способ получения тугоплавких металлов (Cr, Mn, V)."}, {"id": "rx003_fe_cuso4", "sk": "metallurgy_logic", "ref": "01.15", "n": 8, "lvl": 1, "l": ["Fe", "CuSO4"], "r": ["FeSO4", "Cu"], "c": [1, 1, 1, 1], "if": "водный раствор (гидрометаллургия)", "bad": [["Fe2(SO4)3", "В растворе CuSO4 железо окисляется только до Fe(+2) (FeSO4)."], ["Cu(OH)2", "Железо, в отличие от Na, не реагирует с водой при н.у., а вытесняет медь."]], "why": "Более активный металл (правее Mg) вытесняет менее активный из водного раствора его соли."}, {"id": "rx004_na_o2", "sk": "active_metals", "ref": "02.4", "n": 8, "lvl": 2, "l": ["Na", "O2"], "r": ["Na2O2"], "c": [2, 1, 1], "if": "горение на воздухе / в кислороде", "bad": [["Na2O", "Натрий при горении в O2 образует пероксид Na2O2, а не оксид Na2O."], ["NaO2", "Надпероксид в ЕГЭ характерен для калия (KO2), для натрия — пероксид Na2O2."]], "why": "Щелочные металлы горят в O2 по-разному: Li → Li2O, Na → Na2O2, K → KO2."}, {"id": "rx005_k_o2", "sk": "active_metals", "ref": "02.4", "n": 8, "lvl": 3, "l": ["K", "O2"], "r": ["KO2"], "c": [1, 1, 1], "if": "горение калия в кислороде", "bad": [["K2O", "Калий при горении не даёт обычный оксид K2O."], ["K2O2", "Основной продукт горения калия в ЕГЭ — надпероксид KO2."]], "why": "Калий, рубидий и цезий при горении в кислороде образуют надпероксиды (KO2)."}, {"id": "rx006_na2o2_na", "sk": "active_metals", "ref": "02.6", "n": 8, "lvl": 3, "l": ["Na2O2", "Na"], "r": ["Na2O"], "c": [1, 2, 2], "if": "t° (довосстановление пероксида избытком металла)", "bad": [["NaOH", "В реакции нет водорода — образуется безводный оксид Na2O."], ["O2", "Кислород не выделяется: металл связывает пероксидный кислород в Na2O."]], "why": "Единственный классический способ получения чистого Na2O из пероксида в ЕГЭ."}, {"id": "rx007_ko2_k", "sk": "active_metals", "ref": "02.6", "n": 8, "lvl": 3, "l": ["KO2", "K"], "r": ["K2O"], "c": [2, 6, 4], "if": "t° (довосстановление надпероксида избытком калия)", "bad": [["K2O2", "Избыток металлического калия восстанавливает KO2 полностью до K2O."], ["KOH", "Без воды гидроксид не образуется."]], "why": "Аналогично натрию: избыток активного металла переводит надпероксид в обычный оксид K2O."}, {"id": "rx008_na_h2", "sk": "active_metals", "ref": "02.8", "n": 8, "lvl": 1, "l": ["Na", "H2"], "r": ["NaH"], "c": [2, 1, 2], "if": "t° (образование ионного гидрида)", "bad": [["NaH2", "Натрий одновалентен (+1), водород в гидриде (−1) → формула NaH."], ["NaOH", "В реакции нет кислорода."]], "why": "Активные металлы при нагревании с H2 образуют солеобразные гидриды (H^{−1})."}, {"id": "rx009_ca_h2", "sk": "active_metals", "ref": "02.8", "n": 8, "lvl": 1, "l": ["Ca", "H2"], "r": ["CaH2"], "c": [1, 1, 1], "if": "t° (образование гидрида кальция)", "bad": [["CaH", "Кальций двухвалентен (+2) → формула гидрида CaH2."], ["Ca(OH)2", "Без кислорода и воды гидроксид не образуется."]], "why": "Гидрид кальция CaH2 — твёрдое ионное вещество (Ca^{+2}, H^{−1})."}, {"id": "rx010_mg_n2", "sk": "active_metals", "ref": "02.8", "n": 8, "lvl": 2, "l": ["Mg", "N2"], "r": ["Mg3N2"], "c": [3, 1, 1], "if": "t° (нагревание магния в азоте)", "bad": [["MgN", "Mg^{+2} и N^{−3} дают формулу Mg3N2."], ["Mg(NO3)2", "В реакции нет кислорода — образуется бинарный нитрид."]], "why": "Магний и кальций реагируют с азотом N2 при нагревании с образованием нитридов."}, {"id": "rx011_li_n2", "sk": "active_metals", "ref": "02.8", "n": 8, "lvl": 3, "l": ["Li", "N2"], "r": ["Li3N"], "c": [6, 1, 2], "if": "н.у. (комнатная температура!)", "bad": [["LiN", "Li^{+1} и N^{−3} дают формулу нитрида Li3N."], ["Li2N", "Неверный индекс: сумма зарядов должна быть равна нулю (3·(+1) + (−3) = 0)."]], "why": "Литий — единственный металл в ЕГЭ, реагирующий с N2 при комнатной температуре."}, {"id": "rx012_ca_c", "sk": "active_metals", "ref": "02.8", "n": 8, "lvl": 2, "l": ["Ca", "C"], "r": ["CaC2"], "c": [1, 2, 1], "if": "t° (получение карбида кальция)", "bad": [["Ca2C", "Карбид кальция — ацетиленид состава CaC2 (ион C2^{2−})."], ["CaCO3", "В реакции нет кислорода."]], "why": "При прокаливании Ca (или CaO) с углеродом образуется ацетиленид CaC2."}, {"id": "rx013_na_h2o", "sk": "active_metals", "ref": "02.12", "n": 8, "lvl": 1, "l": ["Na", "H2O"], "r": ["NaOH", "H2"], "c": [2, 2, 2, 1], "if": "н.у. (бурная реакция с водой)", "bad": [["Na2O", "В воде натрий сразу образует растворимую щёлочь NaOH, а не оксид."], ["O2", "Восстанавливается водород воды H^{+1} → H2↑, а не выделяется кислород."]], "why": "Щелочные металлы энергично реагируют с водой при н.у. с выделением H2↑."}, {"id": "rx014_ca_h2o", "sk": "active_metals", "ref": "02.12", "n": 8, "lvl": 1, "l": ["Ca", "H2O"], "r": ["Ca(OH)2", "H2"], "c": [1, 2, 1, 1], "if": "н.у. (реакция с водой)", "bad": [["CaO", "При н.у. с водой кальций даёт гидроксид Ca(OH)2 и H2↑."], ["CaH2", "Гидрид сам разлагается водой."]], "why": "Щёлочноземельные металлы (Ca, Ba) реагируют с водой при н.у. с образованием щёлочи и H2↑."}, {"id": "rx015_mg_h2o_hot", "sk": "active_metals", "ref": "02.14", "n": 8, "lvl": 2, "l": ["Mg", "H2O"], "r": ["Mg(OH)2", "H2"], "c": [1, 2, 1, 1], "if": "кипящая вода, t°", "bad": [["MgO", "MgO образуется с водяным паром при сильном прокаливании; с кипящей водой — Mg(OH)2↓."], ["MgH2", "Вода окисляет магний до гидроксида с выделением H2↑."]], "why": "С холодной водой Mg почти не реагирует, с кипящей водой даёт Mg(OH)2↓ + H2↑."}, {"id": "rx016_mg_h2o_steam", "sk": "active_metals", "ref": "02.14", "n": 8, "lvl": 3, "l": ["Mg", "H2O"], "r": ["MgO", "H2"], "c": [1, 1, 1, 1], "if": "водяной пар, сильное нагревание t°", "bad": [["Mg(OH)2", "При высокой температуре в водяном паре Mg(OH)2 разлагается → образуется MgO."], ["O2", "Магний восстанавливает водород воды до H2↑."]], "why": "Металлы средней активности и Mg с водяным паром при высокой t° дают оксид и H2↑."}, {"id": "rx017_nah_h2o", "sk": "active_metals", "ref": "02.19", "n": 8, "lvl": 2, "l": ["NaH", "H2O"], "r": ["NaOH", "H2"], "c": [1, 1, 1, 1], "if": "н.у. (гидролиз гидрида)", "bad": [["Na2O", "В воде образуется щёлочь NaOH."], ["O2", "H^{−1} и H^{+1} сопропорционируют в H2↑."]], "why": "Гидролиз гидридов — ОВР сопропорционирования водорода: H^{−1} + H^{+1} → H2↑."}, {"id": "rx018_cah2_h2o", "sk": "active_metals", "ref": "02.19", "n": 8, "lvl": 2, "l": ["CaH2", "H2O"], "r": ["Ca(OH)2", "H2"], "c": [1, 2, 1, 2], "if": "н.у. (гидролиз гидрида кальция)", "bad": [["CaO", "В водной среде образуется гидроксид Ca(OH)2."], ["H2O2", "Образуется газообразный водород 2H2↑, а не пероксид."]], "why": "На 1 моль CaH2 выделяется 2 моль H2↑ (источник водорода)."}, {"id": "rx019_mg3n2_h2o", "sk": "active_metals", "ref": "02.19", "n": 8, "lvl": 2, "l": ["Mg3N2", "H2O"], "r": ["Mg(OH)2", "NH3"], "c": [1, 6, 3, 2], "if": "н.у. / t° (необратимый гидролиз нитрида)", "bad": [["N2", "Степень окисления азота (−3) не меняется → выделяется NH3↑, а не N2."], ["MgO", "В воде образуется осадок Mg(OH)2↓."]], "why": "Необратимый гидролиз бинарных соединений идёт без изменения степеней окисления: N^{−3} → NH3↑."}, {"id": "rx020_cac2_h2o", "sk": "active_metals", "ref": "02.19", "n": 8, "lvl": 2, "l": ["CaC2", "H2O"], "r": ["Ca(OH)2", "C2H2"], "c": [1, 2, 1, 1], "if": "н.у. (гидролиз карбида кальция)", "bad": [["CH4", "Метан CH4 выделяется при гидролизе Al4C3, а CaC2 даёт ацетилен C2H2↑."], ["CO2", "Степени окисления не меняются — образуется ацетилен C2H2↑."]], "why": "Лабораторный способ получения ацетилена C2H2↑ из карбида кальция."}, {"id": "rx021_na2o2_co2", "sk": "active_metals", "ref": "02.21", "n": 8, "lvl": 2, "l": ["Na2O2", "CO2"], "r": ["Na2CO3", "O2"], "c": [2, 2, 2, 1], "if": "н.у. (регенерация кислорода)", "bad": [["NaHCO3", "В реакции нет водорода — образуется средняя соль Na2CO3."], ["CO", "CO2 не восстанавливается; диспропорционирует кислород O^{−1} → O^{−2} и O2^{0}."]], "why": "Ключевая реакция пероксида натрия: поглощение CO2 с выделением O2↑."}, {"id": "rx022_na2o2_h2o_hot", "sk": "active_metals", "ref": "02.21", "n": 8, "lvl": 2, "l": ["Na2O2", "H2O"], "r": ["NaOH", "O2"], "c": [2, 2, 4, 1], "if": "горячая вода / н.у. с разложением H2O2", "bad": [["H2", "Выделяется кислород O2↑ за счёт диспропорционирования O^{−1}, а не H2."], ["Na2O", "В воде образуется щёлочь NaOH."]], "why": "С горячей водой пероксид натрия даёт щёлочь NaOH и кислород O2↑."}, {"id": "rx023_na2o2_h2o_cold", "sk": "active_metals", "ref": "02.21", "n": 8, "lvl": 3, "l": ["Na2O2", "H2O"], "r": ["NaOH", "H2O2"], "c": [1, 2, 2, 1], "if": "холодная вода (0 °C, гидролиз без разложения)", "bad": [["O2", "При сильном охлаждении H2O2 не разлагается до O2↑."], ["Na2O", "В воде пероксид гидролизуется до NaOH и H2O2."]], "why": "На холоде идёт обратимый гидролиз пероксида как соли слабой кислоты H2O2."}, {"id": "rx024_na2o2_so2", "sk": "active_metals", "ref": "02.23", "n": 8, "lvl": 3, "l": ["Na2O2", "SO2"], "r": ["Na2SO4"], "c": [1, 1, 1], "if": "реакция с оксидом-восстановителем SO2", "bad": [["Na2SO3", "Пероксид — сильный окислитель, он окисляет S^{+4} до сульфата Na2SO4."], ["O2", "Кислород полностью расходуется на окисление SO2 до SO4^{2−}."]], "why": "В отличие от CO2, восстановитель SO2 окисляется пероксидом до Na2SO4 без выделения O2↑."}, {"id": "rx025_na2o2_hcl_cold", "sk": "active_metals", "ref": "02.23", "n": 8, "lvl": 3, "l": ["Na2O2", "HCl"], "r": ["NaCl", "H2O2"], "c": [1, 2, 2, 1], "if": "охлаждённая разбавленная HCl", "bad": [["Cl2", "С охлаждённой разбавленной HCl идёт обмен с образованием H2O2."], ["H2O", "При охлаждении сохраняется пероксид водорода H2O2."]], "why": "При охлаждении пероксид натрия с разбавленной кислотой даёт соль и H2O2."}, {"id": "rx026_ki_h2o2_h2so4", "sk": "active_metals", "ref": "02.25", "n": 8, "lvl": 2, "l": ["KI", "H2O2", "H2SO4"], "r": ["I2", "K2SO4", "H2O"], "c": [2, 1, 1, 1, 1, 2], "if": "разб. H2SO4 (H2O2 — окислитель)", "bad": [["O2", "Здесь H2O2 — окислитель (O^{−1} → O^{−2} в H2O), газ O2 не выделяется."], ["KIO3", "В кислой среде иодид-ион окисляется H2O2 до простого вещества I2↓."]], "why": "С восстановителями (KI, FeSO4, Na2SO3) пероксид H2O2 выступает окислителем (→ H2O)."}, {"id": "rx027_kmno4_h2o2_h2so4", "sk": "active_metals", "ref": "02.25", "n": 8, "lvl": 2, "l": ["KMnO4", "H2O2", "H2SO4"], "r": ["MnSO4", "O2", "K2SO4", "H2O"], "c": [2, 5, 3, 2, 5, 1, 8], "if": "разб. H2SO4 (H2O2 — восстановитель)", "bad": [["MnO2", "В кислой среде перманганат восстанавливается до MnSO4 (обесцвечивание)."], ["K2MnO4", "Манганат образуется только в щелочной среде."]], "why": "С более сильным окислителем KMnO4 пероксид H2O2 выступает восстановителем (→ O2↑)."}, {"id": "rx028_h2o2_cl2", "sk": "active_metals", "ref": "02.25", "n": 8, "lvl": 3, "l": ["H2O2", "Cl2"], "r": ["HCl", "O2"], "c": [1, 1, 2, 1], "if": "водный раствор (H2O2 — восстановитель)", "bad": [["HClO", "Хлор окисляет H2O2 до O2↑, сам восстанавливаясь до HCl."], ["H2O", "Здесь H2O2 отдаёт электроны и переходит в O2↑."]], "why": "Сильный окислитель Cl2 окисляет пероксид водорода до кислорода O2↑."}, {"id": "rx029_h2o2_ag2o", "sk": "active_metals", "ref": "02.25", "n": 8, "lvl": 3, "l": ["H2O2", "Ag2O"], "r": ["Ag", "O2", "H2O"], "c": [1, 1, 2, 1, 1], "if": "н.у. (восстановление оксида серебра)", "bad": [["AgOH", "Ag2O восстанавливается пероксидом до металлического серебра Ag."], ["Ag2O2", "В ЕГЭ H2O2 восстанавливает Ag2O до свободного Ag и O2↑."]], "why": "Классическая реакция-ловушка: H2O2 восстанавливает Ag2O до металла Ag с выделением O2↑."}, {"id": "rx030_mgoh2_t", "sk": "active_metals", "ref": "02.28", "n": 8, "lvl": 1, "l": ["Mg(OH)2"], "r": ["MgO", "H2O"], "c": [1, 1, 1], "if": "t° (термическое разложение нерастворимого основания)", "bad": [["Mg", "Гидроксиды активных металлов не разлагаются до свободного металла."], ["H2", "Разложение гидроксида — не ОВР, водород не выделяется."]], "why": "Нерастворимые основания при нагревании разлагаются на оксид металла и воду."}, {"id": "rx031_caoh2_t", "sk": "active_metals", "ref": "02.28", "n": 8, "lvl": 2, "l": ["Ca(OH)2"], "r": ["CaO", "H2O"], "c": [1, 1, 1], "if": "сильное прокаливание (~550 °C)", "bad": [["Ca", "При прокаливании гашёной извести образуется негашёная известь CaO и H2O."], ["CaO2", "Степень окисления кислорода не меняется — образуется CaO."]], "why": "В отличие от NaOH и KOH (плавятся без разложения), Ca(OH)2 и LiOH при прокаливании теряют воду."}, {"id": "rx032_nahco3_koh", "sk": "active_metals", "ref": "02.34", "n": 8, "lvl": 2, "l": ["NaHCO3", "KOH"], "r": ["Na2CO3", "K2CO3", "H2O"], "c": [2, 2, 1, 1, 2], "if": "водный раствор (нейтрализация кислой соли другой щёлочью)", "bad": [["KHCO3", "Щёлочь переводит кислый анион HCO3⁻ в средний CO3^{2−} → смесь двух средних карбонатов."], ["CO2", "Со щёлочью газ CO2 не выделяется (газ идёт с кислотой!)."]], "why": "Кислая соль + щёлочь с другим катионом → две средние соли + вода."}, {"id": "rx033_khco3_baoh2_def", "sk": "active_metals", "ref": "02.34", "n": 8, "lvl": 3, "l": ["KHCO3", "Ba(OH)2"], "r": ["BaCO3", "K2CO3", "H2O"], "c": [2, 1, 1, 1, 2], "if": "недостаток Ba(OH)2 (мольное соотношение 2 : 1)", "bad": [["KOH", "При недостатке Ba(OH)2 весь OH⁻ уходит на нейтрализацию 2HCO3⁻ → остаётся K2CO3, а не KOH."], ["Ba(HCO3)2", "Образуется нерастворимый средний карбонат BaCO3↓."]], "why": "Считай по OH⁻: 1 моль Ba(OH)2 даёт 2 моль OH⁻, нейтрализуя 2 моль HCO3⁻ до 2CO3^{2−} (BaCO3↓ + K2CO3)."}, {"id": "rx034_khco3_baoh2_exc", "sk": "active_metals", "ref": "02.34", "n": 8, "lvl": 3, "l": ["KHCO3", "Ba(OH)2"], "r": ["BaCO3", "KOH", "H2O"], "c": [1, 1, 1, 1, 1], "if": "избыток Ba(OH)2 (мольное соотношение 1 : 1)", "bad": [["K2CO3", "В избытке Ba(OH)2 все карбонат-ионы связываются с Ba^{2+} в BaCO3↓, а в растворе остаётся KOH."], ["Ba(HCO3)2", "В щелочной среде кислый карбонат не существует."]], "why": "В избытке Ba(OH)2 весь CO3^{2−} уходит в осадок BaCO3↓, поэтому второй продукт — щёлочь KOH."}, {"id": "rx035_nahso4_mg", "sk": "active_metals", "ref": "02.34", "n": 8, "lvl": 3, "l": ["NaHSO4", "Mg"], "r": ["MgSO4", "Na2SO4", "H2"], "c": [2, 1, 1, 1, 1], "if": "водный раствор (NaHSO4 как сильная кислота)", "bad": [["Mg(OH)2", "Кислая среда NaHSO4 растворяет магний до соли MgSO4 с выделением H2↑."], ["SO2", "В растворе гидросульфата окислителем выступает H^{+}, выделяется H2↑."]], "why": "Гидросульфаты сильных кислот диссоциируют с отщеплением H^{+} и реагируют с металлами до H."}, {"id": "rx036_nahso4_na2co3", "sk": "active_metals", "ref": "02.34", "n": 8, "lvl": 2, "l": ["NaHSO4", "Na2CO3"], "r": ["Na2SO4", "CO2", "H2O"], "c": [2, 1, 2, 1, 1], "if": "водный раствор (вытеснение слабой H2CO3)", "bad": [["NaHCO3", "При достаточном количестве NaHSO4 карбонат полностью разлагается с выделением CO2↑."], ["SO2", "Сульфат-ион не восстанавливается — идёт реакция ионного обмена."]], "why": "NaHSO4 реагирует с карбонатами, сульфитами и сульфидами точно так же, как разбавленная H2SO4."}, {"id": "rx037_al_h2o", "sk": "amphoteric_al_zn", "ref": "03.4", "n": 8, "lvl": 2, "l": ["Al", "H2O"], "r": ["Al(OH)3", "H2"], "c": [2, 6, 2, 3], "if": "после удаления защитной оксидной плёнки (амальгамированный Al)", "bad": [["Al2O3", "С жидкой водой очищенный алюминий образует гидроксид Al(OH)3↓ и H2↑."], ["AlH3", "Водород выделяется в виде газа H2↑."]], "why": "Оксидная плёнка защищает Al от воды; без неё алюминий активно вытесняет H2↑."}, {"id": "rx038_zn_h2o_steam", "sk": "amphoteric_al_zn", "ref": "03.4", "n": 8, "lvl": 2, "l": ["Zn", "H2O"], "r": ["ZnO", "H2"], "c": [1, 1, 1, 1], "if": "водяной пар, t°", "bad": [["Zn(OH)2", "При нагревании с водяным паром образуется оксид ZnO, а не гидроксид."], ["O2", "Цинк восстанавливает водород воды до H2↑."]], "why": "Цинк (как и железо) реагирует с водяным паром при нагревании с образованием оксида и H2↑."}, {"id": "rx039_al_hcl", "sk": "amphoteric_al_zn", "ref": "03.7", "n": 8, "lvl": 1, "l": ["Al", "HCl"], "r": ["AlCl3", "H2"], "c": [2, 6, 2, 3], "if": "водный раствор HCl", "bad": [["AlCl2", "У алюминия единственная устойчивая СО +3 → AlCl3."], ["Cl2", "Выделяется водород H2↑ (окислитель H^{+})."]], "why": "Алюминий легко растворяется в неокисляющих кислотах с выделением H2↑."}, {"id": "rx040_zn_h2so4_dil", "sk": "amphoteric_al_zn", "ref": "03.7", "n": 8, "lvl": 1, "l": ["Zn", "H2SO4"], "r": ["ZnSO4", "H2"], "c": [1, 1, 1, 1], "if": "разбавленная H2SO4", "bad": [["SO2", "В разбавленной H2SO4 окислитель — H^{+} → выделяется H2↑, а не SO2."], ["H2S", "H2S выделяется только с концентрированной H2SO4."]], "why": "Цинк с разбавленной серной кислотой даёт сульфат цинка и водород H2↑."}, {"id": "rx041_al_naoh_aq", "sk": "amphoteric_al_zn", "ref": "03.10", "n": 8, "lvl": 2, "l": ["Al", "NaOH", "H2O"], "r": ["Na[Al(OH)4]", "H2"], "c": [2, 2, 6, 2, 3], "if": "водный раствор щёлочи", "bad": [["NaAlO2", "Метаалюминат NaAlO2 образуется при сплавлении, а в водном растворе — комплекс Na[Al(OH)4]."], ["Al(OH)3", "В избытке щёлочи гидроксид растворяется до гидроксокомплекса."]], "why": "Амфотерный алюминий растворяется в водном NaOH с выделением 3H2↑ и образованием Na[Al(OH)4]."}, {"id": "rx042_zn_naoh_aq", "sk": "amphoteric_al_zn", "ref": "03.10", "n": 8, "lvl": 2, "l": ["Zn", "NaOH", "H2O"], "r": ["Na2[Zn(OH)4]", "H2"], "c": [1, 2, 2, 1, 1], "if": "водный раствор щёлочи", "bad": [["Na2ZnO2", "Цинкат Na2ZnO2 образуется при сплавлении, а в воде — комплекс Na2[Zn(OH)4]."], ["Na[Zn(OH)4]", "У цинка заряд +2, значит заряд [Zn(OH)4]^{2−} требует два иона Na^{+} → Na2[Zn(OH)4]."]], "why": "Амфотерный цинк в водном растворе щёлочи даёт тетрагидроксоцинкат натрия и H2↑."}, {"id": "rx043_naaloh4_hcl_def", "sk": "amphoteric_al_zn", "ref": "03.18", "n": 8, "lvl": 2, "l": ["Na[Al(OH)4]", "HCl"], "r": ["Al(OH)3", "NaCl", "H2O"], "c": [1, 1, 1, 1, 1], "if": "недостаток HCl (мольное соотношение 1 : 1)", "bad": [["AlCl3", "При недостатке HCl (1 : 1) выпадает белый осадок Al(OH)3↓; AlCl3 образуется в избытке HCl."], ["NaAlO2", "Кислота разрушает комплекс до осадка гидроксида."]], "why": "Один эквивалент HCl снимает одну группу OH⁻ с комплекса, осаждая Al(OH)3↓."}, {"id": "rx044_naaloh4_hcl_exc", "sk": "amphoteric_al_zn", "ref": "03.18", "n": 8, "lvl": 2, "l": ["Na[Al(OH)4]", "HCl"], "r": ["AlCl3", "NaCl", "H2O"], "c": [1, 4, 1, 1, 4], "if": "избыток HCl (мольное соотношение 1 : 4)", "bad": [["Al(OH)3", "В избытке сильной кислоты HCl выпавший Al(OH)3 полностью растворяется до AlCl3."], ["Cl2", "Реакция не является ОВР — хлор не выделяется."]], "why": "Избыток сильной кислоты полностью разрушает гидроксокомплекс до раствора двух солей."}, {"id": "rx045_naaloh4_co2", "sk": "amphoteric_al_zn", "ref": "03.18", "n": 8, "lvl": 3, "l": ["Na[Al(OH)4]", "CO2"], "r": ["Al(OH)3", "NaHCO3"], "c": [1, 1, 1, 1], "if": "избыток CO2 (слабая кислота — осадок не растворяется!)", "bad": [["Na2CO3", "При избытке CO2 образуется кислая соль NaHCO3, а не Na2CO3."], ["Al2(CO3)3", "Карбонат алюминия в воде не существует."]], "why": "Хит № 8 и № 31: избыток CO2 разрушает комплекс строго до Al(OH)3↓ и NaHCO3."}, {"id": "rx046_na2znoh4_co2", "sk": "amphoteric_al_zn", "ref": "03.18", "n": 8, "lvl": 3, "l": ["Na2[Zn(OH)4]", "CO2"], "r": ["Zn(OH)2", "NaHCO3"], "c": [1, 2, 1, 2], "if": "избыток CO2", "bad": [["Na2CO3", "При избытке CO2 всегда образуется кислая соль NaHCO3."], ["ZnCO3", "В ЕГЭ продуктом разрушения цинкатного комплекса углекислым газом считают Zn(OH)2↓."]], "why": "Аналогично алюминию: избыток CO2 даёт осадок Zn(OH)2↓ и 2NaHCO3."}, {"id": "rx047_naaloh4_so2", "sk": "amphoteric_al_zn", "ref": "03.18", "n": 8, "lvl": 3, "l": ["Na[Al(OH)4]", "SO2"], "r": ["Al(OH)3", "NaHSO3"], "c": [1, 1, 1, 1], "if": "избыток SO2", "bad": [["Na2SO3", "При избытке SO2 образуется кислая соль NaHSO3."], ["Al2(SO3)3", "Сульфит алюминия в воде полностью гидролизуется."]], "why": "Избыток сернистого газа осаждает Al(OH)3↓ и переводит натрий в гидросульфит NaHSO3."}, {"id": "rx048_naaloh4_h2s", "sk": "amphoteric_al_zn", "ref": "03.18", "n": 8, "lvl": 3, "l": ["Na[Al(OH)4]", "H2S"], "r": ["Al(OH)3", "NaHS", "H2O"], "c": [1, 1, 1, 1, 1], "if": "избыток H2S", "bad": [["Na2S", "При избытке H2S образуется кислая соль гидросульфид NaHS."], ["Al2S3", "Сульфид алюминия в воде не существует."]], "why": "Слабый сероводород H2S в избытке осаждает Al(OH)3↓ и образует NaHS + H2O."}, {"id": "rx049_naaloh4_nh4cl", "sk": "amphoteric_al_zn", "ref": "03.18", "n": 8, "lvl": 3, "l": ["Na[Al(OH)4]", "NH4Cl"], "r": ["Al(OH)3", "NH3", "NaCl", "H2O"], "c": [1, 1, 1, 1, 1, 1], "if": "водный раствор (разрушение комплекса солью аммония)", "bad": [["AlCl3", "Катион NH4^{+} связывает OH⁻ в NH3 + H2O, осаждая Al(OH)3↓."], ["NH4[Al(OH)4]", "Ион NH4^{+} и [Al(OH)4]⁻ несовместимы в растворе — идёт реакция с выделением NH3↑."]], "why": "Соли аммония разрушают гидроксокомплекс алюминия с выпадением Al(OH)3↓ и выделением NH3↑."}, {"id": "rx050_alcl3_nh3h2o", "sk": "amphoteric_al_zn", "ref": "03.23", "n": 8, "lvl": 2, "l": ["AlCl3", "NH3·H2O"], "r": ["Al(OH)3", "NH4Cl"], "c": [1, 3, 1, 3], "if": "избыток водного аммиака (осадок НЕ растворяется!)", "bad": [["NH4[Al(OH)4]", "Al(OH)3 не растворяется в водном аммиаке NH3·H2O."], ["[Al(NH3)6]Cl3", "Алюминий не образует водных аммиачных комплексов."]], "why": "Главное отличие от Zn(OH)2 и Cu(OH)2: Al(OH)3 в избытке NH3·H2O остаётся в осадке."}, {"id": "rx051_znoh2_nh3h2o", "sk": "amphoteric_al_zn", "ref": "03.23", "n": 8, "lvl": 3, "l": ["Zn(OH)2", "NH3·H2O"], "r": ["[Zn(NH3)4](OH)2", "H2O"], "c": [1, 4, 1, 4], "if": "избыток водного аммиака (образование аммиаката)", "bad": [["(NH4)2[Zn(OH)4]", "С водным аммиаком цинк образует аммиачный комплекс [Zn(NH3)4](OH)2."], ["ZnO", "Осадок полностью растворяется в избытке NH3·H2O."]], "why": "Цинк (как и медь Cu) образует растворимый тетрааммингидроксид [Zn(NH3)4](OH)2."}, {"id": "rx052_al2s3_h2o", "sk": "amphoteric_al_zn", "ref": "03.26", "n": 8, "lvl": 2, "l": ["Al2S3", "H2O"], "r": ["Al(OH)3", "H2S"], "c": [1, 6, 2, 3], "if": "необратимый гидролиз бинарного сульфида", "bad": [["Al(HS)3", "Сульфид алюминия гидролизуется водой полностью до Al(OH)3↓ и H2S↑."], ["SO2", "Реакция не является ОВР — выделяется H2S↑."]], "why": "Прочерк в таблице растворимости ФИПИ: Al2S3 нацело разлагается водой."}, {"id": "rx053_alcl3_na2co3_h2o", "sk": "amphoteric_al_zn", "ref": "03.26", "n": 8, "lvl": 2, "l": ["AlCl3", "Na2CO3", "H2O"], "r": ["Al(OH)3", "CO2", "NaCl"], "c": [2, 3, 3, 2, 3, 6], "if": "совместный необратимый гидролиз в растворе", "bad": [["Al2(CO3)3", "Карбонат алюминия в воде не существует — идёт совместный гидролиз."], ["NaHCO3", "Выделяется углекислый газ CO2↑ и выпадает Al(OH)3↓."]], "why": "Классика № 6, 8, 30, 31: соль Al^{3+} + карбонат → Al(OH)3↓ + CO2↑."}, {"id": "rx054_alcl3_nahco3", "sk": "amphoteric_al_zn", "ref": "03.26", "n": 8, "lvl": 3, "l": ["AlCl3", "NaHCO3"], "r": ["Al(OH)3", "CO2", "NaCl"], "c": [1, 3, 1, 3, 3], "if": "совместный гидролиз с гидрокарбонатом (вода не нужна в левой части!)", "bad": [["Al(HCO3)3", "Гидрокарбонат алюминия не существует в воде."], ["Na2CO3", "Продукты — осадок Al(OH)3↓, газ 3CO2↑ и 3NaCl."]], "why": "Обрати внимание на баланс: 3NaHCO3 уже содержат 3 атома H для Al(OH)3, поэтому H2O в уравнении нет!"}, {"id": "rx055_alno33_k2s_h2o", "sk": "amphoteric_al_zn", "ref": "03.26", "n": 8, "lvl": 2, "l": ["Al(NO3)3", "K2S", "H2O"], "r": ["Al(OH)3", "H2S", "KNO3"], "c": [2, 3, 6, 2, 3, 6], "if": "совместный необратимый гидролиз", "bad": [["Al2S3", "Сульфид алюминия в воде не существует."], ["S", "Al^{3+} не окислитель (в отличие от Fe^{3+}) — идёт гидролиз, а не ОВР."]], "why": "Сравни: Al^{3+} + S^{2−} → совместный гидролиз (Al(OH)3↓ + H2S↑), а Fe^{3+} + S^{2−} → ОВР!"}, {"id": "rx056_fe_o2", "sk": "transition_fe_cr_cu", "ref": "04.6", "n": 8, "lvl": 2, "l": ["Fe", "O2"], "r": ["Fe3O4"], "c": [3, 2, 1], "if": "t° (горение железа в кислороде)", "bad": [["Fe2O3", "При горении железа в кислороде образуется железная окалина Fe3O4 (FeO·Fe2O3)."], ["FeO", "В кислороде образуется смешанный оксид Fe3O4."]], "why": "Горение Fe в O2 всегда даёт окалину Fe3O4."}, {"id": "rx057_fe_h2o_steam", "sk": "transition_fe_cr_cu", "ref": "04.6", "n": 8, "lvl": 2, "l": ["Fe", "H2O"], "r": ["Fe3O4", "H2"], "c": [3, 4, 1, 4], "if": "водяной пар, красное каление (>570 °C)", "bad": [["Fe(OH)3", "С водяным паром при высокой температуре железо даёт окалину Fe3O4 и H2↑."], ["Fe2O3", "Продуктом реакции раскалённого железа с паром в ЕГЭ является Fe3O4."]], "why": "Раскалённое железо с водяным паром образует Fe3O4 и 4H2↑."}, {"id": "rx058_fe3o4_hcl", "sk": "transition_fe_cr_cu", "ref": "04.8", "n": 8, "lvl": 2, "l": ["Fe3O4", "HCl"], "r": ["FeCl2", "FeCl3", "H2O"], "c": [1, 8, 1, 2, 4], "if": "неокисляющая кислота HCl", "bad": [["FeCl3", "Fe3O4 = FeO·Fe2O3, поэтому с неокисляющей HCl образуется смесь FeCl2 и 2FeCl3."], ["H2", "Реакция оксида с кислотой не выделяет водород."]], "why": "С неокисляющими кислотами (HCl, H2SO4 разб.) окалина даёт смесь солей Fe(+2) и Fe(+3)."}, {"id": "rx059_fe3o4_hno3", "sk": "transition_fe_cr_cu", "ref": "04.8", "n": 8, "lvl": 3, "l": ["Fe3O4", "HNO3"], "r": ["Fe(NO3)3", "NO2", "H2O"], "c": [1, 10, 3, 1, 5], "if": "конц. HNO3, t° (окисление Fe(+2) до Fe(+3))", "bad": [["Fe(NO3)2", "Концентрированная HNO3 доокисляет Fe(+2) до Fe(+3) → только 3Fe(NO3)3."], ["NO", "Концентрированная HNO3 восстанавливается до бурого газа NO2↑."]], "why": "Азотная кислота переводит всё железо из Fe3O4 в степень окисления +3."}, {"id": "rx060_fe3o4_hi", "sk": "transition_fe_cr_cu", "ref": "04.8", "n": 8, "lvl": 3, "l": ["Fe3O4", "HI"], "r": ["FeI2", "I2", "H2O"], "c": [1, 8, 3, 1, 4], "if": "иодоводородная кислота HI (восстановление Fe(+3) до Fe(+2))", "bad": [["FeI3", "FeI3 не существует: иодид-ион восстанавливает 2Fe(+3) до Fe(+2) с выделением I2."], ["H2", "Оксид с кислотой не выделяет H2; идёт ОВР с выделением I2."]], "why": "Кислота-восстановитель HI переводит всё железо из Fe3O4 в FeI2 (+2)."}, {"id": "rx061_feoh2_o2_h2o", "sk": "transition_fe_cr_cu", "ref": "04.11", "n": 8, "lvl": 2, "l": ["Fe(OH)2", "O2", "H2O"], "r": ["Fe(OH)3"], "c": [4, 1, 2, 4], "if": "на воздухе (побурение осадка)", "bad": [["Fe2O3", "Во влажной среде на воздухе Fe(OH)2 окисляется до бурого осадка Fe(OH)3."], ["H2O2", "Кислород восстанавливается до OH⁻ в составе Fe(OH)3."]], "why": "Бело-зелёный осадок Fe(OH)2 быстро буреет на воздухе, превращаясь в Fe(OH)3."}, {"id": "rx062_feoh3_naoh_melt", "sk": "transition_fe_cr_cu", "ref": "04.13", "n": 8, "lvl": 3, "l": ["Fe(OH)3", "NaOH"], "r": ["NaFeO2", "H2O"], "c": [1, 1, 1, 2], "if": "сплавление твёрдых веществ (в воде не идёт!)", "bad": [["Na[Fe(OH)4]", "В ЕГЭ ферриты получают только сплавлением до безводного NaFeO2 + 2H2O."], ["Na2FeO4", "Без окислителя степень окисления железа остаётся +3 (феррит NaFeO2)."]], "why": "При сплавлении с твёрдым NaOH гидроксид железа(III) образует феррит NaFeO2."}, {"id": "rx063_fe2o3_na2co3_melt", "sk": "transition_fe_cr_cu", "ref": "04.13", "n": 8, "lvl": 3, "l": ["Fe2O3", "Na2CO3"], "r": ["NaFeO2", "CO2"], "c": [1, 1, 2, 1], "if": "сплавление твёрдых веществ", "bad": [["Fe2(CO3)3", "При сплавлении амфотерный Fe2O3 вытесняет летучий CO2↑ с образованием NaFeO2."], ["Na2FeO4", "Степень окисления железа не меняется (+3)."]], "why": "Аналогично Al2O3: при сплавлении с Na2CO3 образуется феррит NaFeO2 и CO2↑."}, {"id": "rx064_feoh3_cl2_naoh", "sk": "transition_fe_cr_cu", "ref": "04.13", "n": 8, "lvl": 3, "l": ["Fe(OH)3", "Cl2", "NaOH"], "r": ["Na2FeO4", "NaCl", "H2O"], "c": [2, 3, 10, 2, 6, 8], "if": "конц. щёлочь (окисление Fe(+3) до феррата Fe(+6))", "bad": [["NaFeO2", "Сильный окислитель Cl2 в щёлочи переводит Fe(+3) в малиновый феррат Na2FeO4 (+6)."], ["FeCl3", "В избытке щёлочи хлорид железа(III) существовать не может."]], "why": "Реакция на 95–100 баллов: окисление Fe(OH)3 хлором в щёлочи до феррата натрия Na2FeO4."}, {"id": "rx065_fecl3_ki", "sk": "transition_fe_cr_cu", "ref": "04.15", "n": 8, "lvl": 3, "l": ["FeCl3", "KI"], "r": ["FeCl2", "I2", "KCl"], "c": [2, 2, 2, 1, 2], "if": "водный раствор (ОВР!)", "bad": [["FeI3", "FeI3 не существует — идёт ОВР с образованием FeCl2 и I2."], ["Fe(OH)3", "С иодидом идёт ОВР, а не гидролиз."]], "why": "Антипаттерн № 3: Fe^{3+} окисляет I⁻ до I2, восстанавливаясь до Fe^{2+}."}, {"id": "rx066_fecl3_h2s", "sk": "transition_fe_cr_cu", "ref": "04.15", "n": 8, "lvl": 3, "l": ["FeCl3", "H2S"], "r": ["FeCl2", "S", "HCl"], "c": [2, 1, 2, 1, 2], "if": "водный раствор (ОВР, выпадение жёлтой серы S↓)", "bad": [["Fe2S3", "Fe2S3 в воде не образуется — Fe^{3+} окисляет H2S до жёлтой серы S↓."], ["FeS", "В кислой среде (выделяется HCl) сульфид FeS не выпадает."]], "why": "Пропускание H2S через FeCl3 даёт жёлтый осадок серы S↓ и бледно-зелёный FeCl2."}, {"id": "rx067_fecl3_na2s_def", "sk": "transition_fe_cr_cu", "ref": "04.15", "n": 8, "lvl": 3, "l": ["FeCl3", "Na2S"], "r": ["FeCl2", "S", "NaCl"], "c": [2, 1, 2, 1, 2], "if": "недостаток Na2S (соотношение 2 : 1, ОВР)", "bad": [["Fe2S3", "Fe^{3+} окисляет S^{2−} до серы S↓."], ["Fe(OH)3", "Идёт ОВР, а не совместный гидролиз!"]], "why": "При недостатке Na2S весь сульфид-ион окисляется до S↓, а железо остаётся в растворе в виде FeCl2."}, {"id": "rx068_fecl3_na2s_exc", "sk": "transition_fe_cr_cu", "ref": "04.15", "n": 8, "lvl": 3, "l": ["FeCl3", "Na2S"], "r": ["FeS", "S", "NaCl"], "c": [2, 3, 2, 1, 6], "if": "избыток Na2S (соотношение 2 : 3, ОВР + осаждение FeS↓)", "bad": [["Fe2S3", "Ион Fe^{3+} восстанавливается до Fe^{+2}, затем избыток S^{2−} осаждает чёрный FeS↓."], ["Fe(OH)3", "С сульфидами железо(III) вступает в ОВР, а не в совместный гидролиз."]], "why": "Избыток Na2S сначала восстанавливает 2FeCl3 до 2FeCl2 + S↓, а затем осаждает 2FeS↓."}, {"id": "rx069_fecl3_na2so3_h2o", "sk": "transition_fe_cr_cu", "ref": "04.15", "n": 8, "lvl": 3, "l": ["FeCl3", "Na2SO3", "H2O"], "r": ["FeCl2", "Na2SO4", "HCl"], "c": [2, 1, 1, 2, 1, 2], "if": "водный раствор (ОВР, окисление сульфита до сульфата)", "bad": [["Fe2(SO3)3", "Fe^{3+} окисляет SO3^{2−} до SO4^{2−}, сам восстанавливаясь до Fe^{2+}."], ["Fe(OH)3", "С сульфитами соли Fe(III) вступают в ОВР, а не в совместный гидролиз."]], "why": "Запомни: с CO3^{2−} у Fe^{3+} совместный гидролиз, а с I⁻, S^{2−}, SO3^{2−} — всегда ОВР!"}, {"id": "rx070_k2cro4_h2so4", "sk": "transition_fe_cr_cu", "ref": "04.21", "n": 8, "lvl": 2, "l": ["K2CrO4", "H2SO4"], "r": ["K2Cr2O7", "K2SO4", "H2O"], "c": [2, 1, 1, 1, 1], "if": "подкисление (жёлтый → оранжевый, НЕ ОВР!)", "bad": [["Cr2(SO4)3", "Без восстановителя Cr(+6) не восстанавливается — просто переходит в дихромат."], ["O2", "Реакция не является ОВР."]], "why": "В кислой среде жёлтый хромат K2CrO4 переходит в оранжевый дихромат K2Cr2O7."}, {"id": "rx071_k2cr2o7_koh", "sk": "transition_fe_cr_cu", "ref": "04.21", "n": 8, "lvl": 2, "l": ["K2Cr2O7", "KOH"], "r": ["K2CrO4", "H2O"], "c": [1, 2, 2, 1], "if": "подщелачивание (оранжевый → жёлтый, НЕ ОВР!)", "bad": [["K[Cr(OH)4]", "Без восстановителя Cr(+6) не восстанавливается до Cr(+3)."], ["Cr(OH)3", "Дихромат в щёлочи переходит в жёлтый раствор хромата K2CrO4."]], "why": "В щелочной среде оранжевый дихромат переходит в жёлтый хромат без изменения СО хрома."}, {"id": "rx072_nacroh4_h2o2_naoh", "sk": "transition_fe_cr_cu", "ref": "04.21", "n": 8, "lvl": 3, "l": ["Na[Cr(OH)4]", "H2O2", "NaOH"], "r": ["Na2CrO4", "H2O"], "c": [2, 3, 2, 2, 8], "if": "щелочная среда (зелёный → жёлтый)", "bad": [["Na2Cr2O7", "В щелочной среде устойчив только хромат Na2CrO4 (жёлтый), не дихромат."], ["O2", "H2O2 здесь окислитель (переходит в H2O), кислород не выделяется."]], "why": "Классическое окисление Cr(+3) до жёлтого хромата Cr(+6) в щелочной среде."}, {"id": "rx073_cr2o3_kno3_k2co3", "sk": "transition_fe_cr_cu", "ref": "04.21", "n": 8, "lvl": 3, "l": ["Cr2O3", "KNO3", "K2CO3"], "r": ["K2CrO4", "KNO2", "CO2"], "c": [1, 3, 2, 2, 3, 2], "if": "сплавление (окисление Cr2O3 до хромата)", "bad": [["K2Cr2O7", "В щелочном расплаве с K2CO3 образуется жёлтый хромат K2CrO4."], ["NO2", "Нитрат калия в расплаве восстанавливается до нитрита KNO2."]], "why": "Щелочное окислительное сплавление Cr2O3 — частая реакция № 31."}, {"id": "rx074_k2cr2o7_hcl", "sk": "transition_fe_cr_cu", "ref": "04.21", "n": 8, "lvl": 2, "l": ["K2Cr2O7", "HCl"], "r": ["CrCl3", "Cl2", "KCl", "H2O"], "c": [1, 14, 2, 3, 2, 7], "if": "конц. HCl, t° (получение хлора)", "bad": [["CrCl2", "В кислой среде Cr(+6) восстанавливается до Cr(+3) (CrCl3)."], ["KClO3", "Хлорид-ион окисляется дихроматом до жёлто-зелёного газа Cl2↑."]], "why": "Лабораторный способ получения хлора Cl2↑ (оранжевый раствор становится зелёным)."}, {"id": "rx075_k2cr2o7_ki_h2so4", "sk": "transition_fe_cr_cu", "ref": "04.21", "n": 8, "lvl": 2, "l": ["K2Cr2O7", "KI", "H2SO4"], "r": ["Cr2(SO4)3", "I2", "K2SO4", "H2O"], "c": [1, 6, 7, 1, 3, 4, 7], "if": "разб. H2SO4 (выпадение тёмного осадка I2↓)", "bad": [["CrSO4", "Хром(+6) восстанавливается до Cr(+3) — сульфата хрома(III)."], ["KIO3", "Иодид-ион окисляется до свободного иода I2↓."]], "why": "Эталонная ОВР дихромата с иодидом калия в кислой среде."}, {"id": "rx076_nh42cr2o7_t", "sk": "transition_fe_cr_cu", "ref": "04.21", "n": 8, "lvl": 2, "l": ["(NH4)2Cr2O7"], "r": ["N2", "Cr2O3", "H2O"], "c": [1, 1, 1, 4], "if": "t° (термическое разложение, «вулканчик»)", "bad": [["NH3", "Внутримолекулярная ОВР: N^{−3} окисляется дихроматом до N2↑, а не выделяется NH3."], ["CrO3", "Хром(+6) восстанавливается до тёмно-зелёного оксида Cr2O3."]], "why": "Разложение дихромата аммония — знаменитый «вулканчик» (оранжевые кристаллы → зелёный Cr2O3)."}, {"id": "rx077_kmno4_t", "sk": "transition_fe_cr_cu", "ref": "04.24", "n": 8, "lvl": 1, "l": ["KMnO4"], "r": ["K2MnO4", "MnO2", "O2"], "c": [2, 1, 1, 1], "if": "t° (лабораторное получение кислорода)", "bad": [["K2O", "Перманганат калия разлагается до манганата K2MnO4, бурого MnO2 и O2↑."], ["MnO", "Марганец восстанавливается до +6 и +4, а не до +2."]], "why": "Главный лабораторный способ получения кислорода O2↑ в ЕГЭ."}, {"id": "rx078_kmno4_hcl", "sk": "transition_fe_cr_cu", "ref": "04.24", "n": 8, "lvl": 1, "l": ["KMnO4", "HCl"], "r": ["KCl", "MnCl2", "Cl2", "H2O"], "c": [2, 16, 2, 2, 5, 8], "if": "конц. HCl (получение хлора без нагревания)", "bad": [["MnO2", "В сильнокислой среде HCl перманганат восстанавливается до MnCl2 (+2)."], ["KClO3", "Выделяется жёлто-зелёный газ Cl2↑."]], "why": "Классический лабораторный способ получения Cl2↑ (баланс: 2 и 5)."}, {"id": "rx079_mno2_hcl", "sk": "transition_fe_cr_cu", "ref": "04.24", "n": 8, "lvl": 2, "l": ["MnO2", "HCl"], "r": ["MnCl2", "Cl2", "H2O"], "c": [1, 4, 1, 1, 2], "if": "конц. HCl, t° (метод Шееле)", "bad": [["MnCl4", "Хлорид марганца(IV) неустойчив и разлагается до MnCl2 и Cl2↑."], ["O2", "MnO2 окисляет хлорид-ион до хлора Cl2↑."]], "why": "Растворение бурого осадка MnO2 в конц. HCl с выделением Cl2↑ — частый шаг в № 31."}, {"id": "rx080_kmno4_na2so3_h2o", "sk": "transition_fe_cr_cu", "ref": "04.24", "n": 8, "lvl": 2, "l": ["KMnO4", "Na2SO3", "H2O"], "r": ["MnO2", "Na2SO4", "KOH"], "c": [2, 3, 1, 2, 3, 2], "if": "нейтральная среда (бурый осадок MnO2↓)", "bad": [["MnSO4", "В нейтральной среде Mn(+7) восстанавливается до бурого осадка MnO2↓."], ["K2MnO4", "Манганат образуется только в щелочной среде."]], "why": "В воде перманганат всегда даёт бурый осадок MnO2↓ и щёлочь KOH."}, {"id": "rx081_kmno4_na2so3_koh", "sk": "transition_fe_cr_cu", "ref": "04.24", "n": 8, "lvl": 2, "l": ["KMnO4", "Na2SO3", "KOH"], "r": ["K2MnO4", "Na2SO4", "H2O"], "c": [2, 1, 2, 2, 1, 1], "if": "щелочная среда (изумрудно-зелёный раствор K2MnO4)", "bad": [["MnO2", "В щёлочи Mn(+7) принимает 1e⁻ и переходит в зелёный раствор K2MnO4."], ["Mn(OH)2", "В щелочной среде перманганат восстанавливается только до +6."]], "why": "Малиновый раствор KMnO4 в щёлочи с восстановителем становится зелёным (K2MnO4)."}, {"id": "rx082_cu_o2", "sk": "transition_fe_cr_cu", "ref": "04.27", "n": 8, "lvl": 1, "l": ["Cu", "O2"], "r": ["CuO"], "c": [2, 1, 2], "if": "t° (прокаливание меди на воздухе)", "bad": [["Cu2O", "В избытке кислорода при умеренном нагревании образуется чёрный CuO."], ["CuO2", "Медь не образует пероксидов при горении."]], "why": "Красная медь при прокаливании на воздухе покрывается чёрным оксидом CuO."}, {"id": "rx083_cu_s", "sk": "transition_fe_cr_cu", "ref": "04.27", "n": 8, "lvl": 3, "l": ["Cu", "S"], "r": ["Cu2S"], "c": [2, 1, 1], "if": "t° (ловушка! сера — слабый окислитель)", "bad": [["CuS", "Сера — слабый окислитель и переводит медь в +1: образуется Cu2S, а не CuS!"], ["CuSO4", "В реакции нет кислорода."]], "why": "Обязательная ловушка ЕГЭ: 2Cu + S —t°→ Cu2S (как и Fe + S → FeS)."}, {"id": "rx084_cu_fecl3", "sk": "transition_fe_cr_cu", "ref": "04.27", "n": 8, "lvl": 3, "l": ["Cu", "FeCl3"], "r": ["CuCl2", "FeCl2"], "c": [1, 2, 1, 2], "if": "водный раствор (травление медных плат)", "bad": [["Fe", "Медь правее железа в ряду напряжений — она не вытесняет Fe, а восстанавливает Fe(+3) до Fe(+2)!"], ["CuCl", "В растворе образуется растворимый хлорид меди(II) CuCl2."]], "why": "Хит № 7 и № 8: медь реагирует с раствором FeCl3 (и Fe2(SO4)3) за счёт окислителя Fe^{3+}."}, {"id": "rx085_cu_agno3", "sk": "transition_fe_cr_cu", "ref": "04.27", "n": 8, "lvl": 1, "l": ["Cu", "AgNO3"], "r": ["Cu(NO3)2", "Ag"], "c": [1, 2, 1, 2], "if": "водный раствор (вытеснение серебра)", "bad": [["CuNO3", "В растворе образуется голубой нитрат меди(II) Cu(NO3)2."], ["Ag2O", "Медь стоит левее серебра и вытесняет металлическое Ag."]], "why": "Медь вытесняет из растворов солей металлы, стоящие правее неё (Ag, Hg)."}, {"id": "rx086_cu_hno3_conc", "sk": "transition_fe_cr_cu", "ref": "04.27", "n": 8, "lvl": 1, "l": ["Cu", "HNO3"], "r": ["Cu(NO3)2", "NO2", "H2O"], "c": [1, 4, 1, 2, 2], "if": "конц. HNO3 (бурый газ NO2↑)", "bad": [["H2", "Азотная кислота никогда не выделяет водород H2↑ с металлами."], ["NO", "Бесцветный NO выделяется с разбавленной HNO3, с концентрированной — бурый NO2↑."]], "why": "Растворение меди в конц. HNO3 — классический источник бурого газа NO2↑."}, {"id": "rx087_cu_h2so4_conc", "sk": "transition_fe_cr_cu", "ref": "04.27", "n": 8, "lvl": 1, "l": ["Cu", "H2SO4"], "r": ["CuSO4", "SO2", "H2O"], "c": [1, 2, 1, 1, 2], "if": "конц. H2SO4, t°", "bad": [["H2", "Концентрированная серная кислота не выделяет H2↑; медь восстанавливает S^{+6} до SO2↑."], ["H2S", "H2S с конц. H2SO4 дают активные металлы (Zn, Mg), а медь даёт SO2↑."]], "why": "С разбавленной H2SO4 медь не реагирует, а с горячей конц. H2SO4 даёт CuSO4 + SO2↑ + 2H2O."}, {"id": "rx088_cuso4_ki", "sk": "transition_fe_cr_cu", "ref": "04.30", "n": 8, "lvl": 3, "l": ["CuSO4", "KI"], "r": ["CuI", "I2", "K2SO4"], "c": [2, 4, 2, 1, 2], "if": "водный раствор (ОВР, белый осадок CuI↓ + бурый I2↓)", "bad": [["CuI2", "Иодид меди(II) CuI2 не существует — Cu^{2+} окисляет I⁻ до I2 и переходит в CuI↓."], ["Cu", "Медь восстанавливается до +1 (белый осадок CuI↓), а не до металла."]], "why": "Знаменитая ловушка № 6, 8, 29, 31: 2CuSO4 + 4KI → 2CuI↓ + I2↓ + 2K2SO4."}, {"id": "rx089_agno3_naoh", "sk": "transition_fe_cr_cu", "ref": "04.30", "n": 8, "lvl": 2, "l": ["AgNO3", "NaOH"], "r": ["Ag2O", "NaNO3", "H2O"], "c": [2, 2, 1, 2, 1], "if": "водный раствор (AgOH неустойчив!)", "bad": [["AgOH", "Гидроксид серебра AgOH мгновенно распадается на бурый осадок Ag2O↓ и воду."], ["Ag", "Реакция обмена — серебро не восстанавливается до металла."]], "why": "В таблице растворимости ФИПИ напротив AgOH стоит прочерк: сразу пиши Ag2O↓ + H2O."}, {"id": "rx090_cl2_nabr", "sk": "halogens", "ref": "05.4", "n": 8, "lvl": 1, "l": ["Cl2", "NaBr"], "r": ["NaCl", "Br2"], "c": [1, 2, 2, 1], "if": "водный раствор (вытеснение галогена)", "bad": [["NaBrO", "Более активный хлор вытесняет бром Br2 из бромида."], ["HBr", "Вода в реакции не участвует."]], "why": "В ряду Cl2 → Br2 → I2 каждый более активный галоген вытесняет менее активный из раствора соли."}, {"id": "rx091_cl2_ki", "sk": "halogens", "ref": "05.4", "n": 8, "lvl": 1, "l": ["Cl2", "KI"], "r": ["KCl", "I2"], "c": [1, 2, 2, 1], "if": "водный раствор (выпадение I2↓)", "bad": [["KIO3", "В обычных условиях хлор вытесняет свободный иод I2."], ["HI", "Образуются KCl и I2."]], "why": "Хлор вытесняет иод из водного раствора KI (раствор буреет, выпадает I2↓)."}, {"id": "rx092_br2_ki", "sk": "halogens", "ref": "05.4", "n": 8, "lvl": 1, "l": ["Br2", "KI"], "r": ["KBr", "I2"], "c": [1, 2, 2, 1], "if": "водный раствор", "bad": [["KBrO3", "Бром сильнее иода и вытесняет его до I2↓."], ["IBr", "В водной среде идёт вытеснение I2."]], "why": "Бромная вода окисляет иодид-ион до свободного иода I2↓."}, {"id": "rx093_f2_h2o", "sk": "halogens", "ref": "05.6", "n": 8, "lvl": 3, "l": ["F2", "H2O"], "r": ["HF", "O2"], "c": [2, 2, 4, 1], "if": "н.у. (горение воды во фторе!)", "bad": [["HFO", "Фтор — самый электроотрицательный элемент, он окисляет воду до O2↑, не образуя HFO."], ["H2", "Выделяется кислород O2↑, а не водород."]], "why": "Фтор не вытесняет галогены из водных растворов солей, так как мгновенно окисляет воду до O2↑."}, {"id": "rx094_h2_cl2", "sk": "halogens", "ref": "05.8", "n": 8, "lvl": 1, "l": ["H2", "Cl2"], "r": ["HCl"], "c": [1, 1, 2], "if": "на свету (hν) или при поджигании", "bad": [["HClO", "В реакции нет кислорода — образуется хлороводород HCl."], ["H2Cl2", "Формула хлороводорода — HCl."]], "why": "Синтез хлороводорода HCl на свету идёт по цепному радикальному механизму со взрывом."}, {"id": "rx095_p_cl2_def", "sk": "halogens", "ref": "05.8", "n": 8, "lvl": 2, "l": ["P", "Cl2"], "r": ["PCl3"], "c": [2, 3, 2], "if": "недостаток хлора Cl2", "bad": [["PCl5", "Пентахлорид PCl5 образуется в ИЗБЫТКЕ хлора; в недостатке — PCl3."], ["PCl", "Фосфор в хлоридах имеет степени окисления +3 и +5."]], "why": "Недостаток окислителя переводит фосфор в промежуточную степень окисления +3 (PCl3)."}, {"id": "rx096_p_cl2_exc", "sk": "halogens", "ref": "05.8", "n": 8, "lvl": 2, "l": ["P", "Cl2"], "r": ["PCl5"], "c": [2, 5, 2], "if": "избыток хлора Cl2", "bad": [["PCl3", "В избытке хлора фосфор окисляется до высшей СО +5 (PCl5)."], ["P2Cl5", "Формула пентахлорида фосфора — PCl5."]], "why": "В избытке Cl2 образуется твёрдый пентахлорид PCl5."}, {"id": "rx097_cl2_nh3_exc", "sk": "halogens", "ref": "05.8", "n": 8, "lvl": 3, "l": ["Cl2", "NH3"], "r": ["N2", "NH4Cl"], "c": [3, 8, 1, 6], "if": "избыток аммиака NH3", "bad": [["HCl", "Выделяющийся HCl сразу связывается избытком аммиака в соль NH4Cl."], ["NO", "В реакции нет кислорода — аммиак окисляется до свободного азота N2↑."]], "why": "Избыток NH3 связывает HCl в дым хлорида аммония NH4Cl."}, {"id": "rx098_cl2_h2o", "sk": "halogens", "ref": "05.11", "n": 8, "lvl": 2, "l": ["Cl2", "H2O"], "r": ["HCl", "HClO"], "c": [1, 1, 1, 1], "if": "н.у., обратимое диспропорционирование (хлорная вода)", "bad": [["O2", "Кислород при н.у. выделяет фтор F2; хлор с водой даёт смесь HCl и HClO."], ["HClO3", "Хлорноватая кислота при растворении Cl2 в холодной воде не образуется."]], "why": "Хлор обратимо диспропорционирует в воде до −1 (HCl) и +1 (HClO).", "rev": true}, {"id": "rx099_cl2_koh_cold", "sk": "halogens", "ref": "05.13", "n": 8, "lvl": 2, "l": ["Cl2", "KOH"], "r": ["KCl", "KClO", "H2O"], "c": [1, 2, 1, 1, 1], "if": "холодный раствор щёлочи", "bad": [["KClO3", "Хлорат KClO3 образуется при НАГРЕВАНИИ; на холоде — гипохлорит KClO."], ["KClO4", "Перхлорат в этой реакции не образуется."]], "why": "Диспропорционирование Cl2 на холоде: 0 → −1 (KCl) и +1 (KClO)."}, {"id": "rx100_cl2_koh_hot", "sk": "halogens", "ref": "05.13", "n": 8, "lvl": 2, "l": ["Cl2", "KOH"], "r": ["KCl", "KClO3", "H2O"], "c": [3, 6, 5, 1, 3], "if": "горячий раствор щёлочи, t°", "bad": [["KClO", "В горячей щёлочи гипохлорит неустойчив — образуется хлорат KClO3."], ["KClO4", "Перхлорат получают разложением KClO3 без катализатора."]], "why": "Диспропорционирование Cl2 при нагревании: 0 → −1 (5KCl) и +5 (KClO3)."}, {"id": "rx101_sio2_hf", "sk": "halogens", "ref": "05.16", "n": 8, "lvl": 2, "l": ["SiO2", "HF"], "r": ["SiF4", "H2O"], "c": [1, 4, 1, 2], "if": "травление стекла плавиковой кислотой", "bad": [["H2SiO3", "С избытком HF образуется газообразный фторид SiF4↑ и вода."], ["F2", "Реакция не является ОВР — фтор не выделяется."]], "why": "Единственная кислота в ЕГЭ, растворяющая оксид кремния(IV) SiO2."}, {"id": "rx102_kclo3_kat", "sk": "halogens", "ref": "05.22", "n": 8, "lvl": 2, "l": ["KClO3"], "r": ["KCl", "O2"], "c": [2, 2, 3], "if": "t°, катализатор MnO2", "bad": [["KClO4", "Перхлорат KClO4 образуется при нагревании БЕЗ катализатора."], ["K2O", "Хлорат калия разлагается до KCl и O2↑."]], "why": "С катализатором MnO2 бертолетова соль разлагается на KCl и кислород O2↑."}, {"id": "rx103_kclo3_nokat", "sk": "halogens", "ref": "05.22", "n": 8, "lvl": 3, "l": ["KClO3"], "r": ["KClO4", "KCl"], "c": [4, 3, 1], "if": "t° (~400 °C), БЕЗ катализатора (диспропорционирование)", "bad": [["O2", "Без катализатора идёт диспропорционирование Cl(+5) → Cl(+7) и Cl(−1) без выделения O2."], ["KClO", "Образуются устойчивые перхлорат KClO4 и хлорид KCl."]], "why": "Запомни пару условий для KClO3: с MnO2 → KCl + O2↑; без катализатора → 3KClO4 + KCl."}, {"id": "rx104_fe_s", "sk": "sulfur_compounds", "ref": "06.5", "n": 8, "lvl": 1, "l": ["Fe", "S"], "r": ["FeS"], "c": [1, 1, 1], "if": "t° (сера — слабый окислитель)", "bad": [["Fe2S3", "Сера окисляет железо только до +2 (чёрный сульфид FeS)."], ["FeS2", "При сплавлении стехиометрических количеств Fe и S в ЕГЭ образуется FeS."]], "why": "Сера и иод окисляют железо только до степени окисления +2."}, {"id": "rx105_al_s", "sk": "sulfur_compounds", "ref": "06.5", "n": 8, "lvl": 1, "l": ["Al", "S"], "r": ["Al2S3"], "c": [2, 3, 1], "if": "t° (синтез сульфида алюминия)", "bad": [["AlS", "Al(+3) и S(−2) дают формулу Al2S3."], ["Al(OH)3", "В безводной смеси простых веществ образуется Al2S3 (в воде он гидролизуется)."]], "why": "Сульфид алюминия Al2S3 получают только безводным синтезом из простых веществ."}, {"id": "rx106_s_o2", "sk": "sulfur_compounds", "ref": "06.7", "n": 8, "lvl": 1, "l": ["S", "O2"], "r": ["SO2"], "c": [1, 1, 1], "if": "t° (горение серы на воздухе / в O2)", "bad": [["SO3", "Антипаттерн № 4: при сжигании серы в O2 образуется ТОЛЬКО SO2!"], ["H2SO4", "В реакции нет водорода."]], "why": "Получить SO3 напрямую из серы в одну стадию нельзя — всегда образуется SO2."}, {"id": "rx107_s_koh_hot", "sk": "sulfur_compounds", "ref": "06.7", "n": 8, "lvl": 3, "l": ["S", "KOH"], "r": ["K2S", "K2SO3", "H2O"], "c": [3, 6, 2, 1, 3], "if": "горячий конц. раствор щёлочи, t° (диспропорционирование)", "bad": [["K2SO4", "При диспропорционировании серы в щёлочи образуются сульфид K2S (−2) и сульфит K2SO3 (+4)."], ["KHSO3", "В избытке щёлочи образуются средние соли K2S и K2SO3."]], "why": "Классическое диспропорционирование серы в горячей щёлочи: S^{0} → S^{−2} и S^{+4}."}, {"id": "rx108_s_hno3_conc", "sk": "sulfur_compounds", "ref": "06.7", "n": 8, "lvl": 2, "l": ["S", "HNO3"], "r": ["H2SO4", "NO2", "H2O"], "c": [1, 6, 1, 6, 2], "if": "конц. HNO3, t°", "bad": [["SO2", "Концентрированная азотная кислота окисляет серу до высшей степени +6 (H2SO4)."], ["NO", "Конц. HNO3 с неметаллами всегда даёт бурый газ NO2↑."]], "why": "Неметаллы (S, P, C) окисляются конц. HNO3 до высшей кислоты/оксида с выделением NO2↑."}, {"id": "rx109_s_h2so4_conc", "sk": "sulfur_compounds", "ref": "06.7", "n": 8, "lvl": 2, "l": ["S", "H2SO4"], "r": ["SO2", "H2O"], "c": [1, 2, 3, 2], "if": "конц. H2SO4, t° (сопропорционирование)", "bad": [["H2S", "S^{0} и S^{+6} сходятся в промежуточной СО +4 → образуется 3SO2↑."], ["SO3", "Конц. H2SO4 восстанавливается до SO2↑."]], "why": "Сопропорционирование серы: S^{0} − 4e⁻ → S^{+4} и 2S^{+6} + 4e⁻ → 2S^{+4}."}, {"id": "rx110_h2s_o2_def", "sk": "sulfur_compounds", "ref": "06.11", "n": 8, "lvl": 2, "l": ["H2S", "O2"], "r": ["S", "H2O"], "c": [2, 1, 2, 2], "if": "недостаток кислорода O2, t°", "bad": [["SO2", "SO2 образуется в ИЗБЫТКЕ O2; в недостатке O2 — жёлтая сера S↓."], ["SO3", "SO3 при горении H2S не образуется."]], "why": "Неполное сгорание сероводорода даёт свободную серу S↓ и воду."}, {"id": "rx111_h2s_o2_exc", "sk": "sulfur_compounds", "ref": "06.11", "n": 8, "lvl": 2, "l": ["H2S", "O2"], "r": ["SO2", "H2O"], "c": [2, 3, 2, 2], "if": "избыток кислорода O2, t°", "bad": [["S", "В избытке O2 сера доокисляется до SO2↑."], ["SO3", "Даже в избытке O2 продуктом горения является SO2↑."]], "why": "Полное сгорание сероводорода даёт сернистый газ SO2↑ и воду."}, {"id": "rx112_h2s_so2", "sk": "sulfur_compounds", "ref": "06.11", "n": 8, "lvl": 2, "l": ["H2S", "SO2"], "r": ["S", "H2O"], "c": [2, 1, 3, 2], "if": "н.у. (сопропорционирование, жёлтый осадок S↓)", "bad": [["H2SO4", "Два газа с разными СО серы (−2 и +4) дают жёлтый осадок серы 3S↓."], ["SO3", "Идёт сопропорционирование до простого вещества S↓."]], "why": "Классическая реакция двух газов с выпадением жёлтого осадка S↓."}, {"id": "rx113_h2s_hno3_conc", "sk": "sulfur_compounds", "ref": "06.11", "n": 8, "lvl": 3, "l": ["H2S", "HNO3"], "r": ["H2SO4", "NO2", "H2O"], "c": [1, 8, 1, 8, 4], "if": "конц. HNO3 (избыток)", "bad": [["S", "Избыток конц. HNO3 окисляет H2S максимально глубоко — до H2SO4."], ["NO", "Конц. HNO3 восстанавливается до 8NO2↑."]], "why": "Сильный окислитель HNO3(конц.) переводит S^{−2} в S^{+6} (8e⁻ → 8NO2↑)."}, {"id": "rx114_fes2_o2", "sk": "sulfur_compounds", "ref": "06.15", "n": 8, "lvl": 3, "l": ["FeS2", "O2"], "r": ["Fe2O3", "SO2"], "c": [4, 11, 2, 8], "if": "t° (обжиг пирита — 1-я стадия производства H2SO4)", "bad": [["FeO", "В избытке O2 железо окисляется до Fe2O3 (+3)."], ["SO3", "При обжиге пирита без катализатора образуется SO2↑."]], "why": "Двойное окисление FeS2 (11e⁻ на 1 формулу) → коэффициенты 4, 11, 2, 8."}, {"id": "rx115_so2_br2_h2o", "sk": "sulfur_compounds", "ref": "06.18", "n": 8, "lvl": 2, "l": ["SO2", "Br2", "H2O"], "r": ["H2SO4", "HBr"], "c": [1, 1, 2, 1, 2], "if": "водный раствор (обесцвечивание бромной воды)", "bad": [["H2SO3", "Бром окисляет S^{+4} до серной кислоты H2SO4."], ["SO3", "В водной среде образуется раствор двух сильных кислот — H2SO4 и 2HBr."]], "why": "Качественная реакция на SO2: обесцвечивание бромной воды."}, {"id": "rx116_so2_cl2_h2o", "sk": "sulfur_compounds", "ref": "06.18", "n": 8, "lvl": 2, "l": ["SO2", "Cl2", "H2O"], "r": ["H2SO4", "HCl"], "c": [1, 1, 2, 1, 2], "if": "водный раствор (хлорная вода)", "bad": [["HClO", "Хлор окисляет SO2 до H2SO4, сам восстанавливаясь до HCl."], ["S", "SO2 здесь восстановитель (S^{+4} → S^{+6})."]], "why": "Хлор в воде окисляет сернистый газ до смеси H2SO4 и 2HCl."}, {"id": "rx117_so2_kmno4_h2o", "sk": "sulfur_compounds", "ref": "06.18", "n": 8, "lvl": 3, "l": ["SO2", "KMnO4", "H2O"], "r": ["K2SO4", "MnSO4", "H2SO4"], "c": [5, 2, 2, 1, 2, 2], "if": "водный раствор (среда сразу становится кислой!)", "bad": [["MnO2", "При окислении SO2 выделяется H2SO4, поэтому среда кислая → образуется MnSO4!"], ["K2MnO4", "В кислой среде перманганат обесцвечивается до Mn^{2+}."]], "why": "Ловушка: хотя в левой части H2O, окисление SO2 создаёт кислую среду → MnSO4, а не MnO2!"}, {"id": "rx118_na2so3_h2o2", "sk": "sulfur_compounds", "ref": "06.18", "n": 8, "lvl": 2, "l": ["Na2SO3", "H2O2"], "r": ["Na2SO4", "H2O"], "c": [1, 1, 1, 1], "if": "водный раствор (без видимых признаков!)", "bad": [["O2", "H2O2 здесь окислитель (O^{−1} → H2O), газ O2 не выделяется."], ["SO2", "Сульфит окисляется до сульфата Na2SO4."]], "why": "Реакция без видимых признаков: оба реагента и оба продукта бесцветны и растворимы."}, {"id": "rx119_nh4cl_t", "sk": "nitrogen_nitrates", "ref": "07.7", "n": 8, "lvl": 1, "l": ["NH4Cl"], "r": ["NH3", "HCl"], "c": [1, 1, 1], "if": "t° (обратимое разложение хлорида аммония)", "bad": [["N2", "Хлорид-ион не окислитель — разложение идёт без изменения СО до NH3↑ и HCl↑."], ["Cl2", "Степени окисления не меняются."]], "why": "Соли аммония с неокисляющими кислотами разлагаются на аммиак и кислоту."}, {"id": "rx120_nh4hco3_t", "sk": "nitrogen_nitrates", "ref": "07.7", "n": 8, "lvl": 2, "l": ["NH4HCO3"], "r": ["NH3", "CO2", "H2O"], "c": [1, 1, 1, 1], "if": "t° (разложение без твёрдого остатка)", "bad": [["(NH4)2CO3", "При нагревании гидрокарбонат аммония полностью улетает в виде NH3↑, CO2↑ и H2O."], ["N2", "Реакция не является ОВР."]], "why": "При нагревании NH4HCO3 полностью разлагается на газообразные продукты (разрыхлитель)."}, {"id": "rx121_nh4no2_t", "sk": "nitrogen_nitrates", "ref": "07.7", "n": 8, "lvl": 2, "l": ["NH4NO2"], "r": ["N2", "H2O"], "c": [1, 1, 2], "if": "t° (лабораторное получение азота N2↑)", "bad": [["N2O", "N2O получается из NH4NO3; из нитрита NH4NO2 получается чистый азот N2↑."], ["NH3", "Идёт внутримолекулярная ОВР: N^{−3} + N^{+3} → N2^{0}."]], "why": "Запомни пару: NH4NO2 → N2↑ + 2H2O; NH4NO3 → N2O↑ + 2H2O."}, {"id": "rx122_nh4no3_t", "sk": "nitrogen_nitrates", "ref": "07.7", "n": 8, "lvl": 2, "l": ["NH4NO3"], "r": ["N2O", "H2O"], "c": [1, 1, 2], "if": "t° (~200 °C, получение веселящего газа)", "bad": [["N2", "Азот N2 даёт NH4NO2; нитрат аммония при умеренном нагревании даёт N2O↑."], ["NO2", "Образуется оксид азота(I) N2O↑ (веселящий газ)."]], "why": "Внутримолекулярная ОВР: N^{−3} и N^{+5} сходятся в N^{+1} (N2O↑)."}, {"id": "rx123_no2_h2o_cold", "sk": "nitrogen_nitrates", "ref": "07.11", "n": 8, "lvl": 2, "l": ["NO2", "H2O"], "r": ["HNO2", "HNO3"], "c": [2, 1, 1, 1], "if": "холодная вода (диспропорционирование)", "bad": [["NO", "NO образуется в ГОРЯЧЕЙ воде (из-за разложения HNO2); в холодной — HNO2 + HNO3."], ["NH3", "N^{+4} диспропорционирует в соседние СО +3 и +5."]], "why": "NO2 — смешанный ангидрид: в холодной воде даёт азотистую и азотную кислоты."}, {"id": "rx124_no2_h2o_hot", "sk": "nitrogen_nitrates", "ref": "07.11", "n": 8, "lvl": 2, "l": ["NO2", "H2O"], "r": ["HNO3", "NO"], "c": [3, 1, 2, 1], "if": "горячая вода (HNO2 разлагается!)", "bad": [["HNO2", "В горячей воде азотистая кислота неустойчива — образуются 2HNO3 и NO↑."], ["N2O", "Выделяется оксид азота(II) NO↑."]], "why": "В горячей воде NO2 диспропорционирует на +5 (HNO3) и +2 (NO↑)."}, {"id": "rx125_no2_koh", "sk": "nitrogen_nitrates", "ref": "07.11", "n": 8, "lvl": 2, "l": ["NO2", "KOH"], "r": ["KNO2", "KNO3", "H2O"], "c": [2, 2, 1, 1, 1], "if": "водный раствор щёлочи (без O2)", "bad": [["KNO3", "Без кислорода O2 образуется смесь двух солей — нитрита KNO2 и нитрата KNO3."], ["NO", "В щёлочи нитрит KNO2 устойчив, газ NO не выделяется."]], "why": "NO2 в щёлочи без кислорода даёт две соли: KNO2 и KNO3."}, {"id": "rx126_no2_o2_h2o", "sk": "nitrogen_nitrates", "ref": "07.11", "n": 8, "lvl": 2, "l": ["NO2", "O2", "H2O"], "r": ["HNO3"], "c": [4, 1, 2, 4], "if": "в присутствии O2 (промышленное получение HNO3)", "bad": [["HNO2", "Кислород доокисляет весь азот до +5 — образуется только HNO3."], ["NO", "В избытке O2 образуется чистая азотная кислота 4HNO3."]], "why": "Заключительная стадия производства HNO3: 4NO2 + O2 + 2H2O → 4HNO3."}, {"id": "rx127_no2_o2_koh", "sk": "nitrogen_nitrates", "ref": "07.11", "n": 8, "lvl": 2, "l": ["NO2", "O2", "KOH"], "r": ["KNO3", "H2O"], "c": [4, 1, 4, 4, 2], "if": "в присутствии O2 (щёлочь)", "bad": [["KNO2", "При участии O2 весь NO2 окисляется до одной соли — нитрата KNO3."], ["K2O", "В водном растворе образуются нитрат калия и вода."]], "why": "Сравни: NO2 + KOH → KNO2 + KNO3; NO2 + O2 + KOH → только KNO3."}, {"id": "rx128_kno3_t", "sk": "nitrogen_nitrates", "ref": "07.18", "n": 8, "lvl": 1, "l": ["KNO3"], "r": ["KNO2", "O2"], "c": [2, 2, 1], "if": "t° (нитрат активного металла левее Mg, кроме Li)", "bad": [["K2O", "Нитраты Na, K, Ca, Ba разлагаются до нитрита и O2↑ (не до оксида!)."], ["NO2", "Бурый газ NO2 не выделяется."]], "why": "Зона 1 (левее Mg, кроме Li): нитрат → нитрит + O2↑."}, {"id": "rx129_lino3_t", "sk": "nitrogen_nitrates", "ref": "07.18", "n": 8, "lvl": 3, "l": ["LiNO3"], "r": ["Li2O", "NO2", "O2"], "c": [4, 2, 4, 1], "if": "t° (исключение! LiNO3 как средняя группа)", "bad": [["LiNO2", "Нитрат лития — исключение: разлагается до оксида Li2O, NO2↑ и O2↑."], ["Li", "До металла разлагаются только нитраты металлов правее Cu."]], "why": "Обязательное исключение ЕГЭ: LiNO3 даёт Li2O + NO2↑ + O2↑."}, {"id": "rx130_feno32_t", "sk": "nitrogen_nitrates", "ref": "07.18", "n": 8, "lvl": 3, "l": ["Fe(NO3)2"], "r": ["Fe2O3", "NO2", "O2"], "c": [4, 2, 8, 1], "if": "t° (исключение! окисление Fe(+2) до Fe(+3))", "bad": [["FeO", "Кислород при прокаливании окисляет железо(+2) до бурого Fe2O3(+3)."], ["Fe(NO2)2", "Железо стоит в средней зоне (Mg–Cu) и дополнительно окисляется до Fe2O3."]], "why": "Обязательное исключение: 4Fe(NO3)2 —t°→ 2Fe2O3 + 8NO2↑ + O2↑."}, {"id": "rx131_agno3_t", "sk": "nitrogen_nitrates", "ref": "07.18", "n": 8, "lvl": 2, "l": ["AgNO3"], "r": ["Ag", "NO2", "O2"], "c": [2, 2, 2, 1], "if": "t° (нитрат металла правее Cu)", "bad": [["Ag2O", "Оксид серебра при прокаливании сам разлагается → образуется свободный металл Ag."], ["AgNO2", "Нитраты правее Cu разлагаются до металла, NO2↑ и O2↑."]], "why": "Зона 3 (правее Cu: Ag, Hg): нитрат → металл + NO2↑ + O2↑."}, {"id": "rx132_p_o2_def", "sk": "p_c_si_compounds", "ref": "08.4", "n": 8, "lvl": 2, "l": ["P", "O2"], "r": ["P2O3"], "c": [4, 3, 2], "if": "недостаток кислорода O2, t°", "bad": [["P2O5", "В недостатке O2 образуется оксид фосфора(III) P2O3 (P4O6)."], ["PO2", "Фосфор образует оксиды P2O3 и P2O5."]], "why": "Недостаток O2 переводит фосфор в +3 (P2O3), избыток — в +5 (P2O5)."}, {"id": "rx133_p_o2_exc", "sk": "p_c_si_compounds", "ref": "08.4", "n": 8, "lvl": 1, "l": ["P", "O2"], "r": ["P2O5"], "c": [4, 5, 2], "if": "избыток кислорода O2, t°", "bad": [["P2O3", "В избытке O2 фосфор сгорает до белого дыма P2O5."], ["H3PO4", "В реакции нет водорода."]], "why": "Горение фосфора в избытке O2 даёт P2O5 (P4O10)."}, {"id": "rx134_ca_p", "sk": "p_c_si_compounds", "ref": "08.6", "n": 8, "lvl": 2, "l": ["Ca", "P"], "r": ["Ca3P2"], "c": [3, 2, 1], "if": "t° (синтез фосфида кальция)", "bad": [["CaP", "Ca(+2) и P(−3) дают формулу Ca3P2."], ["Ca3(PO4)2", "Без кислорода образуется бинарный фосфид Ca3P2."]], "why": "Синтез фосфида кальция — первый шаг к получению фосфина PH3."}, {"id": "rx135_ca3p2_h2o", "sk": "p_c_si_compounds", "ref": "08.6", "n": 8, "lvl": 2, "l": ["Ca3P2", "H2O"], "r": ["Ca(OH)2", "PH3"], "c": [1, 6, 3, 2], "if": "н.у. (гидролиз фосфида до фосфина PH3↑)", "bad": [["H3PO4", "Степень окисления фосфора (−3) не меняется → выделяется ядовитый газ PH3↑."], ["P", "Идёт необратимый гидролиз без изменения СО."]], "why": "Фосфор не реагирует с H2 напрямую, поэтому PH3 получают гидролизом фосфидов."}, {"id": "rx136_p_naoh_h2o", "sk": "p_c_si_compounds", "ref": "08.6", "n": 8, "lvl": 3, "l": ["P", "NaOH", "H2O"], "r": ["PH3", "NaH2PO2"], "c": [4, 3, 3, 1, 3], "if": "белый фосфор, конц. NaOH, t° (диспропорционирование)", "bad": [["Na3PO4", "Белый фосфор в щёлочи диспропорционирует до PH3 (−3) и гипофосфита NaH2PO2 (+1)."], ["H2", "Выделяется фосфин PH3↑, а не водород (в отличие от Si + NaOH!)."]], "why": "Хит № 8 и № 31: 4P + 3NaOH + 3H2O → PH3↑ + 3NaH2PO2 (NaH2PO2 — средняя соль!)."}, {"id": "rx137_pcl3_h2o", "sk": "p_c_si_compounds", "ref": "08.9", "n": 8, "lvl": 2, "l": ["PCl3", "H2O"], "r": ["H3PO3", "HCl"], "c": [1, 3, 1, 3], "if": "необратимый гидролиз хлорида фосфора(III)", "bad": [["H3PO4", "Степень окисления фосфора (+3) сохраняется → фосфористая кислота H3PO3."], ["PH3", "Реакция не является ОВР."]], "why": "Галогениды неметаллов нацело гидролизуются водой до двух кислот без смены СО."}, {"id": "rx138_pcl5_h2o", "sk": "p_c_si_compounds", "ref": "08.9", "n": 8, "lvl": 2, "l": ["PCl5", "H2O"], "r": ["H3PO4", "HCl"], "c": [1, 4, 1, 5], "if": "необратимый гидролиз хлорида фосфора(V)", "bad": [["H3PO3", "Фосфор в СО +5 переходит в ортофосфорную кислоту H3PO4."], ["Cl2", "Гидролиз — не ОВР, образуется 5HCl."]], "why": "Полный гидролиз PCl5 даёт ортофосфорную и соляную кислоты."}, {"id": "rx139_p2o5_h2o_cold", "sk": "p_c_si_compounds", "ref": "08.9", "n": 8, "lvl": 3, "l": ["P2O5", "H2O"], "r": ["HPO3"], "c": [1, 1, 2], "if": "холодная вода (метафосфорная кислота)", "bad": [["H3PO4", "H3PO4 образуется при кипячении с горячей водой; с холодной — HPO3."], ["H3PO3", "Степень окисления фосфора +5 сохраняется."]], "why": "P2O5 с холодной водой (1 : 1) даёт метафосфорную кислоту 2HPO3."}, {"id": "rx140_p2o5_h2o_hot", "sk": "p_c_si_compounds", "ref": "08.9", "n": 8, "lvl": 1, "l": ["P2O5", "H2O"], "r": ["H3PO4"], "c": [1, 3, 2], "if": "горячая вода / кипячение (ортофосфорная кислота)", "bad": [["HPO3", "При нагревании с избытком воды образуется ортофосфорная кислота 2H3PO4."], ["H3PO3", "Фосфор сохраняет СО +5."]], "why": "Классическая реакция кислотного оксида P2O5 с горячей водой → 2H3PO4."}, {"id": "rx141_ca3po42_sio2_c", "sk": "p_c_si_compounds", "ref": "08.9", "n": 8, "lvl": 3, "l": ["Ca3(PO4)2", "SiO2", "C"], "r": ["CaSiO3", "P", "CO"], "c": [1, 3, 5, 3, 2, 5], "if": "электропечь, ~1500 °C (промышленное получение фосфора)", "bad": [["CO2", "При 1500 °C в избытке кокса образуется угарный газ 5CO↑, а не CO2."], ["CaO", "Кремнезём SiO2 связывает кальций в шлак CaSiO3."]], "why": "Главный промышленный способ получения белого фосфора из фосфоритов."}, {"id": "rx142_ca3po42_h3po4", "sk": "p_c_si_compounds", "ref": "08.12", "n": 8, "lvl": 2, "l": ["Ca3(PO4)2", "H3PO4"], "r": ["Ca(H2PO4)2"], "c": [1, 4, 3], "if": "получение двойного суперфосфата", "bad": [["CaHPO4", "При избытке H3PO4 (1 : 4) образуется растворимый дигидрофосфат Ca(H2PO4)2."], ["P2O5", "Средняя соль + своя кислота → кислая соль."]], "why": "Перевод нерастворимого фосфорита в растворимое удобрение Ca(H2PO4)2."}, {"id": "rx143_cah2po42_caoh2_def", "sk": "p_c_si_compounds", "ref": "08.12", "n": 8, "lvl": 3, "l": ["Ca(H2PO4)2", "Ca(OH)2"], "r": ["CaHPO4", "H2O"], "c": [1, 1, 2, 2], "if": "недостаток Ca(OH)2 (1 : 1 → гидрофосфат)", "bad": [["Ca3(PO4)2", "Средний фосфат образуется при избытке 2Ca(OH)2; при 1 : 1 — 2CaHPO4↓."], ["H3PO4", "Щёлочь ступенчато нейтрализует кислую соль."]], "why": "Ступенчатая нейтрализация: 1 моль Ca(OH)2 снимает по одному H^{+} с каждого H2PO4⁻."}, {"id": "rx144_cah2po42_caoh2_exc", "sk": "p_c_si_compounds", "ref": "08.12", "n": 8, "lvl": 2, "l": ["Ca(H2PO4)2", "Ca(OH)2"], "r": ["Ca3(PO4)2", "H2O"], "c": [1, 2, 1, 4], "if": "избыток Ca(OH)2 (1 : 2 → средний фосфат)", "bad": [["CaHPO4", "Избыток щёлочи (2 моль Ca(OH)2) полностью нейтрализует дигидрофосфат до Ca3(PO4)2↓."], ["CaO", "Образуется нерастворимый средний фосфат и 4H2O."]], "why": "Полная нейтрализация кислой соли избытком одноимённого основания."}, {"id": "rx145_c_o2_def", "sk": "p_c_si_compounds", "ref": "08.15", "n": 8, "lvl": 1, "l": ["C", "O2"], "r": ["CO"], "c": [2, 1, 2], "if": "недостаток кислорода O2, t°", "bad": [["CO2", "В недостатке O2 образуется угарный газ CO."], ["C2O", "Оксиды углерода — CO и CO2."]], "why": "Неполное сгорание углерода даёт несолеобразующий угарный газ CO."}, {"id": "rx146_c_o2_exc", "sk": "p_c_si_compounds", "ref": "08.15", "n": 8, "lvl": 1, "l": ["C", "O2"], "r": ["CO2"], "c": [1, 1, 1], "if": "избыток кислорода O2, t°", "bad": [["CO", "В избытке O2 углерод сгорает полностью до CO2."], ["H2CO3", "В реакции нет водорода."]], "why": "Полное сгорание углерода даёт кислотный оксид CO2."}, {"id": "rx147_c_co2", "sk": "p_c_si_compounds", "ref": "08.15", "n": 8, "lvl": 2, "l": ["C", "CO2"], "r": ["CO"], "c": [1, 1, 2], "if": "t° (раскалённый кокс, сопропорционирование)", "bad": [["C2O", "C^{0} и C^{+4} сходятся в C^{+2} → образуется 2CO."], ["O2", "Кислород не выделяется."]], "why": "Важная реакция в доменной печи и в заданиях № 7/9: CO2 + C —t°→ 2CO."}, {"id": "rx148_c_h2o_steam", "sk": "p_c_si_compounds", "ref": "08.15", "n": 8, "lvl": 2, "l": ["C", "H2O"], "r": ["CO", "H2"], "c": [1, 1, 1, 1], "if": "водяной пар, t° (получение синтез-газа)", "bad": [["CO2", "При высокой температуре с раскалённым углём образуется смесь CO + H2 (синтез-газ)."], ["CH4", "Водяной пар окисляет углерод до CO и восстанавливается до H2↑."]], "why": "Промышленный способ получения синтез-газа (CO + H2)."}, {"id": "rx149_cao_c", "sk": "p_c_si_compounds", "ref": "08.15", "n": 8, "lvl": 2, "l": ["CaO", "C"], "r": ["CaC2", "CO"], "c": [1, 3, 1, 1], "if": "электропечь, ~2000 °C (промышленное получение карбида кальция)", "bad": [["Ca", "Углерод не восстанавливает CaO до свободного кальция — образуется карбид CaC2 + CO↑."], ["CO2", "При 2000 °C образуется угарный газ CO↑."]], "why": "Промышленный синтез карбида кальция из негашёной извести и кокса."}, {"id": "rx150_sio2_c", "sk": "p_c_si_compounds", "ref": "08.15", "n": 8, "lvl": 2, "l": ["SiO2", "C"], "r": ["Si", "CO"], "c": [1, 2, 1, 2], "if": "электропечь, t° (промышленное получение кремния)", "bad": [["CO2", "При высокой температуре в избытке кокса выделяется CO↑ (а не CO2)."], ["SiC", "При стехиометрии 1 : 2 образуется технический кремний Si и 2CO↑."]], "why": "Промышленный способ получения кремния из кварцевого песка SiO2."}, {"id": "rx151_si_naoh_h2o", "sk": "p_c_si_compounds", "ref": "08.22", "n": 8, "lvl": 3, "l": ["Si", "NaOH", "H2O"], "r": ["Na2SiO3", "H2"], "c": [1, 2, 1, 1, 2], "if": "горячий водный раствор щёлочи, t°", "bad": [["SiH4", "В отличие от белого фосфора (PH3), кремний в щёлочи выделяет водород 2H2↑!"], ["Na4SiO4", "В ЕГЭ продуктом растворения Si в щёлочи является силикат Na2SiO3."]], "why": "Хит № 7, 8 и № 31: кремний растворяется в водном NaOH с выделением 2H2↑."}, {"id": "rx152_si_f2", "sk": "p_c_si_compounds", "ref": "08.22", "n": 8, "lvl": 1, "l": ["Si", "F2"], "r": ["SiF4"], "c": [1, 2, 1], "if": "н.у. (фтор окисляет кремний без нагревания)", "bad": [["SiF2", "У кремния с галогенами устойчива степень окисления +4 → SiF4↑."], ["HF", "В реакции нет водорода."]], "why": "Фтор — единственный галоген, реагирующий с кремнием при н.у."}, {"id": "rx153_si_cl2", "sk": "p_c_si_compounds", "ref": "08.22", "n": 8, "lvl": 1, "l": ["Si", "Cl2"], "r": ["SiCl4"], "c": [1, 2, 1], "if": "t° (нагревание)", "bad": [["SiCl2", "Кремний с хлором образует тетрахлорид SiCl4."], ["HCl", "В реакции нет водорода."]], "why": "При нагревании кремний сгорает в хлоре с образованием жидкости SiCl4."}, {"id": "rx154_sicl4_h2o", "sk": "p_c_si_compounds", "ref": "08.22", "n": 8, "lvl": 2, "l": ["SiCl4", "H2O"], "r": ["H2SiO3", "HCl"], "c": [1, 3, 1, 4], "if": "необратимый гидролиз тетрахлорида кремния", "bad": [["SiO2", "В воде SiCl4 гидролизуется до студенистого осадка H2SiO3↓ и 4HCl."], ["Cl2", "Реакция не является ОВР."]], "why": "Полный гидролиз галогенида неметалла без изменения степеней окисления."}, {"id": "rx155_si_o2", "sk": "p_c_si_compounds", "ref": "08.22", "n": 8, "lvl": 1, "l": ["Si", "O2"], "r": ["SiO2"], "c": [1, 1, 1], "if": "t° (нагревание)", "bad": [["SiO", "В кислороде кремний окисляется до диоксида SiO2."], ["H2SiO3", "В реакции нет водорода."]], "why": "Окисление кремния кислородом при нагревании даёт тугоплавкий SiO2."}, {"id": "rx156_si_mg", "sk": "p_c_si_compounds", "ref": "08.22", "n": 8, "lvl": 2, "l": ["Si", "Mg"], "r": ["Mg2Si"], "c": [1, 2, 1], "if": "t° (получение силицида магния)", "bad": [["MgSi", "Mg(+2) и Si(−4) дают формулу Mg2Si."], ["MgSiO3", "Без кислорода образуется бинарный силицид Mg2Si."]], "why": "Синтез силицида магния — первый шаг для получения силана SiH4."}, {"id": "rx157_mg2si_hcl", "sk": "p_c_si_compounds", "ref": "08.22", "n": 8, "lvl": 3, "l": ["Mg2Si", "HCl"], "r": ["MgCl2", "SiH4"], "c": [1, 4, 2, 1], "if": "разбавленная HCl (получение силана SiH4↑)", "bad": [["SiCl4", "Степень окисления кремния (−4) сохраняется → выделяется самовоспламеняющийся газ SiH4↑."], ["H2", "Кислота вытесняет летучий силан SiH4↑ (не ОВР)."]], "why": "Кремний с H2 не реагирует, поэтому силан SiH4↑ получают из Mg2Si и HCl."}, {"id": "rx158_sio2_na2co3", "sk": "p_c_si_compounds", "ref": "08.25", "n": 8, "lvl": 2, "l": ["SiO2", "Na2CO3"], "r": ["Na2SiO3", "CO2"], "c": [1, 1, 1, 1], "if": "сплавление (варка стекла / растворимого стекла)", "bad": [["H2SiO3", "При сплавлении без воды образуются Na2SiO3 и улетает CO2↑."], ["CO", "Реакция не является ОВР — выделяется CO2↑."]], "why": "Нелетучий SiO2 при сплавлении вытесняет летучий CO2↑ из карбонатов."}, {"id": "rx159_sio2_caco3", "sk": "p_c_si_compounds", "ref": "08.25", "n": 8, "lvl": 2, "l": ["SiO2", "CaCO3"], "r": ["CaSiO3", "CO2"], "c": [1, 1, 1, 1], "if": "сплавление (производство стекла и цемента)", "bad": [["CaO", "Оксид кальция сразу связывается с SiO2 в силикат кальция CaSiO3."], ["CO", "Степени окисления не меняются — выделяется CO2↑."]], "why": "Сплавление SiO2 с CaCO3 — базовая реакция силикатной промышленности."}, {"id": "rx160_sio2_naoh", "sk": "p_c_si_compounds", "ref": "08.25", "n": 8, "lvl": 1, "l": ["SiO2", "NaOH"], "r": ["Na2SiO3", "H2O"], "c": [1, 2, 1, 1], "if": "сплавление / конц. раствор при нагревании t°", "bad": [["H2", "В отличие от простого вещества Si, оксид SiO2 даёт со щёлочью соль и воду (не H2!)."], ["NaHSiO3", "Образуется средний силикат Na2SiO3 и вода."]], "why": "Кислотный оксид SiO2 реагирует со щелочами при нагревании (поэтому щёлочь не хранят в стекле с притёртой пробкой)."}, {"id": "rx161_sio2_cao", "sk": "p_c_si_compounds", "ref": "08.25", "n": 8, "lvl": 1, "l": ["SiO2", "CaO"], "r": ["CaSiO3"], "c": [1, 1, 1], "if": "сплавление t°", "bad": [["Ca2SiO4", "В школьном курсе ЕГЭ кислотный SiO2 + основный CaO → метасиликат CaSiO3."], ["Ca(OH)2", "В реакции нет водорода."]], "why": "Классическая реакция соединения кислотного и основного оксидов при прокаливании."}, {"id": "rx162_sio2_mg", "sk": "p_c_si_compounds", "ref": "08.25", "n": 8, "lvl": 2, "l": ["SiO2", "Mg"], "r": ["Si", "MgO"], "c": [1, 2, 1, 2], "if": "t° (магнийтермия — лабораторное получение кремния)", "bad": [["Mg2Si", "При соотношении 1 : 2 образуется чистый кремний Si и 2MgO (избыток Mg даст Mg2Si)."], ["MgSiO3", "Магний восстанавливает Si(+4) до простого вещества Si."]], "why": "Лабораторный способ получения кремния восстановлением песка магнием."}], "seq": [], "facts": [{"id": "f_metals_1_4", "sk": "active_metals", "ref": "02.15", "n": 7, "lvl": 3, "t": "Ловушки активных и амфотерных металлов", "s": [["Натрий при внесении в водный раствор CuSO4 реагирует с водой, а затем NaOH осаждает Cu(OH)2↓.", "Натрий вытесняет металлическую медь из водного раствора CuSO4.", "Щелочные и щёлочноземельные металлы сначала бурно реагируют с водой, а не вытесняют металл соли."], ["Al(OH)3 не растворяется в избытке водного аммиака NH3·H2O, а Zn(OH)2 растворяется.", "Al(OH)3 и Zn(OH)2 одинаково хорошо растворяются в избытке водного аммиака.", "Zn(OH)2 образует комплекс [Zn(NH3)4](OH)2, а Al(OH)3 аммиачных комплексов не даёт."], ["Карбонаты щелочных металлов Na2CO3 и K2CO3 при прокаливании не разлагаются.", "Na2CO3 и K2CO3 при нагревании легко разлагаются до оксида и CO2↑.", "Из карбонатов щелочных металлов при прокаливании разлагается только Li2CO3."], ["Пропускание избытка CO2 через раствор Na[Al(OH)4] приводит к выпадению осадка Al(OH)3↓ и образованию NaHCO3.", "В избытке CO2 осадок Al(OH)3 растворяется с образованием карбоната алюминия.", "Угольная кислота слишком слаба для растворения Al(OH)3, а Al2(CO3)3 в воде не существует."], ["Литий — единственный металл в школьном курсе ЕГЭ, реагирующий с азотом N2 при комнатной температуре.", "Магний и кальций реагируют с азотом N2 без нагревания, а литий — только при прокаливании.", "6Li + N2 → 2Li3N идёт при н.у., тогда как Mg и Ca требуют нагревания."]]}, {"id": "f_transition_fe_cr", "sk": "transition_fe_cr_cu", "ref": "04.14", "n": 8, "lvl": 3, "t": "Ловушки Fe, Cr, Cu и пассивации", "s": [["Холодные концентрированные HNO3 и H2SO4 пассивируют железо, алюминий и хром.", "Железо бурно растворяется в холодной концентрированной HNO3 с выделением NO2↑.", "На холоде образуется плотная оксидная плёнка; реакция идёт только при нагревании."], ["Взаимодействие FeCl3 с KI и с Na2S в растворе — это ОВР, а не совместный гидролиз.", "При сливании FeCl3 и Na2S идёт совместный гидролиз с выпадением Fe(OH)3↓ и выделением H2S↑.", "Ион Fe^{3+} окисляет I⁻ до I2 и S^{2−} до S↓, сам восстанавливаясь до Fe^{+2}."], ["В рамках ЕГЭ Fe(OH)3 не растворяется в водных растворах щелочей, но сплавляется с твёрдым NaOH до NaFeO2.", "Свежеосаждённый Fe(OH)3 легко растворяется в водном растворе NaOH с образованием Na[Fe(OH)4].", "Амфотерность Fe(OH)3 проявляется в ЕГЭ только при сплавлении с твёрдой щёлочью или карбонатом."], ["Переход оранжевого K2Cr2O7 в жёлтый K2CrO4 в щёлочи не сопровождается изменением степени окисления хрома.", "Переход дихромата в хромат в щёлочи — это реакция восстановления хрома.", "В обоих ионах хром имеет степень окисления +6."], ["Гидроксид серебра AgOH неустойчив и мгновенно распадается на бурый осадок Ag2O↓ и воду.", "При добавлении NaOH к раствору AgNO3 выпадает белый осадок AgOH↓.", "В таблице растворимости ФИПИ напротив AgOH стоит прочерк: 2AgNO3 + 2NaOH → Ag2O↓ + 2NaNO3 + H2O."]]}, {"id": "f_halogens_sulfur", "sk": "sulfur_compounds", "ref": "06.8", "n": 7, "lvl": 3, "t": "Ловушки галогенов, серы и сульфидов", "s": [["При сжигании серы в кислороде образуется только SO2; получить SO3 в одну стадию нельзя.", "При сжигании серы в избытке кислорода образуется оксид серы(VI) SO3.", "Окисление SO2 до SO3 требует катализатора V2O5 и нагревания (~450 °C)."], ["Сульфиды CuS, Ag2S, HgS и PbS не растворяются в соляной и разбавленной серной кислотах.", "Все нерастворимые сульфиды металлов легко растворяются в соляной кислоте с выделением H2S↑.", "Эти четыре сульфида имеют крайне низкую растворимость и растворяются только в кислотах-окислителях (HNO3)."], ["Фтор F2 не вытесняет хлор из водного раствора NaCl, потому что мгновенно окисляет воду до O2↑.", "Фтор как самый активный галоген легко вытесняет хлор из водного раствора NaCl.", "Реакция 2F2 + 2H2O → 4HF + O2↑ протекает со взрывом."], ["С твёрдым NaCl концентрированная H2SO4 даёт реакцию обмена (HCl↑), а с KBr и KI — ОВР.", "Концентрированная H2SO4 окисляет все галогениды (NaCl, KBr, KI) до свободных галогенов.", "Cl⁻ не окисляется H2SO4(конц.), в отличие от Br⁻ (Br2 + SO2↑) и I⁻ (I2 + H2S↑)."], ["Разбавленная H2SO4 не реагирует с медью, а горячая концентрированная окисляет медь до CuSO4 и SO2↑.", "Медь растворяется в разбавленной серной кислоте с выделением водорода H2↑.", "Медь стоит правее водорода в ряду напряжений, поэтому H^{+} её не окисляет."]]}, {"id": "f_nitrogen_pcsi", "sk": "p_c_si_compounds", "ref": "08.23", "n": 7, "lvl": 3, "t": "Ловушки азота, фосфора, углерода и кремния", "s": [["Азотная кислота любой концентрации не выделяет водород H2↑ в реакциях с металлами.", "Очень разбавленная HNO3 реагирует с магнием с выделением водорода H2↑.", "Даже при сильном разбавлении окислителем остаётся N^{+5} (восстанавливается до NH4NO3)."], ["Нитрат лития LiNO3 разлагается до Li2O + NO2↑ + O2↑, а нитрат железа(II) Fe(NO3)2 — до Fe2O3 + NO2↑ + O2↑.", "LiNO3 разлагается до LiNO2 + O2↑, а Fe(NO3)2 — до FeO + NO2↑ + O2↑.", "Это два обязательных исключения из правила разложения нитратов в ЕГЭ."], ["Оксид кремния(IV) SiO2 не реагирует с водой, HCl, H2SO4 и HNO3, но растворяется в плавиковой кислоте HF.", "SiO2 как кислотный оксид при кипячении с водой образует кремниевую кислоту H2SiO3.", "Из-за атомной кристаллической решётки SiO2 инертен к воде и обычным кислотам."], ["Гипофосфит натрия NaH2PO2 — это средняя соль одноосновной кислоты H3PO2.", "Соль NaH2PO2 — кислая соль, способная реагировать со щёлочью NaOH.", "Два атома H в H3PO2 связаны напрямую с фосфором и не замещаются на металл."], ["Фосфор и кремний напрямую с водородом H2 не реагируют.", "Фосфин PH3 и силан SiH4 получают прямым синтезом из простых веществ с H2.", "PH3 и SiH4 получают гидролизом фосфидов (Ca3P2) и силицидов (Mg2Si)."]]}], "calc": [], "stress": [], "ortho": [], "punct": [], "tasks": [{"id": "t01_kim6_al_zn_precip", "type": "match", "sk": "amphoteric_al_zn", "ref": "09.12", "n": 6, "lvl": 2, "q": "[Прототип № 6] Даны две пробирки с осадком гидроксида алюминия Al(OH)3. В первую пробирку добавили раствор вещества X, а во вторую — раствор вещества Y. В первой пробирке осадок растворился, а во второй — не изменился. Выберите X и Y из перечня (в ответе укажите 2 вещества по порядку X, Y).", "left": ["Вещество X (растворяет Al(OH)3)", "Вещество Y (НЕ растворяет Al(OH)3)"], "right": ["KOH (изб.)", "NH3·H2O (изб.)", "Na2SO4", "H2O"], "a": [0, 1], "ex": "Al(OH)3 растворяется в избытке сильной щёлочи KOH до K[Al(OH)4] (1), но не растворяется в водном аммиаке NH3·H2O (2) — главная ловушка № 6."}, {"id": "t02_kim6_two_tubes_fecl3", "type": "match", "sk": "transition_fe_cr_cu", "ref": "04.14", "n": 6, "lvl": 3, "q": "[Прототип № 6] В две пробирки с раствором хлорида железа(III) FeCl3 добавили раствор вещества X (в первую) и раствор вещества Y (во вторую). В первой пробирке выпал бурый осадок и выделился газ без запаха, а во второй — выпал жёлтый осадок и раствор стал бледно-зелёным. Определите X и Y.", "left": ["Вещество X (бурый осадок Fe(OH)3↓ + газ CO2↑)", "Вещество Y (жёлтый осадок S↓ + FeCl2)"], "right": ["Na2CO3", "H2S", "NaOH", "KI", "AgNO3"], "a": [0, 1], "ex": "С Na2CO3 идёт совместный гидролиз: 2FeCl3 + 3Na2CO3 + 3H2O → 2Fe(OH)3↓ + 3CO2↑ + 6NaCl (1). С H2S идёт ОВР: 2FeCl3 + H2S → 2FeCl2 + S↓ + 2HCl (2)."}, {"id": "t03_kim6_caco3_vs_aloh3", "type": "match", "sk": "kim6_9_algorithms", "ref": "09.10", "n": 6, "lvl": 2, "q": "[Прототип № 6] В две пробирки с нерастворимым осадком X добавили: в первую — раствор HCl (осадок растворился с выделением газа), во вторую — раствор NaOH (видимых изменений нет). А с осадком Y в HCl осадок растворился без газа, в NaOH — тоже растворился. Определите X и Y.", "left": ["Осадок X (растворяется в HCl с газом, не реагирует с NaOH)", "Осадок Y (амфотерный гидроксид: растворяется в HCl без газа и в NaOH)"], "right": ["CaCO3", "Zn(OH)2", "BaSO4", "CuS", "Fe(OH)3"], "a": [0, 1], "ex": "CaCO3 + 2HCl → CaCl2 + CO2↑ + H2O (1); Zn(OH)2 растворяется в HCl без газа и в NaOH до Na2[Zn(OH)4] (2). BaSO4 и CuS не растворяются в HCl, Fe(OH)3 не растворяется в водном NaOH."}, {"id": "t04_kim7_sio2_co_fe_cu", "type": "match", "sk": "kim6_9_algorithms", "ref": "09.13", "n": 7, "lvl": 3, "q": "[Прототип № 7] Установите соответствие между формулой вещества и набором реагентов, с КАЖДЫМ из которых это вещество может взаимодействовать.", "left": ["SiO2", "Cu", "Al(OH)3", "FeCl3"], "right": ["HF, NaOH, CaCO3", "HNO3(конц.), FeCl3, AgNO3", "HCl, KOH, HNO3", "KI, Na2CO3, Cu", "H2O, HCl, O2"], "a": [0, 1, 2, 3], "ex": "SiO2 → HF, NaOH, CaCO3 (1); Cu → HNO3(конц.), FeCl3, AgNO3 (2); Al(OH)3 → HCl, KOH, HNO3 (3); FeCl3 → KI (ОВР), Na2CO3 (гидролиз), Cu (ОВР) (4)."}, {"id": "t05_kim7_nonmetals", "type": "match", "sk": "p_c_si_compounds", "ref": "08.28", "n": 7, "lvl": 3, "q": "[Прототип № 7] Установите соответствие между простым веществом (неметаллом) и набором из трёх реагентов, с КАЖДЫМ из которых оно реагирует.", "left": ["Cl2", "S", "Si", "P"], "right": ["H2, KOH, KI", "O2, Fe, HNO3(конц.)", "F2, NaOH(водн.), Mg", "O2, Cl2, Ca", "H2O, HCl, Na2SO4"], "a": [0, 1, 2, 3], "ex": "Cl2 → H2, KOH, KI (1); S → O2, Fe, HNO3(конц.) (2); Si → F2, NaOH(водн.), Mg (3); P → O2, Cl2, Ca (4). Помни: Si и P не реагируют с H2 и HCl!"}, {"id": "t06_kim7_salts_oxides", "type": "match", "sk": "active_metals", "ref": "02.36", "n": 7, "lvl": 3, "q": "[Прототип № 7] Установите соответствие между веществом и тройкой реагентов, с КАЖДЫМ из которых оно реагирует.", "left": ["NaHCO3", "NaHSO4", "SO2", "NH3"], "right": ["HCl, KOH, Ba(OH)2", "Mg, Na2CO3, BaCl2", "Br2(водн.), KOH, H2S", "HCl, O2, CuO", "NaCl, O2, H2O"], "a": [0, 1, 2, 3], "ex": "NaHCO3 амфотерен → HCl, KOH, Ba(OH)2 (1); NaHSO4 ведёт себя как кислота + SO4^{2−} → Mg, Na2CO3, BaCl2 (2); SO2 → Br2+H2O, KOH, H2S (3); NH3 → HCl, O2, CuO (4)."}, {"id": "t07_kim8_products_metals", "type": "match", "sk": "transition_fe_cr_cu", "ref": "09.14", "n": 8, "lvl": 3, "q": "[Прототип № 8] Установите соответствие между реагирующими веществами и продуктами их взаимодействия.", "left": ["Fe3O4 + HCl", "Fe3O4 + HNO3(конц., t°)", "Fe3O4 + HI", "Fe + Cl2"], "right": ["FeCl2 + FeCl3 + H2O", "Fe(NO3)3 + NO2 + H2O", "FeI2 + I2 + H2O", "FeCl3", "FeCl2 + H2"], "a": [0, 1, 2, 3], "ex": "Fe3O4 + HCl → FeCl2 + FeCl3 + H2O (1); Fe3O4 + HNO3(конц.) → Fe(NO3)3 + NO2 + H2O (2); Fe3O4 + HI → FeI2 + I2 + H2O (3); Fe + Cl2 → FeCl3 (4)."}, {"id": "t08_kim8_halogens_nitrogen", "type": "match", "sk": "nitrogen_nitrates", "ref": "07.11", "n": 8, "lvl": 3, "q": "[Прототип № 8] Установите соответствие между реагирующими веществами и продуктами реакции.", "left": ["NO2 + KOH", "NO2 + O2 + KOH", "Cl2 + KOH(хол.)", "Cl2 + KOH(гор.)"], "right": ["KNO2 + KNO3 + H2O", "KNO3 + H2O", "KCl + KClO + H2O", "KCl + KClO3 + H2O", "KCl + KClO4 + H2O"], "a": [0, 1, 2, 3], "ex": "NO2 + KOH → KNO2 + KNO3 + H2O (1); с O2 → только KNO3 + H2O (2); Cl2 + KOH(хол.) → KCl + KClO + H2O (3); Cl2 + KOH(гор.) → KCl + KClO3 + H2O (4)."}, {"id": "t09_kim8_h2so4_nitrates", "type": "match", "sk": "halogens", "ref": "05.18", "n": 8, "lvl": 3, "q": "[Прототип № 8] Установите соответствие между исходными веществами (или нагреваемой солью) и продуктами реакции.", "left": ["NaCl(тв.) + H2SO4(конц., t°)", "KBr(тв.) + H2SO4(конц., t°)", "KI(тв.) + H2SO4(конц.)", "Fe(NO3)2 (t°)"], "right": ["NaHSO4 + HCl↑", "Br2 + SO2↑ + K2SO4 + H2O", "I2 + H2S↑ + K2SO4 + H2O", "Fe2O3 + NO2↑ + O2↑", "FeO + NO2↑ + O2↑"], "a": [0, 1, 2, 3], "ex": "NaCl → обмен до HCl↑ (1); KBr → Br2 + SO2↑ (2); KI → I2 + H2S↑ (3); Fe(NO3)2 разлагается с окислением железа до Fe2O3 (4)."}, {"id": "t10_kim9_chain_al", "type": "match", "sk": "amphoteric_al_zn", "ref": "09.15", "n": 9, "lvl": 2, "q": "[Прототип № 9] Задана схема превращений: AlCl3 —(+X)→ Na[Al(OH)4] —(+Y)→ Al(OH)3↓. Определите вещества X и Y.", "left": ["Вещество X", "Вещество Y"], "right": ["NaOH (изб.)", "CO2 (изб.)", "NH3·H2O (изб.)", "HCl (изб.)", "Na2CO3"], "a": [0, 1], "ex": "AlCl3 + 4NaOH(изб.) → Na[Al(OH)4] + 3NaCl (1); Na[Al(OH)4] + CO2(изб.) → Al(OH)3↓ + NaHCO3 (2). Избыток HCl растворил бы осадок до AlCl3."}, {"id": "t11_kim9_chain_fe", "type": "match", "sk": "transition_fe_cr_cu", "ref": "04.4", "n": 9, "lvl": 3, "q": "[Прототип № 9] Задана схема превращений: Fe —(+X)→ FeCl3 —(+Y)→ FeCl2. Определите вещества X и Y.", "left": ["Вещество X (окисляет Fe до FeCl3)", "Вещество Y (восстанавливает FeCl3 до FeCl2)"], "right": ["Cl2", "Cu", "HCl", "NaOH", "O2"], "a": [0, 1], "ex": "2Fe + 3Cl2 → 2FeCl3 (1; с HCl получилось бы FeCl2!); Cu + 2FeCl3 → CuCl2 + 2FeCl2 (2)."}, {"id": "t12_kim9_chain_si", "type": "match", "sk": "p_c_si_compounds", "ref": "08.25", "n": 9, "lvl": 3, "q": "[Прототип № 9] Задана схема превращений: SiO2 —(+X)→ Na2SiO3 —(+Y)→ H2SiO3↓. Определите вещества X и Y.", "left": ["Вещество X (переводит SiO2 в Na2SiO3)", "Вещество Y (осаждает H2SiO3 из Na2SiO3)"], "right": ["NaOH (t°)", "CO2 + H2O", "NaCl", "H2O", "CuO"], "a": [0, 1], "ex": "SiO2 + 2NaOH —t°→ Na2SiO3 + H2O (1); Na2SiO3 + CO2 + H2O → H2SiO3↓ + Na2CO3 (или 2CO2 → 2NaHCO3) (2). Напрямую SiO2 + H2O не идёт!"}, {"id": "t13_kim9_chain_s", "type": "match", "sk": "sulfur_compounds", "ref": "06.15", "n": 9, "lvl": 2, "q": "[Прототип № 9] Задана схема превращений: FeS2 —(+O2, t°)→ X —(+H2S)→ Y. Определите вещества X и Y.", "left": ["Вещество X (газ обжига пирита)", "Вещество Y (жёлтый осадок)"], "right": ["SO2", "S", "SO3", "Fe2O3", "H2SO4"], "a": [0, 1], "ex": "4FeS2 + 11O2 —t°→ 2Fe2O3 + 8SO2↑ (X = SO2, 1); 2H2S + SO2 → 3S↓ + 2H2O (Y = S, 2)."}, {"id": "t14_kim9_chain_n", "type": "match", "sk": "nitrogen_nitrates", "ref": "07.18", "n": 9, "lvl": 3, "q": "[Прототип № 9] Задана схема превращений: Cu(NO3)2 —(t°)→ X(газ) —(+O2, +H2O)→ Y. Определите вещества X и Y.", "left": ["Вещество X (бурый газ)", "Вещество Y (кислота)"], "right": ["NO2", "HNO3", "NO", "HNO2", "NH3"], "a": [0, 1], "ex": "2Cu(NO3)2 —t°→ 2CuO + 4NO2↑ + O2↑ (X = NO2, 1); 4NO2 + O2 + 2H2O → 4HNO3 (Y = HNO3, 2)."}, {"id": "t15_part2_kim31_fe_cl2_na2s", "type": "part2", "sk": "kim31_experiment", "ref": "10.7", "n": 31, "lvl": 3, "max": 4, "q": "[Задание № 31] Железо прокалили в атмосфере хлора. Полученное твёрдое вещество растворили в воде и к раствору добавили избыток раствора сульфида натрия. Выпавший чёрный осадок отделили от серы и растворили в горячей концентрированной азотной кислоте с выделением бурого газа. Выделившийся бурый газ пропустили через раствор гидроксида калия. Напишите уравнения четырёх описанных реакций.", "ideal": "1) 2Fe + 3Cl2 —t°→ 2FeCl3\n2) 2FeCl3 + 3Na2S(изб.) → 2FeS↓ + S↓ + 6NaCl\n3) FeS + 12HNO3(конц.) —t°→ Fe(NO3)3 + H2SO4 + 9NO2↑ + 5H2O\n4) 2NO2 + 2KOH → KNO2 + KNO3 + H2O", "crit": [["Верно записано уравнение 1: 2Fe + 3Cl2 → 2FeCl3", 1], ["Верно записано уравнение 2 (ОВР с избытком Na2S): 2FeCl3 + 3Na2S → 2FeS + S + 6NaCl", 1], ["Верно записано уравнение 3 (двойное окисление FeS конц. HNO3): FeS + 12HNO3 → Fe(NO3)3 + H2SO4 + 9NO2 + 5H2O (допустимо с Fe2(SO4)3)", 1], ["Верно записано уравнение 4 (диспропорционирование NO2): 2NO2 + 2KOH → KNO2 + KNO3 + H2O", 1]], "ex": "Проверка баланса ур. 3: Fe^{+2}→Fe^{+3} (1e⁻) + S^{−2}→S^{+6} (8e⁻) = 9e⁻; N^{+5}→N^{+4} (1e⁻) → 9NO2. Проверка O: 36 = 9 + 4 + 18 + 5."}, {"id": "t16_part2_kim31_al_complex_si", "type": "part2", "sk": "kim31_experiment", "ref": "10.8", "n": 31, "lvl": 3, "max": 4, "q": "[Задание № 31] Алюминий растворили в водном растворе гидроксида натрия. Через полученный раствор пропустили избыток углекислого газа. Выпавший белый осадок отфильтровали и прокалили. Полученный белый порошок сплавили с твёрдым карбонатом натрия. Напишите уравнения четырёх описанных реакций.", "ideal": "1) 2Al + 2NaOH + 6H2O → 2Na[Al(OH)4] + 3H2↑\n2) Na[Al(OH)4] + CO2(изб.) → Al(OH)3↓ + NaHCO3\n3) 2Al(OH)3 —t°→ Al2O3 + 3H2O\n4) Al2O3 + Na2CO3 —сплавление→ 2NaAlO2 + CO2↑", "crit": [["Верно записано уравнение 1: 2Al + 2NaOH + 6H2O → 2Na[Al(OH)4] + 3H2", 1], ["Верно записано уравнение 2 с учётом ИЗБЫТКА CO2 (кислая соль NaHCO3!): Na[Al(OH)4] + CO2 → Al(OH)3 + NaHCO3", 1], ["Верно записано уравнение 3: 2Al(OH)3 → Al2O3 + 3H2O", 1], ["Верно записано уравнение 4 (сплавление до алюмината): Al2O3 + Na2CO3 → 2NaAlO2 + CO2", 1]], "ex": "Ключевая ловушка: в уравнении 2 слово «избыток CO2» обязывает писать NaHCO3, а в уравнении 4 слово «сплавили» — безводный алюминат NaAlO2."}, {"id": "t17_part2_kim31_cr_h2o2_ki", "type": "part2", "sk": "kim31_experiment", "ref": "10.9", "n": 31, "lvl": 3, "max": 4, "q": "[Задание № 31] К раствору хлорида хрома(III) добавили избыток раствора гидроксида натрия до полного растворения первоначально выпавшего осадка. К полученному зелёному раствору прилили пероксид водорода, при этом раствор стал жёлтым. Жёлтый раствор подкислили разбавленной серной кислотой — окраска сменилась на оранжевую. К оранжевому раствору добавили раствор иодида калия (в сернокислой среде), при этом выпал тёмный осадок простого вещества. Напишите уравнения четырёх описанных реакций.", "ideal": "1) CrCl3 + 4NaOH(изб.) → Na[Cr(OH)4] + 3NaCl\n2) 2Na[Cr(OH)4] + 3H2O2 + 2NaOH → 2Na2CrO4 + 8H2O\n3) 2Na2CrO4 + H2SO4 → Na2Cr2O7 + Na2SO4 + H2O\n4) Na2Cr2O7 + 6KI + 7H2SO4 → Cr2(SO4)3 + 3I2↓ + Na2SO4 + 3K2SO4 + 7H2O", "crit": [["Верно записано уравнение 1 (или через Na3[Cr(OH)6]): CrCl3 + 4NaOH → Na[Cr(OH)4] + 3NaCl", 1], ["Верно записано уравнение 2 (окисление Cr(+3) до жёлтого хромата): 2Na[Cr(OH)4] + 3H2O2 + 2NaOH → 2Na2CrO4 + 8H2O", 1], ["Верно записано уравнение 3 (переход в оранжевый дихромат): 2Na2CrO4 + H2SO4 → Na2Cr2O7 + Na2SO4 + H2O", 1], ["Верно записано уравнение 4 (ОВР дихромата с KI): Na2Cr2O7 + 6KI + 7H2SO4 → Cr2(SO4)3 + 3I2 + Na2SO4 + 3K2SO4 + 7H2O", 1]], "ex": "Полный цикл хрома: Cr^{3+} → [Cr(OH)4]⁻ → CrO4^{2−} (жёлтый) → Cr2O7^{2−} (оранжевый) → Cr^{3+} + I2↓."}, {"id": "t18_part2_kim31_si_co2_excess", "type": "part2", "sk": "kim31_experiment", "ref": "10.10", "n": 31, "lvl": 3, "max": 4, "q": "[Задание № 31] Кремний растворили в горячем водном растворе гидроксида натрия с выделением газа. Через полученный раствор пропустили избыток углекислого газа, при этом выпал белый студенистый осадок. Осадок отфильтровали и прокалили до постоянной массы. Полученное твёрдое вещество растворили в плавиковой кислоте с образованием газообразного продукта. Напишите уравнения четырёх описанных реакций.", "ideal": "1) Si + 2NaOH + H2O —t°→ Na2SiO3 + 2H2↑\n2) Na2SiO3 + 2CO2(изб.) + 2H2O → H2SiO3↓ + 2NaHCO3\n3) H2SiO3 —t°→ SiO2 + H2O\n4) SiO2 + 4HF → SiF4↑ + 2H2O", "crit": [["Верно записано уравнение 1: Si + 2NaOH + H2O → Na2SiO3 + 2H2", 1], ["Верно записано уравнение 2 с ИЗБЫТКОМ CO2 (2NaHCO3!): Na2SiO3 + 2CO2 + 2H2O → H2SiO3 + 2NaHCO3", 1], ["Верно записано уравнение 3: H2SiO3 → SiO2 + H2O", 1], ["Верно записано уравнение 4: SiO2 + 4HF → SiF4 + 2H2O", 1]], "ex": "Главная ловушка этого кейса — уравнение 2: при избытке CO2 обязательно образуется кислая соль NaHCO3, а не Na2CO3."}], "subjectSlug": "chemistry", "_kim": {"6": {"b": 2, "l": "П"}, "7": {"b": 2, "l": "П"}, "8": {"b": 2, "l": "П"}, "9": {"b": 1, "l": "П"}, "31": {"b": 4, "l": "В"}}, "_kon": {"01": {"t": "Модуль 01. Логика неорганических реакций и способы получения металлов", "x": "Вся неорганическая химия ЕГЭ подчиняется всего четырём движущим силам: кислотно-основному взаимодействию, окислительно-восстановительному переносу электронов, комплексообразованию и термическому разложению. А способ получения любого металла жёстко задан его положением в электрохимическом ряду напряжений."}, "01.1": {"t": "Модуль 01 · Главная мысль.", "x": "Вся неорганическая химия ЕГЭ подчиняется всего четырём движущим силам: кислотно-основному взаимодействию, окислительно-восстановительному переносу электронов, комплексообразованию и термическому разложению. А способ получения любого металла жёстко задан его положением в электрохимическом ряду напряжений."}, "01.15": {"t": "Модуль 01 · 3. Общие способы получения металлов (металлургия)", "x": "• ****[[электрометаллургия|Электрометаллургия]]**** — Суть и восстановитель: Электролиз расплавов галогенидов, щелочей или раствора Al2O3 в расплавленном криолите Na3[AlF6]; Ключевые уравнения ЕГЭ: 2NaCl(расплав) —электролиз→ 2Na + Cl2↑; 2Al2O3(расплав в криолите) —электролиз→ 4Al + 3O2↑; Для каких металлов: Активные металлы (Li–Al)\n• ****[[пирометаллургия|Пирометаллургия]]**** — Суть и восстановитель: Восстановление оксидов при высокой температуре (C, CO, H2, Al, Mg — металлотермия). Сульфидные руды предварительно обжигают до оксида!; Ключевые уравнения ЕГЭ: Fe2O3 + 3CO —t°→ 2Fe + 3CO2; CuO + H2 —t°→ Cu + H2O; Cr2O3 + 2Al —t°→ 2Cr + Al2O3 ([[алюмотермия]]); Для каких металлов: Средние и малоактивные (Zn, Cr, Fe, Cu, W)…"}, "01.17": {"t": "Модуль 01 · Ловушки ЕГЭ по получению металлов", "x": "Три классические ловушки по металлургии: 1) Al2O3 НЕ восстанавливается водородом H2 и угарным газом CO! 2) При нагревании Fe2O3 + 3C в избытке угля образуется CO (Fe2O3 + 3C —t°→ 2Fe + 3CO↑), хотя в зависимости от условий может выделяться и CO2; 3) При обжиге сульфида ртути HgS сразу получается металлическая ртуть (HgS + O2 —t°→ Hg + SO2↑), потому что оксид HgO термически неустойчив и разлагается на Hg и O2!"}, "02": {"t": "Модуль 02. Активные металлы: Na, K, Ca, Mg и их соединения", "x": "Щелочные (Li, Na, K) и щёлочноземельные (Ca, Ba) металлы — сильнейшие восстановители. Они отдают электроны настолько легко, что в воде мгновенно вытесняют водород, а с кислородом часто образуют пероксиды и надпероксиды. Магний (Mg) — переходный «мостик»: он активен, но при комнатной температуре защищён плотной оксидной плёнкой."}, "02.1": {"t": "Модуль 02 · Главная мысль.", "x": "Щелочные (Li, Na, K) и щёлочноземельные (Ca, Ba) металлы — сильнейшие восстановители. Они отдают электроны настолько легко, что в воде мгновенно вытесняют водород, а с кислородом часто образуют пероксиды и надпероксиды. Магний (Mg) — переходный «мостик»: он активен, но при комнатной температуре защищён плотной оксидной плёнкой."}, "02.4": {"t": "Модуль 02 · 1. Как активные металлы реагируют с кислородом и неметаллами", "x": "• **Li, Mg, Ca** — Реакция с кислородом O2: 4Li + O2 → 2Li2O; 2Mg + O2 —t°→ 2MgO; Продукт и степень окисления O: Обычный оксид (O^{−2}); Почему так получается: Маленькие катионы Li^{+}, Mg^{2+}, Ca^{2+} стабилизируют компактный анион O^{2−}\n• **Na** — Реакция с кислородом O2: 2Na + O2 → Na2O2; Продукт и степень окисления O: [[пероксид|Пероксид натрия]] (O^{−1}); Почему так получается: Крупный Na^{+} легче образует кристаллическую решётку с гантелеобразным O2^{2−}\n• **K (Rb, Cs)** — Реакция с кислородом O2: K + O2 → KO2; Продукт и степень окисления O: Надпероксид калия (O^{−1/2}); Почему так получается: Ещё более крупный K^{+} стабилизирует ион O2^{−}"}, "02.6": {"t": "Модуль 02 · 1. Как активные металлы реагируют с кислородом и неметаллами", "x": "Na2O2 + 2Na —t°→ 2Na2O\n2KO2 + 6K —t°→ 4K2O"}, "02.8": {"t": "Модуль 02 · 1. Как активные металлы реагируют с кислородом и неметаллами", "x": "2Na + H2 —t°→ 2NaH\nCa + H2 —t°→ CaH2\n3Mg + N2 —t°→ Mg3N2\n6Li + N2 → 2Li3N\nCa + 2C —t°→ CaC2"}, "02.12": {"t": "Модуль 02 · 2. Реакции с водой и почему Na не вытесняет медь из раствора CuSO4", "x": "2Na + 2H2O → 2NaOH + H2↑\nCa + 2H2O → Ca(OH)2 + H2↑"}, "02.14": {"t": "Модуль 02 · 2. Реакции с водой и почему Na не вытесняет медь из раствора CuSO4", "x": "Mg + 2H2O(гор.) —t°→ Mg(OH)2↓ + H2↑\nMg + H2O(пар) —t°→ MgO + H2↑"}, "02.15": {"t": "Модуль 02 · Ловушка ЕГЭ: активный металл + водный раствор соли", "x": "Антипаттерн № 1: никогда не пиши вытеснение другого металла щелочным или щёлочноземельным металлом из ВОДНОГО раствора соли! Если бросить натрий в раствор CuSO4, реакция 2Na + CuSO4 → Cu + Na2SO4 НЕ идёт. Молекул воды вокруг натрия во много раз больше, чем ионов Cu^{2+}, поэтому натрий мгновенно реагирует с водой, а образовавшаяся щёлочь NaOH тут же осаждает голубой Cu(OH)2."}, "02.19": {"t": "Модуль 02 · 3. Свойства пероксидов, гидридов и нитридов (хиты № 8 и № 31)", "x": "NaH + H2O → NaOH + H2↑\nCaH2 + 2H2O → Ca(OH)2 + 2H2↑\nMg3N2 + 6H2O → 3Mg(OH)2↓ + 2NH3↑\nCaC2 + 2H2O → Ca(OH)2 + C2H2↑"}, "02.21": {"t": "Модуль 02 · 3. Свойства пероксидов, гидридов и нитридов (хиты № 8 и № 31)", "x": "2Na2O2 + 2CO2 → 2Na2CO3 + O2↑\n2Na2O2 + 2H2O(гор.) → 4NaOH + O2↑\nNa2O2 + 2H2O(хол.) → 2NaOH + H2O2"}, "02.23": {"t": "Модуль 02 · 3. Свойства пероксидов, гидридов и нитридов (хиты № 8 и № 31)", "x": "Na2O2 + SO2 → Na2SO4\nNa2O2 + 2HCl(хол.) → 2NaCl + H2O2"}, "02.25": {"t": "Модуль 02 · 3. Свойства пероксидов, гидридов и нитридов (хиты № 8 и № 31)", "x": "2KI + H2O2 + H2SO4(разб.) → I2↓ + K2SO4 + 2H2O\n2KMnO4 + 5H2O2 + 3H2SO4(разб.) → 2MnSO4 + 5O2↑ + K2SO4 + 8H2O\nH2O2 + Cl2 → 2HCl + O2↑\nH2O2 + Ag2O → 2Ag + O2↑ + H2O"}, "02.28": {"t": "Модуль 02 · 4. Щёлочи, гидроксид магния и взаимопереходы карбонатов", "x": "Mg(OH)2 —t°→ MgO + H2O\nCa(OH)2 —t°→ CaO + H2O"}, "02.34": {"t": "Модуль 02 · 5. Кислые соли (NaHSO4 vs NaHCO3) и основная соль малахит", "x": "2NaHCO3 + 2KOH → Na2CO3 + K2CO3 + 2H2O\n2KHCO3 + Ba(OH)2(нед.) → BaCO3↓ + K2CO3 + 2H2O\nKHCO3 + Ba(OH)2(изб.) → BaCO3↓ + KOH + H2O\n2NaHSO4 + Mg → MgSO4 + Na2SO4 + H2↑\n2NaHSO4 + Na2CO3 → 2Na2SO4 + CO2↑ + H2O"}, "02.36": {"t": "Модуль 02 · Мост к КИМ (№ 6, 7, 8, 9, 31 КИМ)", "x": "**Как спрашивают:** В № 7 дают Na, Ca, Mg, Na2O2, CaCO3, NaHCO3 и просят выбрать строку из трёх реагентов. В № 8 проверяют разницу между реакцией Na с O2, Mg с холодной/горячей водой и Ca(OH)2 с недостатком/избытком CO2. В № 31 часто встречается «известковая вода помутнела, затем осадок растворился».\n**На чём ловят:** Ловят на: 1) попытке написать 4Na + O2 → 2Na2O вместо Na2O2; 2) попытке вытеснить медь натрием из водного раствора CuSO4; 3) разложении Na2CO3 при нагревании (он не разлагается!); 4) реакции Mg с щелочами (магний НЕ амфотерен и со щелочами не реагирует!).\n**Как читать:** Увидев в задании Na, K или Ca — сразу проверяй, есть ли в строке вода, O2, кислоты или неметаллы. Увидев Mg — помни, что он НЕ амфотерен (в отличие от Be, Zn, Al), зато горит даже в CO2 (2Mg + CO2 —t°→ 2MgO + C)."}, "03": {"t": "Модуль 03. Амфотерные металлы: Al и Zn, их оксиды, гидроксиды и комплексы", "x": "Алюминий (Al), цинк (Zn), а также бериллий (Be), свинец (Pb), олово (Sn) и хром(III) образуют [[амфотерный гидроксид|амфотерные]] оксиды и гидроксиды. Они ведут себя как основания с кислотами и как кислоты со щелочами. Главный секрет безошибочных уравнений — жёстко разделять реакции в водном растворе (образуются гидроксокомплексы [Al(OH)4]⁻, [Zn(OH)4]^{2−}) и при сплавлении (образуются средние соли NaAlO2, Na2ZnO2)."}, "03.1": {"t": "Модуль 03 · Главная мысль.", "x": "Алюминий (Al), цинк (Zn), а также бериллий (Be), свинец (Pb), олово (Sn) и хром(III) образуют [[амфотерный гидроксид|амфотерные]] оксиды и гидроксиды. Они ведут себя как основания с кислотами и как кислоты со щелочами. Главный секрет безошибочных уравнений — жёстко разделять реакции в водном растворе (образуются гидроксокомплексы [Al(OH)4]⁻, [Zn(OH)4]^{2−}) и при сплавлении (образуются средние соли NaAlO2, Na2ZnO2)."}, "03.4": {"t": "Модуль 03 · 1. Защитная плёнка Al2O3, пассивация и реакции с водой", "x": "2Al(без плёнки) + 6H2O → 2Al(OH)3↓ + 3H2↑\nZn + H2O(пар) —t°→ ZnO + H2↑"}, "03.7": {"t": "Модуль 03 · 1. Защитная плёнка Al2O3, пассивация и реакции с водой", "x": "2Al + 6HCl → 2AlCl3 + 3H2↑\nZn + H2SO4(разб.) → ZnSO4 + H2↑"}, "03.10": {"t": "Модуль 03 · 2. Реакции Al и Zn со щелочами: раствор vs сплавление", "x": "2Al + 2NaOH(водн.) + 6H2O → 2Na[Al(OH)4] + 3H2↑\nZn + 2NaOH(водн.) + 2H2O → Na2[Zn(OH)4] + H2↑"}, "03.13": {"t": "Модуль 03 · Амфотерные соединения со щелочами: раствор против сплавления", "x": "• **В водном растворе → гидроксокомплекс**: Al2O3 + 2NaOH(водн.) + 3H2O → 2Na[Al(OH)4]; Al(OH)3 + NaOH(водн.) → Na[Al(OH)4]; ZnO + 2NaOH(водн.) + H2O → Na2[Zn(OH)4]; Zn(OH)2 + 2NaOH(водн.) → Na2[Zn(OH)4]\n• **При сплавлении (t°) → безводная соль + H2O↑/CO2↑**: Al2O3 + 2NaOH(тв.) —сплавление→ 2NaAlO2 + H2O↑; Al(OH)3 + NaOH(тв.) —сплавление→ NaAlO2 + 2H2O↑; Al2O3 + Na2CO3(тв.) —сплавление→ 2NaAlO2 + CO2↑; ZnO + Na2CO3(тв.) —сплавление→ Na2ZnO2 + CO2↑"}, "03.18": {"t": "Модуль 03 · 3. Полный цикл переходов алюминия: осадок, комплекс и его разрушение", "x": "Na[Al(OH)4] + HCl(нед.) → Al(OH)3↓ + NaCl + H2O\nNa[Al(OH)4] + 4HCl(изб.) → AlCl3 + NaCl + 4H2O\nNa[Al(OH)4] + CO2(изб.) → Al(OH)3↓ + NaHCO3\nNa2[Zn(OH)4] + 2CO2(изб.) → Zn(OH)2↓ + 2NaHCO3\nNa[Al(OH)4] + SO2(изб.) → Al(OH)3↓ + NaHSO3\nNa[Al(OH)4] + H2S(изб.) → Al(OH)3↓ + NaHS + H2O\nNa[Al(OH)4] + NH4Cl → Al(OH)3↓ + NH3↑ + NaCl + H2O"}, "03.19": {"t": "Модуль 03 · Ловушка ЕГЭ: CO2, NH4Cl и HCl с комплексами + граница с Fe(OH)3", "x": "Почему с CO2, SO2, H2S и солью аммония NH4Cl выпадает осадок Al(OH)3? Угольная, сернистая и сероводородная кислоты слишком слабые, чтобы растворить Al(OH)3, а их избыток даёт кислую соль (NaHCO3, NaHSO3, NaHS). С NH4Cl идёт взаимный гидролиз комплекса с катионом аммония (Al(OH)3↓ + NH3↑). Сильная кислота (HCl, H2SO4, HNO3) в избытке растворяет выпавший осадок до средней соли AlCl3! Заодно запомни границу амфотерности ЕГЭ: в водном растворе NaOH растворяются Al(OH)3, Zn(OH)2, Cr(OH)3, но **не** Fe(OH)3 (он реагирует со щёлочью только при сплавлении — подробнее в модуле 04)."}, "03.21": {"t": "Модуль 03 · 4. Важнейшее отличие Al(OH)3 от Zn(OH)2 — реакция с водным аммиаком", "x": "Водный раствор аммиака NH3·H2O — слабое основание. Его концентрации OH^{−} хватает, чтобы осадить Al(OH)3 из соли алюминия, но **не хватает**, чтобы растворить Al(OH)3 в гидроксокомплекс. Поэтому при добавлении избытка NH3·H2O к AlCl3 осадок Al(OH)3 **не растворяется**!"}, "03.23": {"t": "Модуль 03 · 4. Важнейшее отличие Al(OH)3 от Zn(OH)2 — реакция с водным аммиаком", "x": "AlCl3 + 3NH3·H2O(изб.) → Al(OH)3↓ + 3NH4Cl\nZn(OH)2 + 4NH3·H2O(изб.) → [Zn(NH3)4](OH)2 + 4H2O"}, "03.26": {"t": "Модуль 03 · 5. Совместный (необратимый) гидролиз солей алюминия", "x": "Al2S3 + 6H2O → 2Al(OH)3↓ + 3H2S↑\n2AlCl3 + 3Na2CO3 + 3H2O → 2Al(OH)3↓ + 3CO2↑ + 6NaCl\nAlCl3 + 3NaHCO3 → Al(OH)3↓ + 3CO2↑ + 3NaCl\n2Al(NO3)3 + 3K2S + 6H2O → 2Al(OH)3↓ + 3H2S↑ + 6KNO3"}, "04": {"t": "Модуль 04. Переходные металлы: Fe, Cr, Cu и их соединения", "x": "У d-металлов (Fe, Cr, Cu) несколько устойчивых степеней окисления, и с ростом степени окисления характер оксида и гидроксида меняется от **основного** к **амфотерному** и далее к **кислотному** (CrO основный → Cr2O3 амфотерный → CrO3 кислотный). Чтобы не ошибаться в продуктах, нужно различать силу окислителя и среду раствора."}, "04.1": {"t": "Модуль 04 · Главная мысль.", "x": "У d-металлов (Fe, Cr, Cu) несколько устойчивых степеней окисления, и с ростом степени окисления характер оксида и гидроксида меняется от **основного** к **амфотерному** и далее к **кислотному** (CrO основный → Cr2O3 амфотерный → CrO3 кислотный). Чтобы не ошибаться в продуктах, нужно различать силу окислителя и среду раствора."}, "04.4": {"t": "Модуль 04 · Куда окисляется металлическое железо Fe(0)?", "x": "• **Слабые/умеренные окислители → Fe(+2)**: Неокисляющие кислоты: Fe + 2HCl → FeCl2 + H2↑; Fe + H2SO4(разб.) → FeSO4 + H2↑; Соли менее активных металлов: Fe + CuSO4 → FeSO4 + Cu; Сера и иод: Fe + S —t°→ FeS; Fe + I2 —t°→ FeI2 (I2 слишком слабый окислитель, чтобы перевести Fe в +3!); Соли Fe(III): Fe + 2FeCl3 → 3FeCl2\n• **Сильные окислители → Fe(+3)**: Хлор и бром: 2Fe + 3Cl2 —t°→ 2FeCl3; 2Fe + 3Br2 —t°→ 2FeBr3; Азотная кислота (разб. при н.у., конц. при нагревании!): Fe + 6HNO3(конц.) —t°→ Fe(NO3)3 + 3NO2↑ + 3H2O; Fe + 4HNO3(разб.) → Fe(NO3)3 + NO↑ + 2H2O; Концентрированная серная кислота (при нагревании!): 2Fe + 6H2SO4(конц.) —t°→ Fe2(SO4)3 + 3SO2↑ + 6H2O"}, "04.6": {"t": "Модуль 04 · 1. Железо (Fe): когда получается +2, когда +3, а когда Fe3O4", "x": "3Fe + 2O2 —t°→ Fe3O4\n3Fe + 4H2O(пар) —t°→ Fe3O4 + 4H2↑"}, "04.8": {"t": "Модуль 04 · 1. Железо (Fe): когда получается +2, когда +3, а когда Fe3O4", "x": "Fe3O4 + 8HCl → FeCl2 + 2FeCl3 + 4H2O\nFe3O4 + 10HNO3(конц.) —t°→ 3Fe(NO3)3 + NO2↑ + 5H2O\nFe3O4 + 8HI → 3FeI2 + I2 + 4H2O"}, "04.11": {"t": "Модуль 04 · 2. Гидроксиды железа и ловушка «ОВР вместо совместного гидролиза»", "x": "4Fe(OH)2 + O2 + 2H2O → 4Fe(OH)3"}, "04.12": {"t": "Модуль 04 · 2. Гидроксиды железа и ловушка «ОВР вместо совместного гидролиза»", "x": "Гидроксид железа(III) Fe(OH)3 проявляет очень слабые амфотерные свойства: в рамках ЕГЭ принято, что **в водном растворе щёлочи Fe(OH)3 не растворяется**, но при **сплавлении** с твёрдыми щелочами и карбонатами образует **ферриты** (NaFeO2), а при действии сильных окислителей (Cl2, Br2, NaClO) в концентрированной щёлочи окисляется до фиолетовых **ферратов** (Na2FeO4, Fe^{+6}):"}, "04.13": {"t": "Модуль 04 · 2. Гидроксиды железа и ловушка «ОВР вместо совместного гидролиза»", "x": "Fe(OH)3 + NaOH(тв.) —сплавление→ NaFeO2 + 2H2O↑\nFe2O3 + Na2CO3(тв.) —сплавление→ 2NaFeO2 + CO2↑\n2Fe(OH)3 + 3Cl2 + 10NaOH(конц.) → 2Na2FeO4 + 6NaCl + 8H2O"}, "04.14": {"t": "Модуль 04 · Ловушка ЕГЭ: Fe^{3+} с CO3^{2−} vs с S^{2−}, SO3^{2−}, I⁻", "x": "Антипаттерн № 3 (главная ошибка в № 6, 8, 30, 31): ион Fe^{3+} — сильный окислитель! С карбонатами (Na2CO3, NaHCO3) соли Fe^{3+} дают **совместный гидролиз** (2FeCl3 + 3Na2CO3 + 3H2O → 2Fe(OH)3↓ + 3CO2↑ + 6NaCl). А вот с сульфидами (S^{2−}, H2S), сульфитами (SO3^{2−}, SO2) и иодидами (I⁻, HI) идёт **ОВР**, а НЕ гидролиз и НЕ обмен!"}, "04.15": {"t": "Модуль 04 · 2. Гидроксиды железа и ловушка «ОВР вместо совместного гидролиза»", "x": "2FeCl3 + 2KI → 2FeCl2 + I2 + 2KCl\n2FeCl3 + H2S → 2FeCl2 + S↓ + 2HCl\n2FeCl3 + Na2S(нед.) → 2FeCl2 + S↓ + 2NaCl\n2FeCl3 + 3Na2S(изб.) → 2FeS↓ + S↓ + 6NaCl\n2FeCl3 + Na2SO3 + H2O → 2FeCl2 + Na2SO4 + 2HCl"}, "04.21": {"t": "Модуль 04 · 3. Хром (Cr): амфотерный Cr(+3) и цветовые качели Cr(+6)", "x": "2K2CrO4 + H2SO4(разб.) → K2Cr2O7 + K2SO4 + H2O\nK2Cr2O7 + 2KOH → 2K2CrO4 + H2O\n2Na[Cr(OH)4] + 3H2O2 + 2NaOH → 2Na2CrO4 + 8H2O\nCr2O3 + 3KNO3 + 2K2CO3 —сплавление→ 2K2CrO4 + 3KNO2 + 2CO2↑\nK2Cr2O7 + 14HCl(конц.) —t°→ 2CrCl3 + 3Cl2↑ + 2KCl + 7H2O\nK2Cr2O7 + 6KI + 7H2SO4(разб.) → Cr2(SO4)3 + 3I2↓ + 4K2SO4 + 7H2O\n(NH4)2Cr2O7 —t°→ N2↑ + Cr2O3 + 4H2O"}, "04.24": {"t": "Модуль 04 · 4. Марганец (KMnO4, MnO2): главный окислитель ЕГЭ и влияние среды", "x": "2KMnO4 —t°→ K2MnO4 + MnO2 + O2↑\n2KMnO4 + 16HCl(конц.) → 2KCl + 2MnCl2 + 5Cl2↑ + 8H2O\nMnO2 + 4HCl(конц.) —t°→ MnCl2 + Cl2↑ + 2H2O\n2KMnO4 + 3Na2SO3 + H2O → 2MnO2↓ + 3Na2SO4 + 2KOH\n2KMnO4 + Na2SO3 + 2KOH → 2K2MnO4 + Na2SO4 + H2O"}, "04.27": {"t": "Модуль 04 · 5. Медь (Cu) и серебро (Ag): металлы после водорода", "x": "2Cu + O2 —t°→ 2CuO\n2Cu + S —t°→ Cu2S\nCu + 2FeCl3 → CuCl2 + 2FeCl2\nCu + 2AgNO3 → Cu(NO3)2 + 2Ag\nCu + 4HNO3(конц.) → Cu(NO3)2 + 2NO2↑ + 2H2O\nCu + 2H2SO4(конц.) —t°→ CuSO4 + SO2↑ + 2H2O"}, "04.30": {"t": "Модуль 04 · 5. Медь (Cu) и серебро (Ag): металлы после водорода", "x": "2CuSO4 + 4KI → 2CuI↓ + I2↓ + 2K2SO4\n2AgNO3 + 2NaOH → Ag2O↓ + 2NaNO3 + H2O"}, "05": {"t": "Модуль 05. Галогены (F2, Cl2, Br2, I2) и их соединения", "x": "В ряду F2 → Cl2 → Br2 → I2 окислительная способность простых веществ **падает**, а восстановительная способность их анионов F⁻ → Cl⁻ → Br⁻ → I⁻ — **растёт**. Фтор настолько силён, что окисляет даже воду, а Cl2, Br2 и I2 в щелочах вступают в диспропорционирование."}, "05.1": {"t": "Модуль 05 · Главная мысль.", "x": "В ряду F2 → Cl2 → Br2 → I2 окислительная способность простых веществ **падает**, а восстановительная способность их анионов F⁻ → Cl⁻ → Br⁻ → I⁻ — **растёт**. Фтор настолько силён, что окисляет даже воду, а Cl2, Br2 и I2 в щелочах вступают в диспропорционирование."}, "05.4": {"t": "Модуль 05 · 1. Окислительная активность галогенов и особое поведение фтора", "x": "Cl2 + 2NaBr → 2NaCl + Br2\nCl2 + 2KI → 2KCl + I2↓\nBr2 + 2KI → 2KBr + I2↓"}, "05.5": {"t": "Модуль 05 · Ловушка ЕГЭ: фтор с водой и растворами солей", "x": "Почему фтор F2 НЕ вытесняет хлор из водного раствора NaCl? Потому что фтор — самый сильный окислитель среди простых веществ: он мгновенно и со взрывом окисляет саму **воду** с выделением кислорода! В этой реакции кислород повышает степень окисления с −2 до 0:"}, "05.6": {"t": "Модуль 05 · 1. Окислительная активность галогенов и особое поведение фтора", "x": "2F2 + 2H2O → 4HF + O2↑"}, "05.8": {"t": "Модуль 05 · 1. Окислительная активность галогенов и особое поведение фтора", "x": "H2 + Cl2 —hν→ 2HCl\n2P + 3Cl2(нед.) → 2PCl3\n2P + 5Cl2(изб.) → 2PCl5\n3Cl2 + 8NH3(изб.) → N2↑ + 6NH4Cl"}, "05.11": {"t": "Модуль 05 · 2. Реакции Cl2, Br2, I2 с водой и щелочами (диспропорционирование)", "x": "Cl2 + H2O ⇄ HCl + HClO"}, "05.13": {"t": "Модуль 05 · Хлор (и бром) со щёлочью: холод vs нагревание", "x": "• **На холоде (Cl⁰ → Cl^{−1} + Cl^{+1})**: Cl2 + 2NaOH(хол.) → NaCl + NaClO + H2O (жавелева вода); 2Cl2 + 2Ca(OH)2(хол.) → CaCl2 + Ca(ClO)2 + 2H2O (хлорная известь); Br2 + 2KOH(хол.) → KBr + KBrO + H2O\n• **При нагревании (Cl⁰ → Cl^{−1} + Cl^{+5})**: 3Cl2 + 6KOH(гор.) —t°→ 5KCl + KClO3 + 3H2O (бертолетова соль); 3Br2 + 6NaOH(гор.) —t°→ 5NaBr + NaBrO3 + 3H2O; 3I2 + 6KOH → 5KI + KIO3 + 3H2O (иод даёт иодат уже при н.у.!)"}, "05.16": {"t": "Модуль 05 · 3. Галогеноводороды, сила кислот и ловушка с концентрированной H2SO4", "x": "SiO2 + 4HF → SiF4↑ + 2H2O"}, "05.18": {"t": "Модуль 05 · 3. Галогеноводороды, сила кислот и ловушка с концентрированной H2SO4", "x": "• **NaCl(тв.) (или CaF2)** — Уравнение с H2SO4(конц.): NaCl(тв.) + H2SO4(конц.) —t°→ NaHSO4 + HCl↑; Тип реакции: **Обмен (не ОВР!)**; Почему продукт именно такой: Cl⁻ — слабый восстановитель; H2SO4(конц.) его не окисляет, а вытесняет летучий HCl (получение HCl в лаборатории)\n• **KBr(тв.)** — Уравнение с H2SO4(конц.): 2KBr(тв.) + 2H2SO4(конц.) → Br2 + SO2↑ + K2SO4 + 2H2O; Тип реакции: **ОВР**; Почему продукт именно такой: Br⁻ сильнее, он восстанавливает S^{+6} до SO2 (S^{+4}) и сам окисляется до бурого Br2\n• **KI(тв.)** — Уравнение с H2SO4(конц.): 8KI(тв.) + 5H2SO4(конц.) → 4I2 + H2S↑ + 4K2SO4 + 4H2O; Тип реакции: **Глубокая ОВР**; Почему продукт именно такой: I⁻ — очень сильный восстановитель, доводит S^{+6} до самого низа — H2S (S^{−2})"}, "05.22": {"t": "Модуль 05 · 4. Кислородные соединения хлора: разложение хлората калия KClO3", "x": "2KClO3 —t°, кат. MnO2→ 2KCl + 3O2↑\n4KClO3 —t° (без кат.)→ 3KClO4 + KCl"}, "06": {"t": "Модуль 06. Сера и её соединения: от сульфидов до концентрированной H2SO4", "x": "Поведение серы и её соединений легко читать по шкале степеней окисления: S^{−2} (H2S, сульфиды) — только восстановитель; S⁰ и S^{+4} (SO2, сульфиты) — двойственные (и окислитель, и восстановитель); S^{+6} (SO3, H2SO4(конц.)) — только окислитель."}, "06.1": {"t": "Модуль 06 · Главная мысль.", "x": "Поведение серы и её соединений легко читать по шкале степеней окисления: S^{−2} (H2S, сульфиды) — только восстановитель; S⁰ и S^{+4} (SO2, сульфиты) — двойственные (и окислитель, и восстановитель); S^{+6} (SO3, H2SO4(конц.)) — только окислитель."}, "06.5": {"t": "Модуль 06 · 1. Простое вещество сера S(0)", "x": "Fe + S —t°→ FeS\n2Cu + S —t°→ Cu2S\n2Al + 3S —t°→ Al2S3"}, "06.7": {"t": "Модуль 06 · 1. Простое вещество сера S(0)", "x": "S + O2 —t°→ SO2\n3S + 6KOH(гор., конц.) —t°→ 2K2S + K2SO3 + 3H2O\nS + 6HNO3(конц.) —t°→ H2SO4 + 6NO2↑ + 2H2O\nS + 2H2SO4(конц.) —t°→ 3SO2↑ + 2H2O"}, "06.8": {"t": "Модуль 06 · Ловушка ЕГЭ: S + O2 никогда не даёт SO3", "x": "Антипаттерн № 4: при сжигании серы в кислороде образуется ТОЛЬКО SO2! Получить SO3 из серы в одну стадию нельзя — нужен катализатор V2O5 и нагревание для окисления уже готового SO2: 2SO2 + O2 ⇄t°, кат. V2O5 2SO3."}, "06.11": {"t": "Модуль 06 · 2. Сероводород H2S, сульфиды и обжиг пирита FeS2", "x": "2H2S + O2(нед.) —t°→ 2S↓ + 2H2O\n2H2S + 3O2(изб.) —t°→ 2SO2↑ + 2H2O\n2H2S + SO2 → 3S↓ + 2H2O\nH2S + 8HNO3(конц.) → H2SO4 + 8NO2↑ + 4H2O"}, "06.15": {"t": "Модуль 06 · 2. Сероводород H2S, сульфиды и обжиг пирита FeS2", "x": "4FeS2 + 11O2 —t°→ 2Fe2O3 + 8SO2↑"}, "06.18": {"t": "Модуль 06 · 3. Оксид серы(IV) SO2 и сульфиты", "x": "SO2 + Br2 + 2H2O → H2SO4 + 2HBr\nSO2 + Cl2 + 2H2O → H2SO4 + 2HCl\n5SO2 + 2KMnO4 + 2H2O → K2SO4 + 2MnSO4 + 2H2SO4\nNa2SO3 + H2O2 → Na2SO4 + H2O"}, "07": {"t": "Модуль 07. Азот, аммиак, оксиды азота, азотная кислота и разложение нитратов", "x": "Азот охватывает степени окисления от −3 (NH3, NH4^{+}) до +5 (HNO3, нитраты). Три главных опоры экзамена: аммиак проявляет одновременно основные и восстановительные свойства; HNO3 любой концентрации — окислитель (без H2); схема термического разложения нитратов привязана к ряду напряжений, но имеет 4 обязательных исключения."}, "07.1": {"t": "Модуль 07 · Главная мысль.", "x": "Азот охватывает степени окисления от −3 (NH3, NH4^{+}) до +5 (HNO3, нитраты). Три главных опоры экзамена: аммиак проявляет одновременно основные и восстановительные свойства; HNO3 любой концентрации — окислитель (без H2); схема термического разложения нитратов привязана к ряду напряжений, но имеет 4 обязательных исключения."}, "07.7": {"t": "Модуль 07 · 1. Азот N2, аммиак NH3 и соли аммония", "x": "NH4Cl —t°→ NH3↑ + HCl↑\nNH4HCO3 —t°→ NH3↑ + CO2↑ + H2O\nNH4NO2 —t°→ N2↑ + 2H2O\nNH4NO3 —t°→ N2O↑ + 2H2O\n(NH4)2Cr2O7 —t°→ N2↑ + Cr2O3 + 4H2O"}, "07.11": {"t": "Модуль 07 · 2. Оксиды азота: несолеобразующие vs NO2 (смешанный ангидрид)", "x": "2NO2 + H2O(хол.) → HNO2 + HNO3\n3NO2 + H2O(гор.) → 2HNO3 + NO↑\n2NO2 + 2KOH → KNO2 + KNO3 + H2O\n4NO2 + O2 + 2H2O → 4HNO3\n4NO2 + O2 + 4KOH → 4KNO3 + 2H2O"}, "07.17": {"t": "Модуль 07 · 4. Термическое разложение нитратов (хит № 8, 9, 31)", "x": "Нитраты при нагревании разлагаются строго по электрохимическому ряду напряжений — чем менее активен металл, тем глубже распадается соль:"}, "07.18": {"t": "Модуль 07 · 4. Термическое разложение нитратов (хит № 8, 9, 31)", "x": "См. наглядную схему в учебнике."}, "08": {"t": "Модуль 08. Фосфор, углерод, кремний и их соединения", "x": "Фосфор (P), углерод (C) и кремний (Si) — неметаллы, в которых ЕГЭ особенно любит проверять нестандартные свойства: диспропорционирование фосфора в щелочах, три ряда фосфатов, реакции углерода и CO как восстановителей, гидролиз карбидов/фосфидов/силицидов, а также уникальную «кислотостойкость» Si и SiO2 при их реакции с HF и щелочами."}, "08.1": {"t": "Модуль 08 · Главная мысль.", "x": "Фосфор (P), углерод (C) и кремний (Si) — неметаллы, в которых ЕГЭ особенно любит проверять нестандартные свойства: диспропорционирование фосфора в щелочах, три ряда фосфатов, реакции углерода и CO как восстановителей, гидролиз карбидов/фосфидов/силицидов, а также уникальную «кислотостойкость» Si и SiO2 при их реакции с HF и щелочами."}, "08.4": {"t": "Модуль 08 · 1. Фосфор (P), фосфиды и три ряда солей H3PO4", "x": "4P + 3O2(нед.) —t°→ 2P2O3\n4P + 5O2(изб.) —t°→ 2P2O5\n2P + 3Cl2(нед.) → 2PCl3\n2P + 5Cl2(изб.) → 2PCl5"}, "08.6": {"t": "Модуль 08 · 1. Фосфор (P), фосфиды и три ряда солей H3PO4", "x": "3Ca + 2P —t°→ Ca3P2\nCa3P2 + 6H2O → 3Ca(OH)2 + 2PH3↑\n4P(белый) + 3NaOH(конц.) + 3H2O —t°→ PH3↑ + 3NaH2PO2"}, "08.7": {"t": "Модуль 08 · Почему NaH2PO2 — средняя, а не кислая соль?", "x": "Обрати внимание на соль NaH2PO2 — это **гипофосфит натрия** (средняя соль одноосновной фосфорноватистой кислоты H3PO2, где степень окисления фосфора +1). Два атома водорода в H2PO2⁻ связаны напрямую с фосфором и на металл не замещаются!"}, "08.9": {"t": "Модуль 08 · 1. Фосфор (P), фосфиды и три ряда солей H3PO4", "x": "PCl3 + 3H2O → H3PO3 + 3HCl\nPCl5 + 4H2O → H3PO4 + 5HCl\nP2O5 + H2O(хол.) → 2HPO3\nP2O5 + 3H2O(гор.) → 2H3PO4\nCa3(PO4)2 + 3SiO2 + 5C —t°→ 3CaSiO3 + 2P + 5CO↑"}, "08.12": {"t": "Модуль 08 · 1. Фосфор (P), фосфиды и три ряда солей H3PO4", "x": "Ca3(PO4)2 + 4H3PO4 → 3Ca(H2PO4)2\nCa(H2PO4)2 + Ca(OH)2(нед.) → 2CaHPO4↓ + 2H2O\nCa(H2PO4)2 + 2Ca(OH)2(изб.) → Ca3(PO4)2↓ + 4H2O"}, "08.15": {"t": "Модуль 08 · 2. Углерод (C), оксиды CO и CO2, карбиды и карбонаты", "x": "2C + O2(нед.) —t°→ 2CO\nC + O2(изб.) —t°→ CO2\nC + CO2 —t°→ 2CO\nC + H2O(пар) —t°→ CO↑ + H2↑\nCaO + 3C —t°→ CaC2 + CO↑\nSiO2 + 2C —t°→ Si + 2CO↑"}, "08.22": {"t": "Модуль 08 · 3. Кремний (Si), оксид кремния(IV) SiO2 и силикаты", "x": "Si + 2NaOH(водн.) + H2O —t°→ Na2SiO3 + 2H2↑\nSi + 2F2 → SiF4↑\nSi + 2Cl2 —t°→ SiCl4\nSiCl4 + 3H2O → H2SiO3↓ + 4HCl\nSi + O2 —t°→ SiO2\nSi + 2Mg —t°→ Mg2Si\nMg2Si + 4HCl → 2MgCl2 + SiH4↑"}, "08.23": {"t": "Модуль 08 · Ловушка ЕГЭ: SiO2 vs Si с водой и кислотами", "x": "Антипаттерн № 6 (ловушка на каждый второй вариант № 7): оксид кремния(IV) SiO2 имеет атомную кристаллическую решётку, поэтому он **НЕ реагирует с водой**! Нельзя писать SiO2 + H2O → H2SiO3. Единственная кислота, которая растворяет SiO2, — это плавиковая кислота HF (SiO2 + 4HF → SiF4↑ + 2H2O). А вот сам кремний Si с отдельной HF в ЕГЭ НЕ реагирует!"}, "08.25": {"t": "Модуль 08 · 3. Кремний (Si), оксид кремния(IV) SiO2 и силикаты", "x": "SiO2 + Na2CO3 —сплавление→ Na2SiO3 + CO2↑\nSiO2 + CaCO3 —сплавление→ CaSiO3 + CO2↑\nSiO2 + 2NaOH —t°→ Na2SiO3 + H2O\nSiO2 + CaO —t°→ CaSiO3\nSiO2 + 2Mg —t°→ Si + 2MgO"}, "08.28": {"t": "Модуль 08 · Мост к КИМ (№ 6, 7, 8, 9, 31 КИМ)", "x": "**Как спрашивают:** В № 7 P, C, Si, CO, CO2, SiO2 — любимые «убийцы баллов». В № 8 и № 31 часто проверяют гидролиз CaC2/Al4C3/Ca3P2/Mg2Si/PCl5/SiCl4, сплавление SiO2 + Na2CO3 и растворение Si в NaOH.\n**На чём ловят:** Ловят на: 1) P + H2 и Si + H2 (напрямую НЕ идут!); 2) SiO2 + H2O (НЕ идёт!); 3) Si с отдельными кислотами HCl, H2SO4, HNO3, HF (НЕ идёт!); 4) CO + NaOH(водн.) при н.у. (НЕ идёт!); 5) попытке осадить H2SiO3 из SiO2 + H2O вместо Na2SiO3 + HCl или Na2SiO3 + CO2 + H2O.\n**Как читать:** Увидев Si в № 7 — сразу ищи в строке NaOH, F2, Cl2, O2, Mg, и смело вычёркивай строки с H2, HCl, H2SO4, HF, H2O. Увидев SiO2 — ищи HF, NaOH, Na2CO3, CaO, C, Mg, и вычёркивай H2O, HCl, HNO3."}, "09": {"t": "Модуль 09. Задания № 6, 7, 8, 9 КИМ: алгоритмы отбора реагентов и генетические цепочки", "x": "Задания № 6, 7, 8 (по 2 балла) и № 9 (1 балл) дают суммарно **7 первичных баллов** — больше десятой части всего экзамена! В № 7 ключ к скорости — **метод отсева** (достаточно найти одно нереагирующее вещество, чтобы вычеркнуть всю строку), а в № 9 — знание [[генетическая связь|генетических мостиков]] через нерастворимые оксиды, гидроксиды и смену степени окисления."}, "09.1": {"t": "Модуль 09 · Главная мысль.", "x": "Задания № 6, 7, 8 (по 2 балла) и № 9 (1 балл) дают суммарно **7 первичных баллов** — больше десятой части всего экзамена! В № 7 ключ к скорости — **метод отсева** (достаточно найти одно нереагирующее вещество, чтобы вычеркнуть всю строку), а в № 9 — знание [[генетическая связь|генетических мостиков]] через нерастворимые оксиды, гидроксиды и смену степени окисления."}, "09.10": {"t": "Модуль 09 · 3. Различение осадков в кислотах (хит задания № 6)", "x": "• **BaSO4 (белый)** — Реакция с HCl / HNO3(разб.): **НЕ растворяется** ни в HCl, ни в HNO3; Как это используют в № 6: Отличает сульфат от BaCO3 и BaSO3 (оба белые, но растворяются в HCl с выделением CO2↑ и SO2↑)\n• **AgCl (белый), AgBr (бледно-жёлтый), AgI (жёлтый)** — Реакция с HCl / HNO3(разб.): **НЕ растворяются** в HNO3; Как это используют в № 6: Отличает галогениды серебра от жёлтого Ag3PO4 (он **растворяется** в HNO3!)\n• **CuS, Ag2S, PbS, HgS (чёрные)** — Реакция с HCl / HNO3(разб.): **НЕ растворяются** в HCl/H2SO4(разб.), но растворяются в HNO3; Как это используют в № 6: Отличает их от FeS и ZnS, которые растворяются в HCl с запахом H2S"}, "09.12": {"t": "Модуль 09 · 4. Полные разборы форматов № 6, № 7, № 8 и № 9", "x": "**Шаг 1.** **Разбор 1 (формат № 6 — две пробирки):** В пробирку с раствором соли X добавили раствор NaOH — выпал осадок, который растворился в избытке щёлочи. В другую пробирку с тем же X добавили раствор BaCl2 — выпал белый осадок. Кто X?\n**Шаг 2.** **Ход мысли:** 1) Осадок, растворимый в избытке NaOH → амфотерный катион (Al^{3+}, Zn^{2+} или Cr^{3+}). 2) Белый осадок с BaCl2 → анион SO4^{2−} (или CO3^{2−}/SO3^{2−}, но с Al^{3+} они не существуют!). Значит X — **сульфат алюминия Al2(SO4)3** (или ZnSO4)."}, "09.13": {"t": "Модуль 09 · 4. Полные разборы форматов № 6, № 7, № 8 и № 9", "x": "**Шаг 1.** **Разбор 2 (формат № 7 — отбор строки):** Для оксида кремния(IV) SiO2 выбери строку из 3 реагентов: 1) H2O, NaOH, HF; 2) HCl, CaO, C; 3) Na2CO3, HF, KOH; 4) SO2, O2, NaCl.\n**Шаг 2.** **Метод отсева:** в строке 1 сразу вычёркиваем H2O (SiO2 с водой не реагирует); в строке 2 вычёркиваем HCl; в строке 4 вычёркиваем кислотный оксид SO2, O2 и NaCl. Остаётся **строка 3**: SiO2 + Na2CO3 —сплавление→ Na2SiO3 + CO2↑; SiO2 + 4HF → SiF4↑ + 2H2O; SiO2 + 2KOH —t°→ K2SiO3 + H2O. Все три реакции идут!"}, "09.14": {"t": "Модуль 09 · 4. Полные разборы форматов № 6, № 7, № 8 и № 9", "x": "**Шаг 1.** **Разбор 3 (формат № 8 — исходные → продукты):** Сравни две почти одинаковые пары: А) Fe3O4 + HCl и Б) Fe3O4 + HNO3(конц.) при нагревании.\n**Шаг 2.** **Ход мысли:** Fe3O4 содержит Fe^{+2} и Fe^{+3}. Кислота HCl не окислитель → степени окисления сохраняются, получаем **две соли**: FeCl2 + FeCl3 + H2O. Кислота HNO3(конц.) — сильный окислитель → весь Fe^{+2} окисляется до Fe^{+3}, получаем **одну соль** Fe(NO3)3 + NO2↑ + H2O."}, "09.15": {"t": "Модуль 09 · 4. Полные разборы форматов № 6, № 7, № 8 и № 9", "x": "**Шаг 1.** **Разбор 4 (формат № 9 — цепочка X → Y):** Fe —(+X)→ FeCl3 —(+Y)→ FeCl2.\n**Шаг 2.** **Ход мысли:** 1) Чтобы перевести Fe(0) сразу в Fe(+3) (а не в FeCl2!), нужна не HCl, а сильный окислитель — **хлор Cl2** (2Fe + 3Cl2 —t°→ 2FeCl3). 2) Чтобы восстановить FeCl3 до FeCl2 без лишних посторонних катионов или с чистым переходом, идеально подходит **железо Fe** (2FeCl3 + Fe → 3FeCl2), либо Cu, либо KI/H2S (смотря что есть в списке вариантов!)."}, "10": {"t": "Модуль 10. Задание № 31 КИМ: мысленный эксперимент из 4 реакций на 4/4 балла", "x": "Задание № 31 оценивается в **4 первичных балла** — ровно по **1 баллу за каждое правильно записанное и уравненное уравнение**. Даже если одна реакция не получилась, остальные три принесут 3 балла. Главный ключ — не писать уравнения вслепую, а сначала составить краткую «карту веществ» по цветовым, газовым и температурным маркерам текста."}, "10.1": {"t": "Модуль 10 · Главная мысль.", "x": "Задание № 31 оценивается в **4 первичных балла** — ровно по **1 баллу за каждое правильно записанное и уравненное уравнение**. Даже если одна реакция не получилась, остальные три принесут 3 балла. Главный ключ — не писать уравнения вслепую, а сначала составить краткую «карту веществ» по цветовым, газовым и температурным маркерам текста."}, "10.5": {"t": "Модуль 10 · 2. Словарь маркеров задания № 31 (как читать подсказки текста)", "x": "• **«Выделился **бурый газ**»** — Что это за вещество / процесс: NO2 (или пары Br2, если речь о бромидах); На что сразу обратить внимание: Реакция с HNO3(конц.) или разложение нитрата группы Mg–Cu / Li / Ag\n• **«Бесцветный газ, **буреющий на воздухе**»** — Что это за вещество / процесс: NO (2NO + O2 → 2NO2); На что сразу обратить внимание: Реакция с HNO3(разб.) или каталитическое окисление NH3\n• **«Газ с **запахом тухлых яиц**»** — Что это за вещество / процесс: H2S; На что сразу обратить внимание: Сульфид + HCl, совместный гидролиз Al2S3/Cr2S3, или KI/Zn + H2SO4(конц.)\n• **«Газ с **резким запахом**»** — Что это за вещество / процесс: NH3 (щелочная среда), SO2 (обесцвечивает KMnO4/Br2), HCl; На что сразу обратить внимание: Смотри, в какой среде газ выделился: со щёлочью → NH3, с кислотой → SO2 или HCl…"}, "10.7": {"t": "Модуль 10 · 3. Три эталонных разбора реальных типов задания № 31", "x": "**Шаг 1.** **Кейс 1 (разложение нитрата + амфотерность + комплекс):** *«Нитрат алюминия прокалили до постоянной массы. Твёрдый остаток сплавили с карбонатом натрия. Полученную соль растворили в избытке соляной кислоты. К образовавшемуся раствору добавили избыток раствора сульфида натрия.»*\n**Шаг 2.** **Реакция 1 (разложение нитрата группы Mg–Cu):** 4Al(NO3)3 —t°→ 2Al2O3 + 12NO2↑ + 3O2↑. Проверяем O: слева 4·9 = 36, справа 2·3 + 12·2 + 3·2 = 6 + 24 + 6 = 36.\n**Шаг 3.** **Реакция 2 (сплавление амфотерного оксида с карбонатом):** Al2O3 + Na2CO3 —сплавление→ 2NaAlO2 + CO2↑. Проверяем O: 3 + 3 = 6 и 4 + 2 = 6.\n**Шаг 4.** **Реакция 3 (метаалюминат + избыток HCl → две соли, осадок Al(OH)3 растворяется!):** NaAlO2 + 4HCl(изб.) → AlCl3 + NaCl + 2H2O. Проверяем H: 4 и 4, O: 2 и 2.…"}, "10.8": {"t": "Модуль 10 · 3. Три эталонных разбора реальных типов задания № 31", "x": "**Шаг 1.** **Кейс 2 (железо + осаждение + окисление на воздухе + ОВР с HI):** *«Железные опилки растворили в соляной кислоте. К полученному раствору добавили раствор гидроксида натрия, при этом выпал серо-зелёный осадок. Влажный осадок оставили на воздухе до полного побурения. Побуревший осадок растворили в растворе иодоводородной кислоты.»*\n**Шаг 2.** **Реакция 1 (неокисляющая кислота → Fe(+2)):** Fe + 2HCl → FeCl2 + H2↑.\n**Шаг 3.** **Реакция 2 (осаждение гидроксида железа(II)):** FeCl2 + 2NaOH → Fe(OH)2↓ + 2NaCl.\n**Шаг 4.** **Реакция 3 (окисление влажного Fe(OH)2 кислородом воздуха до бурого Fe(OH)3):** 4Fe(OH)2 + O2 + 2H2O → 4Fe(OH)3. Проверяем O: 4·2 + 2 + 2 = 12 и 4·3 = 12.\n**Шаг 5.** **Реакция 4 (ОВР Fe(OH)3 + HI, НЕ обмен!):** 2Fe(OH)3 + 6HI → 2FeI2 + I2↓ + 6H2O. Баланс: 2Fe^{+3} + 2e⁻ → 2Fe^{+2}; 2I^{−1} − 2e⁻ → I2⁰. Проверяем H: 2·3 + 6 = 12 и 6·2 = 12; O: 6 и 6; I: 6 и 4 + 2 = 6. Чистые **4/4 балла**!"}, "10.9": {"t": "Модуль 10 · 3. Три эталонных разбора реальных типов задания № 31", "x": "**Шаг 1.** **Кейс 3 (неметаллы: кремний + щёлочь + CO2 + HF):** *«Кремний растворили в горячем растворе гидроксида натрия. Через полученный раствор пропустили избыток углекислого газа. Выпавший студенистый осадок отфильтровали и прокалили. Полученный твёрдый оксид обработали плавиковой кислотой.»*\n**Шаг 2.** **Реакция 1 (Si + щёлочь):** Si + 2NaOH(водн.) + H2O —t°→ Na2SiO3 + 2H2↑.\n**Шаг 3.** **Реакция 2 (избыток CO2 → кислая соль NaHCO3!):** Na2SiO3 + 2CO2(изб.) + 2H2O → H2SiO3↓ + 2NaHCO3. Проверяем O: 3 + 4 + 2 = 9 и 3 + 6 = 9.\n**Шаг 4.** **Реакция 3 (прокаливание H2SiO3):** H2SiO3 —t°→ SiO2 + H2O.\n**Шаг 5.** **Реакция 4 (травление SiO2 плавиковой кислотой):** SiO2 + 4HF → SiF4↑ + 2H2O. Проверяем O: 2 и 2, F: 4 и 4. Чистые **4/4 балла**!"}, "10.10": {"t": "Модуль 10 · Главная причина потери 1 балла в № 31", "x": "В Кейсе 3 посмотри на реакцию 2: «пропустили **избыток** углекислого газа»! Если написать Na2SiO3 + CO2 + H2O → H2SiO3↓ + Na2CO3, эксперт ФИПИ поставит **0 баллов** за эту реакцию, потому что при избытке CO2 карбонат обязан перейти в гидрокарбонат NaHCO3. Всегда подчёркивай в черновике слова «избыток», «недостаток», «концентрированная», «разбавленная», «сплавили», «прокалили»!"}}, "_kt": "Неорганика металлов и неметаллов: задания № 6–9 и № 31 ЕГЭ", "_mods": {"01": "Логика неорганических реакций и способы получения металлов", "02": "Активные металлы: Na, K, Ca, Mg и их соединения", "03": "Амфотерные металлы: Al и Zn, их оксиды, гидроксиды и комплексы", "04": "Переходные металлы: Fe, Cr, Cu и их соединения", "05": "Галогены (F2, Cl2, Br2, I2) и их соединения", "06": "Сера и её соединения: от сульфидов до концентрированной H2SO4", "07": "Азот, аммиак, оксиды азота, азотная кислота и разложение нитратов", "08": "Фосфор, углерод, кремний и их соединения", "09": "Задания № 6, 7, 8, 9 КИМ: алгоритмы отбора реагентов и генетические цепочки", "10": "Задание № 31 КИМ: мысленный эксперимент из 4 реакций на 4/4 балла"}, "_skm": {"metallurgy_logic": ["01"], "active_metals": ["02"], "amphoteric_al_zn": ["03"], "transition_fe_cr_cu": ["04"], "halogens": ["05"], "sulfur_compounds": ["06"], "nitrogen_nitrates": ["07"], "p_c_si_compounds": ["08"], "kim6_9_algorithms": ["09"], "kim31_experiment": ["10"]}, "_fig": []};
